window.QUESTION_BANK = {"1": {"ch": 1, "chapter": "Basics of Derivatives", "q": "A contract's value moves only because the price of crude oil moves. Which statement best describes this contract?", "options": ["It is a money market instrument because it has a short maturity", "It is a cash market product because oil is a physical commodity", "It is a derivative because its value is derived from an underlying asset", "It is a debt instrument because it has a fixed settlement date"], "answer": 2, "why": ["The workbook defines a derivative as a contract or product whose value is derived from the value of some other asset, called the underlying. The test is always: where does the value come from?", "Key point: A derivative has no stand-alone value; its value is \"derived\" from the underlying (here, crude oil). Maturity or settlement date does not make it a debt or money market instrument."], "reasons": ["Maturity length does not decide the category; the value here comes from oil, not from lending money", "Value moves only because the oil price moves, so it is derived from an underlying asset", "Oil is only the underlying; the contract itself is not a spot purchase of oil", "A fixed settlement date is a feature of forwards/futures too; there is no borrowing or lending, so it is not debt"], "notes": ["⚠️ Important: Do not get distracted by features like maturity or settlement date. Ask only whether the value depends on another asset.", "Easy way to remember: No underlying, no derivative."], "id": 1}, "2": {"ch": 1, "chapter": "Basics of Derivatives", "q": "Which of the following is NOT listed as a category of underlying for derivatives in the NISM workbook?", "options": ["Metals such as copper and zinc", "Energy resources such as electricity and natural gas", "Human capital such as employee skills", "Financial assets such as bonds and foreign exchange"], "answer": 2, "why": ["The workbook lists four groups of underlyings: metals, energy resources, agri commodities and financial assets (shares, bonds, foreign exchange).", "Key point: The workbook lists metals, energy, agri commodities and financial assets (shares, bonds, forex). Employee skills cannot be priced or delivered and are not a derivative underlying."], "reasons": ["Metals (gold, silver, aluminium, copper, zinc, nickel, tin, lead) are listed", "Energy (oil, coal, electricity, natural gas) is listed", "Employee skills are not in the workbook list and cannot be priced or traded as an underlying", "Financial assets (shares, bonds, forex) are listed"], "notes": ["Easy way to remember: Four buckets: Metals, Energy, Agri, Financial — \"MEAF\"."], "id": 2}, "3": {"ch": 1, "chapter": "Basics of Derivatives", "q": "English Cistercian monasteries in the 13th century sold wool to foreign merchants up to how many years in advance?", "options": ["20 years", "5 years", "10 years", "15 years"], "answer": 0, "why": ["Under \"Derivatives Market – History & Evolution\", the workbook notes that 13th-century English Cistercian monasteries sold wool to foreign merchants up to 20 years in advance — an early forward.", "Key point: The workbook cites Cistercian monasteries frequently selling wool up to 20 years in advance — an early form of forward contract."], "reasons": ["The workbook says \"up to 20 years in advance\"", "5 years is not the figure given", "10 years is not the figure given", "15 years is not the figure given"], "notes": ["Easy way to remember: 13th century monks → 20 years ahead."], "id": 3}, "4": {"ch": 1, "chapter": "Basics of Derivatives", "q": "The Dojima rice futures market in the late 17th century was developed mainly to:", "options": ["Allow speculators to profit from rice price swings", "Protect rice producers from bad weather or warfare", "Help the government collect rice tax in advance", "Enable arbitrage between Osaka and Tokyo markets"], "answer": 1, "why": ["The workbook states that in the late 17th century a rice futures market was developed at Dojima, near Osaka, to protect rice producers from bad weather or warfare. That is a hedging purpose.", "Key point: Dojima (near Osaka) was set up to protect rice producers from bad weather or warfare — a hedging motive."], "reasons": ["Speculation is not the purpose the workbook gives", "Protection of producers from weather/warfare is exactly the stated purpose", "Tax collection is not mentioned", "Arbitrage between cities is not mentioned"], "notes": ["Easy way to remember: Dojima = farmers' insurance against weather and war."], "id": 4}, "5": {"ch": 1, "chapter": "Basics of Derivatives", "q": "Arrange correctly: (i) CBOT lists first \"exchange traded\" futures, (ii) CBOE becomes first marketplace for listed options, (iii) Kansas City Board of Trade launches first stock index futures, (iv) CME introduces IMM for currency futures.", "options": ["(i) → (ii) → (iv) → (iii)", "(iv) → (i) → (ii) → (iii)", "(i) → (iv) → (ii) → (iii)", "(i) → (iv) → (iii) → (ii)"], "answer": 2, "why": ["Workbook timeline: 1865 CBOT lists first exchange-traded futures; 1972 CME introduces IMM (currency futures); 1973 CBOE becomes the first listed options market; 1982 Kansas City Board of Trade launches first stock index futures.", "Key point: CBOT futures 1865 → IMM currency futures 1972 → CBOE listed options 1973 → first stock index futures 1982."], "reasons": ["Puts CBOE (1973) before IMM (1972) — wrong", "Starts with IMM (1972) before CBOT futures (1865) — wrong", "Correct order: 1865 → 1972 → 1973 → 1982. CBOT futures 1865 → IMM currency futures 1972 → CBOE listed options 1973 → first stock index futures 1982.", "Puts index futures (1982) before CBOE options (1973) — wrong"], "notes": ["⚠️ Important: 1972 and 1973 are one year apart — the most common slip is swapping IMM and CBOE.", "Easy way to remember: \"65-72-73-82\": futures, currency, options, index."], "id": 5}, "6": {"ch": 1, "chapter": "Basics of Derivatives", "q": "The first successful pure interest rate futures contract was:", "options": ["T-bond futures introduced by CBOT in 1977", "Eurodollar futures introduced by CME in 1982", "Currency futures on IMM in 1972", "Treasury bill futures introduced by CBOT in 1975"], "answer": 3, "why": ["The workbook says CBOT introduced Treasury bill futures in 1975, the first successful pure interest rate futures. T-bond futures came in 1977 and Eurodollar futures in 1982.", "Key point: The workbook states the 1975 CBOT T-bill futures was the first successful pure interest rate futures. T-bond (1977) and Eurodollar (1982) came later."], "reasons": ["T-bond futures came later, in 1977", "Eurodollar futures came in 1982", "IMM (1972) was for currency futures, not interest rates", "Treasury bill futures (CBOT, 1975) — the first successful pure interest rate futures"], "notes": ["Easy way to remember: Bill before Bond: T-bill 1975, T-bond 1977."], "id": 6}, "7": {"ch": 1, "chapter": "Basics of Derivatives", "q": "In 1983, CBOE introduced options on which stock indices?", "options": ["Dow Jones and Nasdaq 100", "Nikkei 225 and S&P 500", "S&P 100 (OEX) and S&P 500 (SPX)", "Value Line and S&P 100"], "answer": 2, "why": ["The workbook states that in 1983 CBOE introduced options on stock indices with the S&P 100 (OEX) and S&P 500 (SPX) indices.", "Key point: In 1983 CBOE introduced index options on the S&P 100 (OEX) and S&P 500 (SPX)."], "reasons": ["Dow Jones and Nasdaq 100 are not mentioned", "Nikkei 225 is a Japanese index; not mentioned here", "S&P 100 (OEX) and S&P 500 (SPX) — exactly as in the workbook", "Value Line is not mentioned"], "notes": ["Easy way to remember: 1983 CBOE = \"S&P twins\": 100 and 500."], "id": 7}, "8": {"ch": 1, "chapter": "Basics of Derivatives", "q": "The Tulip Mania in Holland (1634–1637) is significant in derivatives history because:", "options": ["Fortunes were lost when a speculative boom in tulip futures burst", "It marked the launch of the first exchange-traded options", "It led to the formation of the Chicago Board of Trade", "It introduced the concept of mark-to-market margining"], "answer": 0, "why": ["The workbook lists 1634–1637 Tulip Mania in Holland: fortunes were lost after a speculative boom in tulip futures burst. It shows speculation risk, not a product launch.", "Key point: Tulip Mania is cited as an early speculative bubble in tulip futures that burst, wiping out fortunes."], "reasons": ["Listed options came much later (CBOE, 1973). Tulip Mania is cited as an early speculative bubble in tulip futures that burst, wiping out fortunes.", "Correct — a speculative boom in tulip futures burst", "CBOT came in 1848, unrelated to Holland", "Mark-to-market is a modern exchange feature, not from Tulip Mania"], "notes": ["Easy way to remember: Tulip Mania = the first famous bubble."], "id": 8}, "9": {"ch": 1, "chapter": "Basics of Derivatives", "q": "Which of the following is NOT a factor cited for the global growth of financial derivatives?", "options": ["Increased fluctuations in underlying asset prices", "Integration of financial markets globally", "Fixed exchange rate regimes reducing currency volatility", "Reduction in transaction costs through technology"], "answer": 2, "why": ["Growth factors listed: increased price fluctuations, global integration of markets, lower transaction costs via technology, better understanding of risk tools, and frequent innovation.", "Key point: Derivatives grow when volatility rises, not when it is suppressed. Fixed exchange rates reduce the need to hedge. The other three are listed growth drivers."], "reasons": ["Increased fluctuations are listed — volatility creates hedging demand", "Global integration of markets is listed", "Fixed exchange rates reduce volatility and hedging need — not a growth factor", "Technology reducing transaction costs is listed"], "notes": ["⚠️ Important: Anything that REDUCES price volatility would reduce, not increase, derivative demand.", "Easy way to remember: Derivatives feed on volatility."], "id": 9}, "10": {"ch": 1, "chapter": "Basics of Derivatives", "q": "The L.C. Gupta Committee on derivatives was set up by SEBI on:", "options": ["March 17, 1998", "June 12, 2000", "November 18, 1996", "May 11, 1998"], "answer": 2, "why": ["SEBI set up a 24-member committee under Dr L.C. Gupta on November 18, 1996. It reported on March 17, 1998; SEBI accepted the recommendations on May 11, 1998.", "Key point: Committee set up on November 18, 1996 (24 members); report submitted March 17, 1998; SEBI accepted recommendations on May 11, 1998."], "reasons": ["March 17, 1998 — date the report was submitted", "June 12, 2000 is around when trading began, not the committee date", "November 18, 1996 — date the committee was set up", "May 11, 1998 — date SEBI accepted the recommendations"], "notes": ["⚠️ Important: Three dates, three events: set up (1996), report (Mar 1998), acceptance (May 1998).", "Easy way to remember: Gupta: '96 set up, '98 report."], "id": 10}, "11": {"ch": 1, "chapter": "Basics of Derivatives", "q": "The L.C. Gupta Committee was a ___ member committee that recommended derivatives be declared as ___.", "options": ["24; securities", "12; commodities", "24; contracts for differences", "18; foreign exchange instruments"], "answer": 0, "why": ["The workbook: a 24-member committee that recommended derivatives be declared \"securities\" so the regulatory framework applicable to securities could govern derivatives.", "Key point: It was a 24-member committee that recommended derivatives be declared \"securities\" so the securities regulatory framework would apply."], "reasons": ["24 members; recommended derivatives be declared securities", "12 is wrong; commodities is not the recommendation", "Contracts for differences was not the recommendation", "18 members and forex are both wrong"], "notes": ["Easy way to remember: 24 members → \"securities\"."], "id": 11}, "12": {"ch": 1, "chapter": "Basics of Derivatives", "q": "The J.R. Varma group, set up in June 1998, primarily worked on:", "options": ["Taxation of derivative profits", "Accounting standards for futures", "Eligibility of stocks for derivatives trading", "Risk containment measures such as margining methodology and net-worth criteria"], "answer": 3, "why": ["SEBI set up a group under Prof. J.R. Varma in June 1998 (report October 1998) to recommend risk containment measures — margining system, initial margin methodology, membership, net-worth, deposits and real-time position monitoring.", "Key point: Prof. J.R. Varma's group (report October 1998) worked out operational details of margining, membership, net-worth criteria, deposits and real-time position monitoring."], "reasons": ["Taxation was not its mandate", "Accounting was handled by ICAI guidance notes, not this group", "Stock eligibility criteria is a later SEBI framework", "Risk containment/margining — its actual mandate"], "notes": ["Easy way to remember: Gupta = framework; Varma = risk/margins."], "id": 12}, "13": {"ch": 1, "chapter": "Basics of Derivatives", "q": "The SCRA was amended to include derivatives within the definition of \"securities\" in:", "options": ["1996", "1998", "2001", "1999"], "answer": 3, "why": ["The workbook: in 1999 SCRA was amended to include derivatives within \"securities\". In March 2000 the government repealed the three-decade-old notification prohibiting forward trading in securities.", "Key point: SCRA was amended in 1999. In March 2000, the government repealed the three-decade-old notification prohibiting forward trading in securities."], "reasons": ["1996 is when the Gupta committee was set up", "1998 is when the report came", "2001 is when options/stock futures started", "1999 — SCRA amendment year. SCRA was amended in 1999."], "notes": ["Easy way to remember: '96 committee → '98 report → '99 law → 2000 trading."], "id": 13}, "14": {"ch": 1, "chapter": "Basics of Derivatives", "q": "Which is the correct chronology of equity derivatives introduction in India?", "options": ["Stock futures → Index futures → Index options → Stock options", "Index futures → Stock options → Index options → Stock futures", "Index options → Index futures → Stock futures → Stock options", "Index futures → Index options → Stock options → Stock futures"], "answer": 3, "why": ["The workbook: index futures (June 2000), index options (June 2001), stock options (July 2001), stock futures (November 2001).", "Key point: Index futures (June 2000) → Index options (June 2001) → Stock options (July 2001) → Stock futures (November 2001)."], "reasons": ["Stock futures came last, not first", "Stock options (July 2001) came after index options (June 2001)", "Index futures came before index options", "Correct sequence. Index futures (June 2000) → Index options (June 2001) → Stock options (July 2001) → Stock futures (November 2001)."], "notes": ["⚠️ Important: In stocks, options came BEFORE futures; in indices, futures came before options.", "Easy way to remember: Index-F, Index-O, Stock-O, Stock-F."], "id": 14}, "15": {"ch": 1, "chapter": "Basics of Derivatives", "q": "Stock futures in India were launched in November 2001. Which product preceded it by only about four months?", "options": ["Index futures", "Stock options", "Index options", "Currency futures"], "answer": 1, "why": ["Stock options began in July 2001; stock futures in November 2001 — about four months later.", "Key point: Stock options began in July 2001, about four months before stock futures (November 2001)."], "reasons": ["Index futures began June 2000, about 17 months earlier", "Stock options, July 2001 — about four months earlier", "Index options began June 2001, about five months earlier", "Currency futures are not part of this sequence"], "notes": ["Easy way to remember: July options, November futures for stocks."], "id": 15}, "16": {"ch": 1, "chapter": "Basics of Derivatives", "q": "Metropolitan Stock Exchange of India (MSEI) started trading in derivative products in:", "options": ["June 2000", "November 2001", "October 2019", "February 2013"], "answer": 3, "why": ["The workbook states MSEI started trading in derivative products in February 2013.", "Key point: The workbook states MSEI began derivatives trading in February 2013."], "reasons": ["June 2000 is when NSE/BSE index futures started", "November 2001 is stock futures", "October 2019 is when physical settlement of stock F&O began", "February 2013 — MSEI derivatives launch. The workbook states MSEI began derivatives trading in February 2013."], "notes": ["Easy way to remember: MSEI = 2013."], "id": 16}, "17": {"ch": 1, "chapter": "Basics of Derivatives", "q": "Which feature is common to BOTH forwards and futures?", "options": ["Standardised lot size fixed by the exchange", "Obligation on both parties to honour the contract at a price fixed today", "Daily mark-to-market settlement", "Clearing corporation guarantee"], "answer": 1, "why": ["Both are agreements to buy/sell at a future date at a price fixed today, and both parties are obliged to honour them. Standardisation, daily MTM and clearing guarantee belong to futures only.", "Key point: In both, both parties are obligated and the price is fixed at inception. Standardisation, daily MTM and clearing guarantee exist only for futures."], "reasons": ["Standardised lot size applies to futures only; forwards are tailor-made", "Common feature: binding obligation on both sides at a price fixed today", "Daily MTM applies only to futures", "Clearing corporation guarantee applies only to futures"], "notes": ["Easy way to remember: Forward and future share the promise; futures add the exchange."], "id": 17}, "18": {"ch": 1, "chapter": "Basics of Derivatives", "q": "A swap is best described as:", "options": ["A single forward contract settled in cash", "An option to exchange one asset for another", "A futures contract on interest rates", "A series of forward contracts to exchange cash flows according to a prearranged formula"], "answer": 3, "why": ["The workbook: a swap is an agreement between two parties to exchange cash flows in the future according to a prearranged formula; broadly, a series of forward contracts.", "Key point: The workbook describes swaps as broadly a series of forward contracts exchanging future cash flows by a prearranged formula."], "reasons": ["A swap involves many cash flows, not one", "An option is a right; a swap is an obligation", "Swaps can be on interest rates, currencies or commodities; they are not futures", "Correct — a series of forwards exchanging cash flows by a formula"], "notes": ["Easy way to remember: Swap = string of forwards."], "id": 18}, "19": {"ch": 1, "chapter": "Basics of Derivatives", "q": "An option writer:", "options": ["Pays the premium and receives a right", "Pays the premium and takes on an obligation", "Receives the premium and takes on an obligation", "Receives the premium and receives a right"], "answer": 2, "why": ["The buyer pays the premium and gets the right. The writer/seller receives the premium and has the obligation to buy/sell if the buyer exercises.", "Key point: The writer (seller) receives the premium and is obligated to buy/sell if the buyer exercises. The buyer pays for the right."], "reasons": ["This describes the option buyer", "Nobody pays a premium and also takes an obligation", "Writer: receives premium, takes obligation. The writer (seller) receives the premium and is obligated to buy/sell if the buyer exercises.", "Nobody receives premium and also gets a right"], "notes": ["Easy way to remember: Writer = \"wage earner\" — paid premium, must perform."], "id": 19}, "20": {"ch": 1, "chapter": "Basics of Derivatives", "q": "A textile exporter expecting dollar receipts in 3 months sells USD forward. In this transaction, the exporter is acting as a:", "options": ["Hedger", "Speculator", "Arbitrageur", "Market maker"], "answer": 0, "why": ["Hedgers face risk from the underlying's price and use derivatives to reduce it. The exporter already has dollar receivables; selling USD forward locks the rate.", "Key point: The exporter already faces currency risk and uses a derivative to reduce it — the definition of a hedger."], "reasons": ["Hedger — reduces an existing currency risk. The exporter already faces currency risk and uses a derivative to reduce it — the definition of a hedger.", "A speculator has no underlying exposure; the exporter does", "Arbitrage exploits a price gap between markets; none here", "Market maker is not one of the three participant types in the workbook"], "notes": ["Easy way to remember: Existing exposure + derivative to reduce it = hedge."], "id": 20}, "21": {"ch": 1, "chapter": "Basics of Derivatives", "q": "Why do speculators generally prefer derivatives over the underlying for trading?", "options": ["Derivatives offer leverage, lower transaction cost and faster execution in size", "Derivatives carry no risk of loss", "Derivatives are not regulated by SEBI", "Derivatives always trade at a discount to spot"], "answer": 0, "why": ["The workbook: derivatives are preferred for trading because they offer leverage, are less expensive (lower transaction cost) and are faster to execute in size (high volumes).", "Key point: The workbook lists leverage, lower cost and ability to execute in size quickly as reasons speculators prefer derivatives."], "reasons": ["Correct — leverage, lower cost, faster execution in size", "Derivatives are leveraged and can cause large losses", "Derivatives are regulated by SEBI", "Futures can trade at a premium or discount to spot"], "notes": ["Easy way to remember: Speculators love L-C-S: Leverage, Cost, Size."], "id": 21}, "22": {"ch": 1, "chapter": "Basics of Derivatives", "q": "Arbitrage opportunities are \"unlikely to persist for very long\" because:", "options": ["SEBI bans arbitrage after a few days", "Exchanges suspend trading when prices diverge", "Arbitrage requires physical delivery which takes time", "Arbitrageurs rush in and their trading closes the price gap"], "answer": 3, "why": ["The workbook: arbitrageurs rush into such transactions, buying in the cheaper market and selling in the dearer one, which closes the price gap.", "Key point: Buying in the cheap market and selling in the expensive one pushes prices together until the gap disappears."], "reasons": ["SEBI does not ban arbitrage", "Exchanges do not suspend trading because of price differences", "Physical delivery is not the reason", "Correct — arbitrage trading itself closes the gap"], "notes": ["Easy way to remember: Arbitrage kills itself."], "id": 22}, "23": {"ch": 1, "chapter": "Basics of Derivatives", "q": "Which statement about market participants is correct?", "options": ["A person can only be a hedger or a speculator for life", "Arbitrageurs always take naked positions", "Hedgers need no counterparty", "An individual may play different roles in different market circumstances"], "answer": 3, "why": ["The workbook says there are three types of participants — hedgers, traders and arbitrageurs — and an individual may play different roles in different market circumstances.", "Key point: The workbook explicitly states an individual may act as hedger, trader or arbitrageur depending on circumstances. Arbitrageurs lock in profit (not naked), and hedgers need traders as counterparties."], "reasons": ["Roles are not fixed for life", "Arbitrageurs lock in profits; they don't take naked positions", "Hedgers need traders as counterparties", "Correct, stated directly in the workbook. The workbook explicitly states an individual may act as hedger, trader or arbitrageur depending on circumstances."], "notes": ["Easy way to remember: Same person, different hats."], "id": 23}, "24": {"ch": 1, "chapter": "Basics of Derivatives", "q": "In OTC derivatives markets, the management of counterparty credit risk is:", "options": ["Centralised with the clearing corporation", "Guaranteed by SEBI", "Handled through the Settlement Guarantee Fund", "Decentralised and located within individual institutions"], "answer": 3, "why": ["Among OTC features the workbook lists: \"the management of counter-party (credit) risk is decentralized and located within individual institutions\".", "Key point: OTC credit risk management is decentralised within each institution; there is no central counterparty."], "reasons": ["A central clearing corporation is a feature of exchange-traded contracts", "SEBI does not guarantee OTC deals", "The Settlement Guarantee Fund covers exchange trades only", "Correct — decentralised, within each institution"], "notes": ["Easy way to remember: OTC = Own-Treasury Control of credit risk."], "id": 24}, "25": {"ch": 1, "chapter": "Basics of Derivatives", "q": "Which of the following is NOT a feature of OTC derivative transactions?", "options": ["Contracts are tailor-made", "No formal centralised limits on positions or leverage", "Prices determined through an anonymous auction platform", "Transactions are private with little disclosure"], "answer": 2, "why": ["OTC features: tailor-made contracts, decentralised credit risk, no formal centralised limits, no formal risk management rules, private transactions. Anonymous auction pricing is an exchange feature.", "Key point: Anonymous auction platforms characterise exchange-traded derivatives. OTC deals are negotiated bilaterally."], "reasons": ["Tailor-made contracts are an OTC feature", "No centralised limits is an OTC feature", "Anonymous auction platform is an exchange-traded feature — not OTC", "Private transactions with little disclosure is an OTC feature"], "notes": ["Easy way to remember: Anonymous auction = Exchange."], "id": 25}, "26": {"ch": 1, "chapter": "Basics of Derivatives", "q": "The OTC market is best described as:", "options": ["A physical trading floor where dealers meet", "A collection of broker-dealers linked by telephone/electronic networks, more a way of doing business than a place", "A segment of NSE for unlisted securities", "A market run by RBI for government bonds only"], "answer": 1, "why": ["The workbook: the OTC market is not a physical marketplace but a collection of broker-dealers linked by telephone/electronic networks — \"more a way of doing business than a place\".", "Key point: The workbook describes OTC as not a physical marketplace but a network of broker-dealers — \"more a way of doing business than a place\"."], "reasons": ["There is no trading floor in OTC", "Correct — a network, a way of doing business. The workbook describes OTC as not a physical marketplace but a network of broker-dealers — \"more a way of doing business than a place\".", "It is not an NSE segment", "It is not run by RBI"], "notes": ["Easy way to remember: OTC = a web, not a building."], "id": 26}, "27": {"ch": 1, "chapter": "Basics of Derivatives", "q": "Why is the OTC derivatives market described as \"less regulated\"?", "options": ["Because OTC contracts are illegal in India", "Because transactions occur privately among qualified counterparties presumed capable of protecting themselves", "Because SEBI has no jurisdiction over banks", "Because OTC contracts have no underlying asset"], "answer": 1, "why": ["The workbook: OTC is less regulated because transactions occur privately among qualified counterparties who are supposed to be capable of protecting themselves.", "Key point: OTC deals happen privately among sophisticated counterparties who are supposed to be capable of protecting themselves."], "reasons": ["OTC contracts are not illegal", "Correct — private deals among sophisticated parties", "SEBI's jurisdiction over banks is not the reason", "OTC contracts do have underlyings"], "notes": ["Easy way to remember: Grown-ups' market — expected to look after themselves."], "id": 27}, "28": {"ch": 1, "chapter": "Basics of Derivatives", "q": "In exchange-traded derivatives, who guarantees contract performance?", "options": ["The trading member", "The buyer's bank", "The clearing corporation", "SEBI"], "answer": 2, "why": ["The workbook: in exchange-traded contracts, \"a clearing corporation guarantees contract performance (settlement of transactions)\".", "Key point: The clearing corporation guarantees settlement of exchange-traded contracts."], "reasons": ["A trading member does not guarantee settlement", "A bank does not guarantee", "Clearing corporation — guarantees settlement via novation", "SEBI regulates but does not guarantee trades"], "notes": ["Easy way to remember: CC = Central Counterparty."], "id": 28}, "29": {"ch": 1, "chapter": "Basics of Derivatives", "q": "Which of the following is NOT a function served by the derivatives market?", "options": ["Improving price discovery", "Transferring risk from risk-averse participants to those willing to bear it", "Shifting speculative trades from unorganised to organised markets", "Guaranteeing profits to hedgers"], "answer": 3, "why": ["Functions listed: improving price discovery, transferring risk, and shifting speculation from unorganised to organised markets.", "Key point: Hedgers reduce risk; they are not guaranteed profits. The other three are listed functions of derivatives markets."], "reasons": ["Price discovery is a listed function", "Risk transfer is a listed function", "Shifting speculation to organised markets is a listed function", "Guaranteeing profits is never a function; hedging only reduces risk"], "notes": ["Easy way to remember: Derivatives transfer risk; they don't guarantee profit."], "id": 29}, "30": {"ch": 1, "chapter": "Basics of Derivatives", "q": "\"Hedgers want to give away risk whereas traders are willing to take risk.\" This statement illustrates which function of derivatives?", "options": ["Risk transfer", "Price discovery", "Liquidity creation", "Capital formation"], "answer": 0, "why": ["This line appears in the workbook under the risk-transfer function: risk moves from those with low risk appetite to those with high risk appetite.", "Key point: Derivatives transfer risk from those with low risk appetite (hedgers) to those with high risk appetite (traders)."], "reasons": ["Correct — risk transfer. Derivatives transfer risk from those with low risk appetite (hedgers) to those with high risk appetite (traders).", "Price discovery is about finding fair prices, not moving risk", "Liquidity creation is not the function named here", "Capital formation is not a listed derivative function"], "notes": ["Easy way to remember: Hedger hands the hot potato to the trader."], "id": 30}, "31": {"ch": 1, "chapter": "Basics of Derivatives", "q": "Shifting speculative trades from the unorganised to the organised market contributes to financial stability mainly because:", "options": ["Organised markets have no speculation", "Organised markets offer guaranteed returns", "Speculative trades become tax-free", "Risk management mechanisms and surveillance in the organised space monitor participants"], "answer": 3, "why": ["The workbook: shifting speculation to the organised market helps because risk management and surveillance of participants there provide stability to the financial system.", "Key point: The organised market brings risk management and surveillance, which provide stability to the financial system."], "reasons": ["Organised markets still have speculation", "No guaranteed returns", "Speculative trades are not tax-free", "Correct — risk management and surveillance. The organised market brings risk management and surveillance, which provide stability to the financial system."], "notes": ["Easy way to remember: Organised = watched."], "id": 31}, "32": {"ch": 1, "chapter": "Basics of Derivatives", "q": "A client cannot exit a position because there are no buyers in a deep OTM stock option near expiry. This is:", "options": ["Counterparty risk", "Liquidity risk", "Operational risk", "Legal risk"], "answer": 1, "why": ["Workbook risk list: counterparty risk (default), price risk (adverse move), liquidity risk (inability to exit), legal/regulatory risk (enforceability), operational risk (fraud, documentation, execution).", "Key point: Liquidity risk is the inability to exit a position."], "reasons": ["Counterparty risk is about default, not exiting", "Liquidity risk — inability to exit a position", "Operational risk is about processes and people", "Legal risk is about enforceability"], "notes": ["Easy way to remember: Can't get out = Liquidity."], "id": 32}, "33": {"ch": 1, "chapter": "Basics of Derivatives", "q": "A contract becomes unenforceable because a court rules the counterparty lacked authority to sign it. This is an example of:", "options": ["Price risk", "Liquidity risk", "Market risk", "Legal or regulatory risk"], "answer": 3, "why": ["The workbook defines legal or regulatory risk as risk relating to the enforceability of contracts.", "Key point: Legal/regulatory risk relates to the enforceability of contracts."], "reasons": ["Price risk is loss from adverse price moves", "Liquidity risk is inability to exit", "Market risk is price movement", "Correct — enforceability is legal/regulatory risk"], "notes": ["Easy way to remember: Court problem = Legal risk."], "id": 33}, "34": {"ch": 1, "chapter": "Basics of Derivatives", "q": "Losses arising from fraud, inadequate documentation or improper execution fall under:", "options": ["Counterparty risk", "Systematic risk", "Basis risk", "Operational risk"], "answer": 3, "why": ["The workbook lists operational risk as \"fraud, inadequate documentation, improper execution, etc.\"", "Key point: The workbook groups fraud, inadequate documentation and improper execution under operational risk."], "reasons": ["Counterparty risk is default by the other party", "Systematic risk is market-wide price risk", "Basis risk is not the category the workbook uses here", "Correct — operational risk. The workbook groups fraud, inadequate documentation and improper execution under operational risk."], "notes": ["Easy way to remember: Ops risk = People, Process, Paperwork."], "id": 34}, "35": {"ch": 1, "chapter": "Basics of Derivatives", "q": "Which of the following is an operational risk?", "options": ["The broker's disaster recovery plan fails during a system outage", "The counterparty defaults on payment", "The Nifty falls 3% in a day", "The option expires worthless"], "answer": 0, "why": ["Operational risk arises from failures of internal processes or systems. The workbook's sample question lists \"inadequate disaster planning\" as an operational risk.", "Key point: Failure of processes/systems such as inadequate disaster planning is operational risk."], "reasons": ["Failed disaster recovery is an operational failure", "Counterparty default is counterparty risk", "A market fall is price/market risk", "An option expiring worthless is the buyer's normal price risk"], "notes": ["Easy way to remember: Systems down = Operational."], "id": 35}, "36": {"ch": 1, "chapter": "Basics of Derivatives", "q": "The Model Risk Disclosure Document is:", "options": ["Issued by SEBI to listed companies", "Filed by clients with the clearing corporation", "Issued by members of exchanges and should be read by prospective participants before trading in cash or F&O", "Only required for institutional investors"], "answer": 2, "why": ["The workbook: a Model Risk Disclosure Document is issued by the members of exchanges and contains important information on trading in equities and F&O. All prospective participants should read it before trading.", "Key point: It is issued by exchange members and contains important information on trading in equities and F&O; all prospective participants should read it."], "reasons": ["It is not issued by SEBI to companies", "Clients do not file it with the clearing corporation", "Correct — issued by exchange members, read before trading", "It applies to all participants, not only institutions"], "notes": ["Easy way to remember: Read the RDD before you trade."], "id": 36}, "37": {"ch": 1, "chapter": "Basics of Derivatives", "q": "Derivatives \"may not be an appropriate avenue\" for which of the following, according to the workbook?", "options": ["Someone with limited resources, limited trading experience or low risk tolerance", "A corporate treasury hedging currency exposure", "A mutual fund hedging its portfolio", "A bank managing interest rate risk"], "answer": 0, "why": ["The workbook warns that derivatives, being leveraged, \"may not be an appropriate avenue for someone of limited resources, or having limited trading experience, or with low risk tolerance\".", "Key point: Because derivatives are leveraged, the workbook cautions that they may not suit those with limited resources, limited experience or low risk tolerance."], "reasons": ["Correct — exactly the workbook's caution. Because derivatives are leveraged, the workbook cautions that they may not suit those with limited resources, limited experience or low risk tolerance.", "A corporate hedger is a natural user", "A mutual fund hedging is a legitimate use", "A bank managing interest rate risk is a legitimate use"], "notes": ["Easy way to remember: Limited money, experience or nerves → stay away."], "id": 37}, "38": {"ch": 1, "chapter": "Basics of Derivatives", "q": "An index option is a:", "options": ["Debt instrument", "Cash market product", "Money market instrument", "Derivative product"], "answer": 3, "why": ["An index option derives its value from a stock index, so by definition it is a derivative. (This is the workbook's own sample question.)", "Key point: Its value is derived from an index — so it is a derivative product."], "reasons": ["It is not a debt instrument; there is no borrowing", "A cash market product involves immediate settlement of the asset itself", "Money market instruments are short-term debt", "Correct — derivative product. Its value is derived from an index — so it is a derivative product."], "notes": ["Easy way to remember: Index option = derivative of an index."], "id": 38}, "39": {"ch": 1, "chapter": "Basics of Derivatives", "q": "The simultaneous purchase of a share on BSE and sale on NSE to benefit from a price difference is:", "options": ["Hedging", "Speculation", "Mortgage", "Arbitrage"], "answer": 3, "why": ["The workbook defines arbitrage as a deal that profits from a price difference of the same product in two markets — buy cheap in one, sell dear in the other simultaneously.", "Key point: Exploiting a price difference for the same asset across two markets simultaneously is arbitrage."], "reasons": ["Hedging reduces an existing risk", "Speculation takes a directional risk", "Mortgage is unrelated", "Correct — arbitrage. Exploiting a price difference for the same asset across two markets simultaneously is arbitrage."], "notes": ["Easy way to remember: Two markets + same asset + simultaneous = arbitrage."], "id": 39}, "40": {"ch": 1, "chapter": "Basics of Derivatives", "q": "Which pair is correctly matched?", "options": ["Forward — standardised, exchange-traded", "Future — customised, OTC", "Option — right without obligation for the buyer", "Swap — single cash flow exchanged on one date"], "answer": 2, "why": ["Forwards: OTC and customised. Futures: exchange-traded and standardised. Options: the buyer has a right, not an obligation. Swaps: a series of cash flows.", "Key point: Option buyers have a right but not an obligation. Forwards are customised/OTC, futures standardised/exchange-traded, swaps involve a series of cash flows."], "reasons": ["Wrong — forwards are customised and OTC", "Wrong — futures are standardised and exchange-traded", "Correct — option buyer has a right without obligation", "Wrong — a swap involves a series of cash flows"], "notes": ["Easy way to remember: Only the option buyer can walk away."], "id": 40}, "41": {"ch": 1, "chapter": "Basics of Derivatives", "q": "A trader buys Nifty futures purely because he expects the budget to be positive for markets. He holds no Nifty stocks. He is:", "options": ["A speculator/trader", "A hedger", "An arbitrageur", "A market regulator"], "answer": 0, "why": ["Speculators/traders predict future price movements and take positions without any underlying exposure.", "Key point: He takes a directional position based on a view without an underlying exposure — speculation."], "reasons": ["Correct — a directional view with no underlying = speculator", "A hedger would have an existing exposure to protect", "An arbitrageur would lock a price gap", "The regulator is SEBI"], "notes": ["Easy way to remember: View without exposure = speculation."], "id": 41}, "42": {"ch": 1, "chapter": "Basics of Derivatives", "q": "Futures can be described as:", "options": ["Customised options", "OTC swaps", "Deferred cash market trades without margins", "Exchange-traded forward contracts"], "answer": 3, "why": ["The workbook: \"futures are standardised forward contracts that are traded on an exchange\" — \"exchange traded forward contracts\".", "Key point: The workbook says futures are, in effect, exchange-traded (standardised) forward contracts."], "reasons": ["Options are a different product", "Swaps are OTC series of cash flows", "Futures have margins and MTM, unlike cash trades", "Correct — exchange-traded forwards. The workbook says futures are, in effect, exchange-traded (standardised) forward contracts."], "notes": ["Easy way to remember: Futures = Forwards + Exchange."], "id": 42}, "43": {"ch": 1, "chapter": "Basics of Derivatives", "q": "Which risk is largely eliminated for clients in exchange-traded derivatives because of novation?", "options": ["Price risk", "Liquidity risk", "Operational risk", "Counterparty risk"], "answer": 3, "why": ["Through novation the clearing corporation becomes counterparty to every trade and guarantees settlement, so client counterparty risk is largely eliminated.", "Key point: The clearing corporation becomes counterparty to every trade and guarantees settlement, largely eliminating counterparty risk for clients."], "reasons": ["Price risk remains — prices still move", "Liquidity risk remains, especially near expiry", "Operational risk remains", "Correct — counterparty risk is removed by the CC guarantee"], "notes": ["Easy way to remember: Novation neutralises counterparty risk."], "id": 43}, "44": {"ch": 1, "chapter": "Basics of Derivatives", "q": "The Chicago Butter and Egg Board, reorganised in 1919 to allow futures trading, later became:", "options": ["CBOT", "CME", "CBOE", "Kansas City Board of Trade"], "answer": 1, "why": ["The workbook: in 1919 the Chicago Butter and Egg Board, a spin-off of CBOT, was reorganised to allow futures trading; its name was later changed to the Chicago Mercantile Exchange (CME).", "Key point: It was a spin-off of CBOT and was later renamed the Chicago Mercantile Exchange (CME)."], "reasons": ["It was a spin-off of CBOT, not CBOT itself", "Correct — renamed CME. It was a spin-off of CBOT and was later renamed the Chicago Mercantile Exchange (CME).", "CBOE was formed in 1973 for options", "Kansas City Board of Trade launched index futures in 1982"], "notes": ["Easy way to remember: Butter and Eggs became the Merc (CME)."], "id": 44}, "45": {"ch": 1, "chapter": "Basics of Derivatives", "q": "In 1848, the Chicago Board of Trade (CBOT):", "options": ["Listed the first exchange-traded futures", "Launched stock index futures", "Introduced treasury bond futures", "Facilitated trading of forward contracts on commodities"], "answer": 3, "why": ["The workbook: in 1848 CBOT facilitated trading of forward contracts on commodities; in 1865 it listed the first exchange-traded futures.", "Key point: In 1848 CBOT facilitated forward trading; the first exchange-traded futures came in 1865."], "reasons": ["First futures listing was 1865, not 1848", "Stock index futures came in 1982 (Kansas City)", "T-bond futures came in 1977", "Correct — forwards facilitated in 1848. In 1848 CBOT facilitated forward trading; the first exchange-traded futures came in 1865."], "notes": ["Easy way to remember: 1848 forwards, 1865 futures."], "id": 45}, "46": {"ch": 1, "chapter": "Basics of Derivatives", "q": "Which statement about the Indian derivatives market's launch is correct?", "options": ["SEBI first permitted stock futures on BSE only", "Index options commenced before index futures", "NSE alone was permitted to launch derivatives", "Index futures on Nifty and Sensex commenced in June 2000"], "answer": 3, "why": ["SEBI permitted BSE and NSE to introduce equity derivatives; trading in index futures on Nifty and Sensex commenced in June 2000.", "Key point: SEBI permitted BSE and NSE; index futures on Nifty and Sensex began in June 2000."], "reasons": ["Index futures came first, and both exchanges were permitted", "Index futures came before index options", "Both BSE and NSE were permitted", "SEBI permitted BSE and NSE; index futures on Nifty and Sensex began in June 2000."], "notes": ["Easy way to remember: June 2000 — Nifty and Sensex futures."], "id": 46}, "47": {"ch": 1, "chapter": "Basics of Derivatives", "q": "A mutual fund manager, a jeweller hedging gold inventory and a proprietary desk locking a risk-free spread between cash and futures are, respectively:", "options": ["Hedger, hedger, arbitrageur", "Speculator, hedger, arbitrageur", "Hedger, speculator, hedger", "Arbitrageur, hedger, speculator"], "answer": 0, "why": ["Hedgers reduce existing exposure; arbitrageurs lock risk-free profit from mispricing; speculators take naked views.", "Key point: The fund manager (if protecting a portfolio) and jeweller both reduce existing risk — hedgers. Locking a risk-free cash-futures spread is arbitrage."], "reasons": ["Correct — hedger, hedger, arbitrageur. The fund manager (if protecting a portfolio) and jeweller both reduce existing risk — hedgers.", "The fund manager protecting a portfolio is not speculating", "The jeweller is hedging inventory, not speculating", "The fund manager is not doing arbitrage"], "notes": ["Easy way to remember: Protect = hedge; lock a gap = arbitrage."], "id": 47}, "48": {"ch": 1, "chapter": "Basics of Derivatives", "q": "What happens to derivatives market depth if speculators are absent?", "options": ["Nothing — hedgers trade among themselves easily", "Arbitrage profits increase permanently", "Prices become more efficient", "Hedgers may be unable to hedge because natural counterparties with opposite needs rarely match in size and timing"], "answer": 3, "why": ["The workbook: the market's capacity to absorb hedgers' buying/selling depends on traders who act as counterparties. Hedgers may not be able to hedge without traders.", "Key point: Speculators act as counterparties to hedgers and provide depth; without them hedgers may not find takers."], "reasons": ["Hedgers rarely match each other in size and timing", "Arbitrage profits don't rise permanently", "Prices become less, not more, efficient", "Correct — hedgers may be unable to hedge. Speculators act as counterparties to hedgers and provide depth; without them hedgers may not find takers."], "notes": ["Easy way to remember: No speculator, no hedge."], "id": 48}, "49": {"ch": 1, "chapter": "Basics of Derivatives", "q": "Which of the following statements about forwards is FALSE?", "options": ["They are bilateral contracts", "Terms can be altered if both parties agree", "Price, quantity and delivery terms are fixed at inception", "They are traded on recognised stock exchanges"], "answer": 3, "why": ["Forwards are bilateral OTC contracts; terms can be altered if both agree; all terms are fixed on the contract date. They are not exchange-traded.", "Key point: Forwards are OTC, not exchange-traded. The other statements are true."], "reasons": ["True — they are bilateral", "True — terms can be altered by mutual agreement", "True — price, quantity and delivery terms are fixed at inception", "FALSE — forwards are not traded on exchanges. Forwards are OTC, not exchange-traded."], "notes": ["Easy way to remember: If it's on an exchange, it's a future."], "id": 49}, "50": {"ch": 1, "chapter": "Basics of Derivatives", "q": "Financial derivatives provide the facility for:", "options": ["Trading only", "Hedging only", "Trading, hedging and arbitraging", "Arbitraging only"], "answer": 2, "why": ["The workbook's sample answer: derivatives provide the facility for trading, hedging and arbitrage — all three participant types use them.", "Key point: Derivatives serve all three purposes — trading (speculation), hedging and arbitrage."], "reasons": ["Incomplete — hedging and arbitrage are also facilitated", "Incomplete", "Correct — all three. Derivatives serve all three purposes — trading (speculation), hedging and arbitrage.", "Incomplete"], "notes": ["Easy way to remember: Three players, three uses."], "id": 50}, "51": {"ch": 2, "chapter": "Understanding the Index", "q": "An index of five stocks had a base market capitalisation of Rs 18,800 lakh set equal to 100. Today the market capitalisation is Rs 42,500 lakh. What is the current index value (market-cap weighted)?", "options": ["226.06", "204.50", "236.00", "425.00"], "answer": 0, "why": ["In a market-cap weighted index, the base-date market cap is equated to the base value (100). Current index = Current M-cap ÷ Base M-cap × Base value. The workbook's example gives 18,800 → 42,500 lakh.", "Working: Index = (Current M-cap / Base M-cap) × Base value = 42,500 / 18,800 × 100 = 226.06."], "reasons": ["42,500 ÷ 18,800 × 100 = 226.06. Index = (Current M-cap / Base M-cap) × Base value = 42,500 / 18,800 × 100 = 226.06.", "204.50 does not follow from the ratio", "236 is an arithmetic slip", "425 treats 42,500 as if the base were 10,000"], "notes": ["⚠️ Important: Use market capitalisation (price × shares), not prices alone, in a market-cap index.", "Easy way to remember: New M-cap ÷ Old M-cap × Base."], "id": 51}, "52": {"ch": 2, "chapter": "Understanding the Index", "q": "A market-cap weighted index has three stocks: A (price Rs 100, 10 lakh shares), B (Rs 200, 5 lakh shares), C (Rs 50, 20 lakh shares). Base index = 1,000. Prices move to A = 120, B = 180, C = 60. New index value?", "options": ["1,029", "1,050", "1,100", "1,200"], "answer": 2, "why": ["Market cap = price × number of shares for each stock; the index moves by the ratio of total market cap.", "Working: Base M-cap = 1,000 + 1,000 + 1,000 = 3,000 lakh. New M-cap = 1,200 + 900 + 1,200 = 3,300 lakh. Index = 3,300 / 3,000 × 1,000 = 1,100."], "reasons": ["1,029 is not a result of the M-cap ratio", "1,050 would require M-cap of 3,150 lakh", "Base M-cap 3,000; new 1,200 + 900 + 1,200 = 3,300 → 3,300/3,000 × 1,000 = 1,100", "1,200 overstates the rise"], "notes": ["⚠️ Important: B's price falls but C's rise is bigger in value terms because C has 20 lakh shares.", "Easy way to remember: Weight = value, not price."], "id": 52}, "53": {"ch": 2, "chapter": "Understanding the Index", "q": "Using the same three stocks (A: 100→120, B: 200→180, C: 50→60), what is the percentage change in a PRICE-weighted index?", "options": ["+10.00%", "+6.67%", "+2.86%", "−2.86%"], "answer": 2, "why": ["Price-weighted index = sum of prices ÷ number of stocks. Each stock's weight is proportional to its price, so the costliest stock moves the index most.", "Working: Old price index = (100+200+50)/3 = 116.67; new = (120+180+60)/3 = 120. Change = 3.33/116.67 = +2.86%. B's fall hurts more because B has the highest price, i.e., the highest weight."], "reasons": ["+10% is the market-cap result, not the price-weighted one", "+6.67% has no basis", "Old = 350/3 = 116.67; new = 360/3 = 120 → +2.86%", "The index rises, so a negative change is wrong"], "notes": ["⚠️ Important: Same stocks, different methodology → different index change (M-cap +10%, price-weighted +2.86%).", "Easy way to remember: Price-weighted: the heaviest price tag pulls hardest."], "id": 53}, "54": {"ch": 2, "chapter": "Understanding the Index", "q": "In a price-weighted index of AZ(150), BY(300), CX(450), DW(100), EU(250), which stock carries the highest weight?", "options": ["AZ", "BY", "CX", "DW"], "answer": 2, "why": ["In a price-weighted index the weight of each stock = its price ÷ sum of prices. Workbook: CX weight 0.36 (450/1,250).", "Working: Weight is proportional to price. CX at 450 has weight 450/1,250 = 0.36, the highest."], "reasons": ["AZ: 150/1,250 = 0.12", "BY: 300/1,250 = 0.24", "CX: 450/1,250 = 0.36 — highest. Weight is proportional to price.", "DW: 100/1,250 = 0.08"], "notes": ["Easy way to remember: Highest price = highest weight."], "id": 54}, "55": {"ch": 2, "chapter": "Understanding the Index", "q": "Which of these is a well-known price-weighted index?", "options": ["Nifty 50", "S&P 500", "Dow Jones Industrial Average", "BSE Sensex"], "answer": 2, "why": ["The workbook: \"Dow Jones Industrial Average and Nikkei 225 are popular price-weighted indices.\" Sensex and Nifty were earlier market-cap weighted and are now free-float based.", "Key point: The workbook cites the Dow Jones Industrial Average and Nikkei 225 as price-weighted indices. Nifty and Sensex are free-float market-cap weighted."], "reasons": ["Nifty 50 is free-float market cap weighted", "S&P 500 is market cap weighted", "Dow Jones Industrial Average — price-weighted", "Sensex is free-float market cap weighted"], "notes": ["Easy way to remember: Dow and Nikkei = price-weighted."], "id": 55}, "56": {"ch": 2, "chapter": "Understanding the Index", "q": "An equal-weighted index of four stocks, each with value Rs 30,000 on the base date (total 1,20,000, index = 100), now has total value Rs 1,46,000. What is the new index value, and which action restores equal weights?", "options": ["121.67; sell the gainers and buy the laggards", "121.67; buy the gainers and sell the laggards", "146.00; no rebalancing needed", "118.00; sell all stocks equally"], "answer": 0, "why": ["In an equal-weighted index every stock starts with the same value. After price moves, weights drift, and the manager must rebalance by selling stocks above the target weight and buying those below.", "Working: 1,46,000 / 1,20,000 × 100 = 121.67. Stocks that rose now exceed 25% weight; the manager sells those and buys the ones below 25%."], "reasons": ["146,000/120,000 × 100 = 121.67; sell gainers (P, R), buy laggards (Q, S)", "Buying the gainers would widen the imbalance", "146 is the value in thousands, not the index; rebalancing is required", "118 is wrong, and selling equally doesn't restore equal weight"], "notes": ["Easy way to remember: Equal weight → trim winners, top up losers."], "id": 56}, "57": {"ch": 2, "chapter": "Understanding the Index", "q": "A company has 10 crore shares at Rs 500. Promoters hold 60%. What is its free-float market capitalisation?", "options": ["Rs 5,000 crore", "Rs 3,000 crore", "Rs 1,200 crore", "Rs 2,000 crore"], "answer": 3, "why": ["Free-float market cap counts only shares readily available for trading, excluding promoter holdings.", "Working: Free float = 40% × 10 crore = 4 crore shares. Free-float M-cap = 4 crore × 500 = Rs 2,000 crore. Promoter holding is not readily available for trading."], "reasons": ["Rs 5,000 crore is total M-cap", "Rs 3,000 crore uses 60% instead of 40%", "Rs 1,200 crore is not the correct result", "Free float 40% × 10 crore = 4 crore shares × 500 = Rs 2,000 crore"], "notes": ["⚠️ Important: Free float excludes promoters — the shares \"locked\" with promoters don't trade.", "Easy way to remember: Free float = what the public can actually trade."], "id": 57}, "58": {"ch": 2, "chapter": "Understanding the Index", "q": "A company with 5,00,00,000 shares outstanding trades at Rs 120. Its market capitalisation is:", "options": ["Rs 60 crore", "Rs 6,000 crore", "Rs 600 crore", "Rs 6 crore"], "answer": 2, "why": ["Market capitalisation = shares outstanding × current market price. Workbook: 5 crore × 120 = Rs 600 crore.", "Working: 5 crore × 120 = Rs 600 crore (Rs 6,00,00,00,000)."], "reasons": ["Rs 60 crore drops a zero", "Rs 6,000 crore adds a zero", "5,00,00,000 × 120 = Rs 6,00,00,00,000 = Rs 600 crore", "Rs 6 crore is far too small"], "notes": ["Easy way to remember: 1 crore = 1,00,00,000."], "id": 58}, "59": {"ch": 2, "chapter": "Understanding the Index", "q": "Order book: Best bid 9.80 (1,000), 9.70 (2,000); Best ask 9.90 (1,000), 10.00 (1,500). What is the impact cost of BUYING 1,500 shares?", "options": ["0.50%", "0.68%", "1.02%", "0.84%"], "answer": 3, "why": ["Impact cost = (Actual execution price − Ideal price) ÷ Ideal price × 100, where Ideal price = average of best bid and best offer. This is the workbook example.", "Working: Ideal price = (9.80 + 9.90)/2 = 9.85. Actual buy price = (1,000×9.90 + 500×10.00)/1,500 = 9.9333. Impact cost = (9.9333 − 9.85)/9.85 = 0.84%."], "reasons": ["0.50% is not the result", "0.68% is not the result", "1.02% is the impact cost of SELLING 2,000", "Ideal 9.85; buy avg (1,000×9.90 + 500×10.00)/1,500 = 9.9333; (9.9333−9.85)/9.85 = 0.84%"], "notes": ["Easy way to remember: Impact cost = distance from mid-price."], "id": 59}, "60": {"ch": 2, "chapter": "Understanding the Index", "q": "Using the same order book (bid 9.80×1,000, 9.70×2,000; ask 9.90×1,000, 10.00×1,500), what is the impact cost of SELLING 2,000 shares?", "options": ["0.51%", "0.84%", "1.52%", "1.02%"], "answer": 3, "why": ["For a sell order, the order hits the best bids in sequence. Impact cost = (Ideal − Actual sell price) ÷ Ideal.", "Working: Ideal = 9.85. Actual sell price = (1,000×9.80 + 1,000×9.70)/2,000 = 9.75. Impact cost = (9.85 − 9.75)/9.85 = 1.02%."], "reasons": ["0.51% is not the result", "0.84% is the buy-side example", "1.52% overstates", "Sell 1,000 @ 9.80 + 1,000 @ 9.70 = avg 9.75; (9.85 − 9.75)/9.85 = 1.02%"], "notes": ["⚠️ Important: When selling, you walk DOWN the bid side; when buying, UP the ask side.", "Easy way to remember: Sell → hit bids; Buy → lift offers."], "id": 60}, "61": {"ch": 2, "chapter": "Understanding the Index", "q": "Best bid Rs 50.00; asks: 50.10 (500), 50.20 (1,000). Impact cost of buying 1,000 shares is closest to:", "options": ["0.20%", "0.10%", "0.30%", "0.40%"], "answer": 0, "why": ["Ideal price = (best bid + best ask) ÷ 2. The buy order walks up the ask side.", "Working: Ideal = (50.00 + 50.10)/2 = 50.05. Buy avg = (500×50.10 + 500×50.20)/1,000 = 50.15. IC = 0.10/50.05 = 0.20%."], "reasons": ["Ideal 50.05; avg buy (500×50.10 + 500×50.20)/1,000 = 50.15; 0.10/50.05 = 0.20%", "0.10% ignores the second price level", "0.30% overstates", "0.40% overstates"], "notes": ["Easy way to remember: Mid first, average fill second, % gap third."], "id": 61}, "62": {"ch": 2, "chapter": "Understanding the Index", "q": "State whether true or false: \"Impact cost is low when liquidity in the system is poor.\"", "options": ["True", "False"], "answer": 1, "why": ["Workbook sample: \"Impact cost is low when the liquidity in the system is poor\" is FALSE. Liquidity means large orders execute without moving prices; poor liquidity means high impact cost.", "Key point: Poor liquidity means thin order books and wide spreads, so large orders move the price more — impact cost is HIGH."], "reasons": ["True would contradict the definition of liquidity", "False — poor liquidity means HIGH impact cost"], "notes": ["Easy way to remember: Liquid market = low impact."], "id": 62}, "63": {"ch": 2, "chapter": "Understanding the Index", "q": "Which cost is NOT actually paid by market participants but arises due to lack of liquidity?", "options": ["Securities Transaction Tax", "Impact cost", "SEBI turnover fees", "Brokerage"], "answer": 1, "why": ["Workbook sample: impact cost is not actually paid by participants but arises from lack of liquidity. STT, SEBI fees and brokerage are explicit charges.", "Key point: Impact cost is an implicit cost from executing away from the ideal price; it is not a fee paid to anyone."], "reasons": ["STT is an explicit tax paid", "Impact cost — implicit, arises from lack of liquidity", "SEBI charges are explicit fees", "Brokerage is explicit"], "notes": ["Easy way to remember: Explicit = on the contract note; implicit = hidden in price."], "id": 63}, "64": {"ch": 2, "chapter": "Understanding the Index", "q": "The bid-ask spread conveys the transaction cost for:", "options": ["A small trade", "A large trade", "An institutional block trade", "An overnight position"], "answer": 0, "why": ["The workbook: \"The bid-ask spread therefore conveys the transaction cost for a small trade.\" For large orders, impact cost captures the extra cost.", "Key point: The workbook notes the bid-ask spread reflects the cost of a small trade; impact cost captures the extra cost of large orders."], "reasons": ["Small trade — spread shows its cost. The workbook notes the bid-ask spread reflects the cost of a small trade; impact cost captures the extra cost of large orders.", "Large trades are captured by impact cost", "Block trades suffer impact cost too", "Overnight holding is unrelated"], "notes": ["Easy way to remember: Spread = small trade cost; impact = big trade cost."], "id": 64}, "65": {"ch": 2, "chapter": "Understanding the Index", "q": "Going from 50 to 100 stocks in an index reduces diversifiable risk:", "options": ["Sharply", "To zero", "Very little", "Not at all, it increases risk"], "answer": 2, "why": ["The workbook: 10 → 20 stocks gives a sharp risk reduction; 50 → 100 gives very little; beyond 100 almost zero. A good index trades off diversification against liquidity.", "Key point: 10→20 stocks cuts risk sharply, 50→100 only a little, and beyond 100 there is almost zero decline. A good index trades off diversification against liquidity."], "reasons": ["Sharp reductions happen from 10 to 20, not 50 to 100", "Diversifiable risk is not reduced to zero here", "Very little — correct. 10→20 stocks cuts risk sharply, 50→100 only a little, and beyond 100 there is almost zero decline.", "Diversification does not increase risk"], "notes": ["Easy way to remember: Diversification has diminishing returns."], "id": 65}, "66": {"ch": 2, "chapter": "Understanding the Index", "q": "Which is NOT an attribute of a good market index?", "options": ["It should include the maximum possible number of illiquid stocks for diversification", "It should reflect market behaviour", "It should be computed by an independent third party free from influence", "It should be professionally maintained"], "answer": 0, "why": ["Attributes: reflects market behaviour, computed by an independent third party free from influence, professionally maintained. Liquidity also matters (low impact cost).", "Key point: Illiquid stocks raise impact cost and make the index hard to replicate. The first three are the listed attributes."], "reasons": ["Illiquid stocks increase impact cost; not an attribute", "Listed attribute", "Listed attribute", "Listed attribute"], "notes": ["Easy way to remember: Good index = Representative, Independent, Maintained, Liquid."], "id": 66}, "67": {"ch": 2, "chapter": "Understanding the Index", "q": "Adjusting the index for a stock split or bonus issue is part of:", "options": ["Index maintenance", "Index construction", "Index revision", "Index rebalancing to equal weights"], "answer": 0, "why": ["Workbook: construction = choosing stocks and methodology; maintenance = adjusting for corporate actions (bonus, rights, split, consolidation, merger); revision = changing composition.", "Key point: Maintenance = adjusting for corporate actions (bonus, rights, splits, mergers). Revision = changing the composition (replacing stocks)."], "reasons": ["Maintenance — adjusting for corporate actions", "Construction is the initial design", "Revision is replacing stocks", "Rebalancing applies to equal-weighted funds"], "notes": ["⚠️ Important: Maintenance is triggered by a corporate action; revision is a continuous exercise.", "Easy way to remember: Maintenance = Mend after events; Revision = Replace members."], "id": 67}, "68": {"ch": 2, "chapter": "Understanding the Index", "q": "Replacing a stock in the index because its trading intensity has fallen is:", "options": ["Index maintenance", "Index construction", "Index revision", "Free-float adjustment"], "answer": 2, "why": ["Revision means changing the composition — replacing existing stocks with new ones, e.g., due to changes in trading intensity.", "Key point: Revision changes the index composition — replacing existing stocks with new ones."], "reasons": ["Maintenance adjusts for corporate actions", "Construction is the initial selection", "Revision — changing the constituents. Revision changes the index composition — replacing existing stocks with new ones.", "Free-float adjustment is not a revision"], "notes": ["Easy way to remember: Revision = Replacement."], "id": 68}, "69": {"ch": 2, "chapter": "Understanding the Index", "q": "NSE indices are managed by ___, while BSE indices are managed by ___.", "options": ["NSE Clearing Ltd; BSE Ltd", "NSE Indices Limited; Asia Index Pvt Ltd", "CRISIL; ICRA", "SEBI; RBI"], "answer": 1, "why": ["The workbook: BSE indices are managed by Asia Index Pvt Ltd; NSE indices by NSE Indices Limited.", "Key point: NSE Indices Ltd manages NSE indices; Asia Index Pvt Ltd manages BSE indices."], "reasons": ["NSE Clearing is the clearing corporation", "Correct pairing. NSE Indices Ltd manages NSE indices; Asia Index Pvt Ltd manages BSE indices.", "CRISIL and ICRA are rating agencies", "Regulators do not manage indices"], "notes": ["Easy way to remember: NSE → NSE Indices Ltd; BSE → Asia Index."], "id": 69}, "70": {"ch": 2, "chapter": "Understanding the Index", "q": "As per SEBI's October 30, 2025 circular, which set of prudential norms applies to derivatives on existing non-benchmark indices?", "options": ["Minimum 10 constituents; top weight ≤ 25%; top 3 ≤ 55%", "Minimum 14 constituents; top weight ≤ 20%; top 3 ≤ 45%", "Minimum 20 constituents; top weight ≤ 15%; top 3 ≤ 40%", "Minimum 14 constituents; top weight ≤ 33%; top 3 ≤ 62%"], "answer": 1, "why": ["The workbook: derivatives on existing non-benchmark indices must satisfy a minimum of 14 constituents, top constituent weight ≤ 20%, and combined top-3 weight ≤ 45%.", "Key point: The norms are at least 14 constituents, top constituent ≤ 20%, and combined top 3 ≤ 45%."], "reasons": ["Wrong on all three numbers", "Correct — 14 / 20% / 45%. The norms are at least 14 constituents, top constituent ≤ 20%, and combined top 3 ≤ 45%.", "Wrong numbers", "33% and 62% are not the norms"], "notes": ["Easy way to remember: 14 – 20 – 45."], "id": 70}, "71": {"ch": 2, "chapter": "Understanding the Index", "q": "A non-benchmark index's top constituent has weight 30% against a target of 20%, to be adjusted in four monthly tranches. After the first tranche the weight will be:", "options": ["27.5%", "28.0%", "25.0%", "20.0%"], "answer": 0, "why": ["In the four-tranche method, month 1 adjusts by (Actual − Desired)/4, month 2 by the remaining gap/3, month 3 by /2, month 4 by /1.", "Working: Tranche 1 adjustment = (30 − 20)/4 = 2.5%. New weight = 27.5%. Later tranches divide the remaining gap by 3, 2 and 1."], "reasons": ["(30 − 20)/4 = 2.5% → 27.5%. Tranche 1 adjustment = (30 − 20)/4 = 2.5%.", "28% would be a 2% cut, i.e., an 8% gap", "25% would need two tranches", "20% would be a single-tranche adjustment"], "notes": ["Easy way to remember: Divide by the number of tranches left."], "id": 71}, "72": {"ch": 2, "chapter": "Understanding the Index", "q": "In the four-tranche method, the Month-2 adjustment for a constituent at 25.5% with a 20% target is:", "options": ["1.38%", "2.75%", "1.83%", "5.50%"], "answer": 2, "why": ["Workbook illustration: month 2 starts at 25.5% against a 20% target; adjustment = (25.5 − 20)/3 = 1.83% → 23.67%.", "Working: Month 2 divides the remaining gap by 3: (25.5 − 20)/3 = 1.83%, giving 23.67%."], "reasons": ["1.38% is a digit swap", "2.75% divides by 2 (that is month 3)", "5.5/3 = 1.83%. Month 2 divides the remaining gap by 3: (25.5 − 20)/3 = 1.83%, giving 23.67%.", "5.5% is the whole remaining gap"], "notes": ["Easy way to remember: Month 2 → ÷3."], "id": 72}, "73": {"ch": 2, "chapter": "Understanding the Index", "q": "Under the SEBI timeline for non-benchmark indices, BANKNIFTY was to comply:", "options": ["By December 31, 2025 in a single tranche", "By June 30, 2026 in two tranches", "Immediately from November 20, 2024", "By March 31, 2026 in four monthly tranches"], "answer": 3, "why": ["Workbook table: BANKEX (BSE) and FINNIFTY (NSE) — up to Dec 31, 2025, single tranche; BANKNIFTY (NSE) — up to Mar 31, 2026, four monthly tranches.", "Key point: BANKEX and FINNIFTY — up to Dec 31, 2025, single tranche. BANKNIFTY — up to Mar 31, 2026, four monthly tranches."], "reasons": ["This is the BANKEX/FINNIFTY timeline", "Not in the workbook", "Nov 20, 2024 relates to contract size/weekly expiry changes", "Correct for BANKNIFTY. BANKEX and FINNIFTY — up to Dec 31, 2025, single tranche."], "notes": ["Easy way to remember: BANKNIFTY gets four slices, finishing March 2026."], "id": 73}, "74": {"ch": 2, "chapter": "Understanding the Index", "q": "A Sensex index fund underperforms the Sensex by 0.35% in a year. This difference is called:", "options": ["Impact cost", "Basis", "Expense ratio mismatch spread", "Tracking error"], "answer": 3, "why": ["The workbook: an index fund returns similar to the index except for a small \"tracking error\" from fund management expenses and cash holdings.", "Key point: The gap between an index fund's return and the index return (from expenses, cash holdings etc.) is tracking error."], "reasons": ["Impact cost is a trading cost from illiquidity", "Basis is spot minus futures", "Not a workbook term", "Tracking error — the gap between fund return and index return"], "notes": ["Easy way to remember: Tracking error = how far the fund strays from the index."], "id": 74}, "75": {"ch": 2, "chapter": "Understanding the Index", "q": "Which advantage do ETFs have over ordinary index mutual funds?", "options": ["They guarantee index returns with zero tracking error", "They are exempt from all taxes", "They trade on the exchange so intraday buying and selling is possible", "They cannot fall below NAV"], "answer": 2, "why": ["The workbook: ETFs are baskets that trade like stocks on an exchange, so intraday transactions are possible; they also offer small denominations and low transaction cost.", "Key point: ETFs are baskets that trade like stocks, allowing intraday transactions and small-denomination basket trading."], "reasons": ["No guarantee of zero tracking error", "Not tax-exempt", "Correct — exchange-traded, intraday trading. ETFs are baskets that trade like stocks, allowing intraday transactions and small-denomination basket trading.", "ETF prices can move away from NAV"], "notes": ["Easy way to remember: ETF = fund that trades like a share."], "id": 75}, "76": {"ch": 2, "chapter": "Understanding the Index", "q": "Which is NOT a stated significance of a stock index?", "options": ["Indicator of overall market or sector performance", "Benchmark for portfolio performance", "A guarantee against systematic risk", "Underlying for derivatives"], "answer": 2, "why": ["The workbook lists three: indicator of market/sector performance, benchmark for portfolios, and underlying for derivatives.", "Key point: An index measures the market; it doesn't protect against market risk. Index derivatives can be used to hedge, but the index itself guarantees nothing."], "reasons": ["Listed", "Listed", "An index measures risk; it doesn't guarantee against it", "Listed"], "notes": ["Easy way to remember: Indicator, Benchmark, Underlying — \"IBU\"."], "id": 76}, "77": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "On May 11 you agree with a goldsmith to buy 10 g of gold after one month at Rs 62,337. On the settlement date spot gold is Rs 62,700. Your gain per 10 g (buying under the forward and selling in the spot market) is:", "options": ["Rs 207", "Rs 363", "Rs 570", "Nil — forwards have no gain or loss"], "answer": 1, "why": ["In a forward, you lock the price today. On the settlement date you buy at the forward price and can sell at the spot price. Gain = Spot − Forward price. (Workbook gold example.)", "Working: Buy at 62,337 under the forward, sell at 62,700 spot → gain = 363."], "reasons": ["207 is 62,337 − 62,130 — the forward premium, not your gain", "62,700 − 62,337 = 363 gain per 10 g. Buy at 62,337 under the forward, sell at 62,700 spot → gain = 363.", "570 is 62,700 − 62,130, i.e., spot vs original spot", "Forwards do create gains/losses when spot differs from the forward price"], "notes": ["Easy way to remember: Long forward gain = Spot at maturity − Forward price."], "id": 77}, "78": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "Same forward (buy gold at Rs 62,337). If spot on the settlement date is Rs 61,900, the result for you is:", "options": ["Loss of Rs 437", "Profit of Rs 437", "Loss of Rs 237", "You can walk away without loss"], "answer": 0, "why": ["Both parties to a forward are obliged to honour it irrespective of the price on delivery. Result = Spot − Forward = 61,900 − 62,337.", "Key point: A forward is binding. You pay 62,337 for gold worth 61,900 → loss of 437. Walking away is a feature of options, not forwards."], "reasons": ["Loss of 437 — you pay 62,337 for gold worth 61,900", "A profit would need spot above 62,337", "237 is the workbook's figure for spot 62,100, not 61,900", "Only option buyers can walk away; forwards are binding"], "notes": ["⚠️ Important: Don't copy the workbook's 237 blindly — the spot price in this question is different.", "Easy way to remember: Forward = both-way obligation."], "id": 78}, "79": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "In the gold forward example, at the time of entering the contract:", "options": ["The buyer pays the full forward price upfront", "The buyer pays a premium to the goldsmith", "The goldsmith pays a margin to the buyer", "There is no exchange of money or gold"], "answer": 3, "why": ["The workbook: after agreeing the forward price \"there is no exchange of money or gold at this point of time\". Everything happens on the settlement date.", "Key point: In a forward, nothing changes hands at inception; both exchange money and asset only on the settlement date."], "reasons": ["The buyer pays only on the settlement date", "Premiums exist in options, not forwards", "Margins are an exchange-traded futures feature", "Correct — nothing changes hands at inception. In a forward, nothing changes hands at inception; both exchange money and asset only on the settlement date."], "notes": ["Easy way to remember: Forward: shake hands today, exchange later."], "id": 79}, "80": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "A and B agree that A will buy 100 kg rice at Rs 40/kg after 6 months. At maturity rice is Rs 50/kg and B refuses to deliver. A has suffered:", "options": ["Liquidity risk", "Basis risk", "Operational risk", "Counterparty risk"], "answer": 3, "why": ["Workbook: counterparty risk is the risk of loss from the counterparty failing to fulfil its contractual obligation. In the rice example, B may refuse to deliver when the price rises to Rs 50.", "Key point: Counterparty (default) risk is the risk that the other party fails to honour the contract — here the seller refuses when the price moves against him."], "reasons": ["Liquidity risk is about being unable to exit", "Basis risk concerns spot-futures differences", "Operational risk is about processes and fraud", "Correct — the counterparty has defaulted. Counterparty (default) risk is the risk that the other party fails to honour the contract — here the seller refuses when the price moves against him."], "notes": ["Easy way to remember: Other side walks away = counterparty risk."], "id": 80}, "81": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "Why are forwards generally illiquid?", "options": ["They are always cash settled", "SEBI prohibits their transfer", "They are tailor-made and not exchange-listed, so other participants can't easily access or trade them", "They have no underlying"], "answer": 2, "why": ["The workbook: forwards are tailor-made to the parties' needs, not listed or traded on exchanges, so other participants can't easily access them, creating illiquidity.", "Key point: Customised terms and absence from exchanges mean few other participants want or can find these contracts."], "reasons": ["Forwards can be delivery-settled; settlement type is not the reason", "SEBI does not prohibit transfer", "Correct — tailor-made and not exchange-listed", "Forwards do have an underlying"], "notes": ["Easy way to remember: Custom-made = hard to resell."], "id": 81}, "82": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "Which of the following is NOT a limitation of futures contracts noted in the workbook?", "options": ["Limited maturities", "Counterparty default risk borne by the client", "Limited set of underlyings", "Increased administrative costs on account of MTM settlement"], "answer": 1, "why": ["Workbook limitations of futures: limited maturities, limited underlying set, lack of flexibility in contract design, and increased administrative costs due to MTM.", "Key point: The clearing corporation guarantees futures settlement, so client counterparty risk is removed. The other three are listed limitations."], "reasons": ["Listed limitation", "Not a limitation — the clearing corporation guarantees settlement", "Listed limitation", "Listed limitation"], "notes": ["Easy way to remember: Futures fix counterparty risk but lose flexibility."], "id": 82}, "83": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "In a futures contract, which term is NOT standardised by the exchange?", "options": ["Lot size", "Price", "Expiry date", "Tick size"], "answer": 1, "why": ["The workbook: \"In a futures market, the exchange decides all the terms of the contract other than price.\" Price is discovered by buyers and sellers.", "Key point: The exchange decides everything except price; price is discovered through buyer-seller interaction."], "reasons": ["Lot size is fixed by the exchange", "Price — the only term not set by the exchange", "Expiry is fixed by the exchange", "Tick size is fixed by the exchange"], "notes": ["Easy way to remember: Exchange fixes everything but the price."], "id": 83}, "84": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "The words \"buy\" and \"sell\" in futures are described as \"figurative\" because:", "options": ["Futures are always cash settled", "No money or underlying changes hands between buyer and seller when the deal originates", "SEBI treats futures as notional", "The exchange is the actual buyer and seller"], "answer": 1, "why": ["The workbook: \"The words buy and sell are figurative only because no money or underlying asset changes hand, between buyer and seller, when the deal is originated.\"", "Key point: At inception only margins are paid; the asset and full price do not change hands between the parties."], "reasons": ["Stock futures are physically settled, so this isn't the reason", "Correct — nothing changes hands at origination", "SEBI does not treat futures as notional", "The exchange's CC is counterparty, but that's not why the words are figurative"], "notes": ["Easy way to remember: \"Buy\" futures = promise to buy later."], "id": 84}, "85": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "On Oct 03, 2025, Nifty spot was 24,894.25 and Oct Nifty futures closed at 25,006.60. The basis was:", "options": ["+112.35", "+24,894.25", "−112.35", "Zero"], "answer": 2, "why": ["Workbook definition: Basis = Spot price − Futures price. When futures > spot, basis is negative. Workbook example: 24,894.25 − 25,006.60 = −112.35.", "Working: Basis = Spot − Futures = 24,894.25 − 25,006.60 = −112.35. Futures above spot → negative basis."], "reasons": ["The sign is reversed (that would be futures − spot)", "24,894.25 is just the spot value", "Correct — −112.35. Basis = Spot − Futures = 24,894.25 − 25,006.60 = −112.35.", "Basis is zero only at expiry"], "notes": ["⚠️ Important: Many books define basis as F − S. For NISM VIII use S − F.", "Easy way to remember: Basis = S − F."], "id": 85}, "86": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "A stock trades at Rs 780 and its near-month futures at Rs 772. The basis is:", "options": ["+8, futures at a premium", "−8, futures at a discount", "−8, futures at a premium", "+8, futures at a discount"], "answer": 3, "why": ["Basis = Spot − Futures. Futures below spot means the futures trades at a discount and the basis is positive.", "Working: Basis = 780 − 772 = +8. Futures below spot means futures trade at a discount; basis is positive."], "reasons": ["A positive basis means futures are at a discount, not a premium", "The sign is wrong", "Both sign and premium/discount are wrong", "Correct — +8 and futures at a discount. Basis = 780 − 772 = +8."], "notes": ["Easy way to remember: Positive basis ↔ futures discount."], "id": 86}, "87": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "Whatever its value during the life of a contract, the basis at expiry becomes:", "options": ["Zero", "Equal to the cost of carry", "Equal to the initial margin", "Negative"], "answer": 0, "why": ["The workbook: whatever the basis, it becomes zero at maturity because final settlement takes place at the closing price of the underlying.", "Key point: Final settlement is at the closing price of the underlying, so futures and spot converge — basis becomes zero."], "reasons": ["Correct — basis = 0 at expiry (convergence). Final settlement is at the closing price of the underlying, so futures and spot converge — basis becomes zero.", "Cost of carry shrinks to zero at expiry", "Margin is unrelated to basis", "Basis doesn't have to be negative"], "notes": ["Easy way to remember: At expiry, futures = spot."], "id": 87}, "88": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "The difference between the basis of a 1-month and a 2-month futures contract on the same underlying should essentially equal:", "options": ["The initial margin difference", "The tick size", "The cost of carrying the underlying from month 1 to month 2", "The dividend yield for a year"], "answer": 2, "why": ["The workbook: the difference in the basis of 1-month and 2-month contracts should equal the cost of carrying the underlying between the first and second month — the principle linking futures maturities.", "Key point: This is the fundamental link between futures of different maturities — the extra month of carry cost."], "reasons": ["Margins don't link maturities", "Tick size is the minimum price movement", "Correct — carry cost for the extra period. This is the fundamental link between futures of different maturities — the extra month of carry cost.", "One year's dividend is wrong"], "notes": ["Easy way to remember: Extra month = extra carry."], "id": 88}, "89": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "ABC trades at Rs 100. Borrowing cost is 6% p.a. ABC is expected to pay a 200% dividend on face value Rs 1 within the year. The break-even one-year futures price is:", "options": ["Rs 102", "Rs 104", "Rs 106", "Rs 108"], "answer": 1, "why": ["Workbook example: net cost of carry = interest paid − dividend received. Dividend of 200% on face value Rs 1 = Rs 2.", "Working: Interest = 6; dividend = 200% × 1 = 2. Net carry = 6 − 2 = 4. Break-even futures = 100 + 4 = 104."], "reasons": ["102 subtracts the dividend twice", "Interest 6 − dividend 2 = 4 → break-even 104. Interest = 6; dividend = 200% × 1 = 2.", "106 ignores the dividend", "108 adds the dividend instead of subtracting it"], "notes": ["⚠️ Important: Dividend % is on face value (Rs 1), not the market price (Rs 100).", "Easy way to remember: F = S + interest − dividend."], "id": 89}, "90": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "A share trades at Rs 250. An investor can borrow at 8% p.a. and expects a dividend of Rs 5 during the year. Using simple cost of carry, the one-year break-even futures price is:", "options": ["Rs 255", "Rs 265", "Rs 270", "Rs 275"], "answer": 1, "why": ["Cost of carry = financing cost − income. Break-even futures = Spot + net carry.", "Working: Interest = 8% × 250 = 20. Net carry = 20 − 5 = 15. F = 250 + 15 = 265."], "reasons": ["255 subtracts dividend from spot without interest", "8% × 250 = 20; net carry 20 − 5 = 15; F = 265", "270 ignores the dividend", "275 adds the dividend"], "notes": ["Easy way to remember: Borrow cost adds, dividend subtracts."], "id": 90}, "91": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "For equity derivatives, cost of carry equals:", "options": ["Interest paid to finance the purchase minus dividend earned", "Storage cost plus insurance", "Dividend earned minus interest paid", "Brokerage plus STT"], "answer": 0, "why": ["The workbook: for equity derivatives, carrying cost is the interest paid to finance the purchase less the dividend earned. Storage/insurance apply to commodities.", "Key point: Equity has no storage cost; carry = financing cost − income (dividend)."], "reasons": ["Correct — interest minus dividend. Equity has no storage cost; carry = financing cost − income (dividend).", "Storage and insurance apply to commodities", "Reversed signs", "Brokerage and STT are transaction costs, not carry"], "notes": ["Easy way to remember: Equity carry = Interest − Dividend."], "id": 91}, "92": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "\"Cost of carry may be different for different participants.\" This mainly explains why:", "options": ["Futures always trade at fair value", "The exchange fixes different prices for different clients", "Different participants have different fair values and no-arbitrage bounds, which keeps trading continuous", "Margins differ between buyers and sellers"], "answer": 2, "why": ["The workbook notes different borrowing costs and return expectations mean different fair values and no-arbitrage bounds, \"what makes the market and trading take place on a continuous basis\".", "Key point: Different borrowing costs and return expectations produce different fair values, which is what makes the market trade continuously."], "reasons": ["Futures don't always trade at one fair value", "The exchange never sets client-specific prices", "Different borrowing costs and return expectations produce different fair values, which is what makes the market trade continuously.", "Margins are unrelated to this statement"], "notes": ["Easy way to remember: Different carry → different fair values → continuous trading."], "id": 92}, "93": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "A trader buys one Nifty futures lot at 22,250 (lot size 25). The broker charges 10% initial margin. The initial margin is:", "options": ["Rs 55,625", "Rs 22,250", "Rs 5,56,250", "Rs 1,11,250"], "answer": 0, "why": ["Contract value = Futures price × lot size. Initial margin = % × contract value. (Workbook example.)", "Working: Contract value = 22,250 × 25 = 5,56,250. 10% = 55,625."], "reasons": ["22,250 × 25 = 5,56,250 × 10% = 55,625. Contract value = 22,250 × 25 = 5,56,250.", "22,250 is just the price", "5,56,250 is the contract value, not the margin", "1,11,250 is 20%"], "notes": ["Easy way to remember: Margin = % of (price × lot)."], "id": 93}, "94": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "Nifty futures at 24,000, lot size 75, initial margin 12%. What margin is required for 2 lots?", "options": ["Rs 4,32,000", "Rs 2,16,000", "Rs 3,60,000", "Rs 36,00,000"], "answer": 0, "why": ["Initial margin = Futures price × lot × number of lots × margin %.", "Working: Contract value per lot = 24,000 × 75 = 18,00,000. Two lots = 36,00,000. 12% = 4,32,000."], "reasons": ["24,000 × 75 × 2 = 36,00,000 × 12% = 4,32,000. Contract value per lot = 24,000 × 75 = 18,00,000.", "2,16,000 is for one lot only", "3,60,000 uses 10%", "36,00,000 is the contract value, not the margin"], "notes": ["Easy way to remember: Don't forget the number of lots."], "id": 94}, "95": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "Trader A sells 20 August contracts at Rs 4,500 and Trader B sells 17 September contracts at Rs 4,550. Lot size 50; initial margin 6%. Total initial margin to be collected from both is:", "options": ["Rs 5,02,050", "Rs 2,70,000", "Rs 2,32,050", "Rs 4,10,000"], "answer": 0, "why": ["Workbook Chapter 7 sample question. Both buyers and sellers pay initial margin. Compute separately then add.", "Working: A: 20 × 50 × 4,500 × 6% = 2,70,000. B: 17 × 50 × 4,550 × 6% = 2,32,050. Total = 5,02,050."], "reasons": ["A: 20×50×4,500×6% = 2,70,000; B: 17×50×4,550×6% = 2,32,050; total 5,02,050", "2,70,000 is only Trader A's margin", "2,32,050 is only Trader B's margin", "4,10,000 is an arithmetic slip"], "notes": ["⚠️ Important: Sellers pay margin too — the question says both traders SELL, and both still pay.", "Easy way to remember: Margin is per trader, then add."], "id": 95}, "96": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "Which statement on initial margin is correct?", "options": ["Only the buyer of futures pays initial margin", "Only the seller of futures pays initial margin", "Both buyer and seller of futures pay initial margin", "The clearing corporation pays initial margin to both"], "answer": 2, "why": ["The workbook: \"Both buyers and sellers of futures contract pay initial margin, as there is an obligation on both the parties to honour the contract.\"", "Key point: Both parties have an obligation, so both deposit initial margin."], "reasons": ["Sellers pay too", "Buyers pay too", "Correct — both pay. Both parties have an obligation, so both deposit initial margin.", "The clearing corporation collects margin; it doesn't pay it"], "notes": ["Easy way to remember: Futures: both sides obligated → both margined."], "id": 96}, "97": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "Initial margin on a futures contract is higher when:", "options": ["The underlying is more volatile", "The underlying is less volatile", "The contract has fewer days to expiry", "The lot size is smaller"], "answer": 0, "why": ["The workbook: \"As high volatility assets carry more risk, the exchange would charge higher initial margin on them.\"", "Key point: Higher volatility means higher potential one-day loss, so the exchange charges higher margin."], "reasons": ["Correct — higher volatility, higher margin. Higher volatility means higher potential one-day loss, so the exchange charges higher margin.", "Lower volatility means lower margin", "Days to expiry is not the stated driver", "A smaller lot means a lower absolute margin"], "notes": ["Easy way to remember: More volatile → more margin."], "id": 97}, "98": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "A trader bought Nifty futures at 22,250 (lot 25). It closed at 22,308.70. The MTM credited that day is closest to:", "options": ["Rs 5,870", "Rs 587", "Rs 14,675", "Rs 1,468"], "answer": 3, "why": ["MTM = (Settlement price − Trade price) × lot for a long position. Workbook: 58.70 × 25 = Rs 1,468 (rounded).", "Working: (22,308.70 − 22,250) × 25 = 58.70 × 25 = 1,467.50 ≈ 1,468. Next day's MTM starts from 22,308.70."], "reasons": ["5,870 uses a lot of 100", "587 uses a lot of 10", "14,675 uses a lot of 250", "58.70 × 25 = 1,467.50 ≈ 1,468. (22,308.70 − 22,250) × 25 = 58.70 × 25 = 1,467.50 ≈ 1,468."], "notes": ["Easy way to remember: MTM = price change × lot."], "id": 98}, "99": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "A trader is short 3 lots of index futures at 24,500 (lot 75). The day's settlement price is 24,380. MTM for the day:", "options": ["Rs 27,000 credit", "Rs 27,000 debit", "Rs 9,000 credit", "Rs 9,000 debit"], "answer": 0, "why": ["A short gains when the settlement price falls. MTM = (Sell price − Settlement) × lot × lots.", "Working: Short gains when price falls. (24,500 − 24,380) × 75 × 3 = 120 × 225 = 27,000 credit."], "reasons": ["120 × 75 × 3 = 27,000 credit. Short gains when price falls.", "The short gains, so it isn't a debit", "9,000 is for only one lot", "The direction and size are both wrong"], "notes": ["Easy way to remember: Short + price down = credit."], "id": 99}, "100": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "Long 1 lot (lot 50) at Rs 1,000. Daily settlement prices: Day 1: 1,012; Day 2: 995; Day 3: 1,005. What is the Day 2 MTM and the cumulative MTM after Day 3?", "options": ["−250 and +250", "−850 and +250", "−850 and +500", "+600 and +250"], "answer": 1, "why": ["Daily MTM compares each day's settlement price with the previous one (the entry price for day 1). Cumulative MTM always equals (latest settlement − entry) × lot.", "Working: Day 1: +12×50 = +600. Day 2: (995−1,012)×50 = −850. Day 3: +10×50 = +500. Cumulative = +250 = (1,005−1,000)×50."], "reasons": ["−250 is not Day 2's MTM", "Day 2: (995 − 1,012) × 50 = −850; cumulative (1,005 − 1,000) × 50 = +250", "Cumulative isn't 500", "+600 is Day 1's MTM, not Day 2's"], "notes": ["⚠️ Important: After each day, positions are reset to the settlement price, so Day 2 is measured from 1,012, not 1,000.", "Easy way to remember: Each day starts where yesterday settled."], "id": 100}, "101": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "You sold one XYZ futures contract at Rs 278 (lot 1,200) and bought it back at Rs 265. Your profit/loss is:", "options": ["−15,600", "+16,600", "+15,600", "−16,600"], "answer": 2, "why": ["Workbook sample. Short P&L = (Sell − Buy back) × lot.", "Working: Short gains on a fall: (278 − 265) × 1,200 = +15,600."], "reasons": ["Profit, not loss", "16,600 is an arithmetic slip", "(278 − 265) × 1,200 = +15,600. Short gains on a fall: (278 − 265) × 1,200 = +15,600.", "Sign and amount wrong"], "notes": ["Easy way to remember: Sell high, buy low = profit."], "id": 101}, "102": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "You are short one June XYZ futures (multiplier 50) at Rs 3,400 and closed out with a profit of Rs 10,000. How did you close?", "options": ["Sold 1 June contract at 3,600", "Bought 1 June contract at 3,600", "Bought 1 June contract at 3,200", "Sold 1 June contract at 3,200"], "answer": 2, "why": ["Workbook sample. To close a short you BUY. Profit 10,000 ÷ 50 = 200 per unit, so buy back at 3,400 − 200.", "Working: Closing a short needs a buy. Profit 10,000/50 = 200 per unit → buy at 3,400 − 200 = 3,200."], "reasons": ["Selling adds to the short, it doesn't close it", "Buying at 3,600 creates a loss of 10,000", "Buy at 3,200 → (3,400 − 3,200) × 50 = 10,000. Closing a short needs a buy.", "Selling doesn't close a short"], "notes": ["Easy way to remember: Close short = buy; profit only if cheaper."], "id": 102}, "103": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "Mar 1: A shorts 50 and B goes long 50. Mar 2: C goes long 100 and D goes short 100. What are the open interest and the volume on Mar 2?", "options": ["OI 100; volume 150", "OI 150; volume 100", "OI 300; volume 100", "OI 150; volume 150"], "answer": 1, "why": ["Workbook OI table. When a new buyer and new seller trade, OI rises. Volume counts only the day's trades.", "Working: New longs and new shorts are created, so OI rises from 50 to 150. Volume is only the day's trades = 100."], "reasons": ["OI and volume are swapped", "OI 50 + 100 = 150; volume 100. New longs and new shorts are created, so OI rises from 50 to 150.", "OI counts one side only, not both", "Volume was only 100 on Mar 2"], "notes": ["Easy way to remember: Both new → OI up."], "id": 103}, "104": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "Continuing, on Mar 3 A buys back 50 to close his short, and E newly shorts 50. Open interest becomes:", "options": ["150", "100", "200", "50"], "answer": 0, "why": ["Workbook: \"OI remains at 150 because A's short position is replaced by E's short position.\"", "Working: A's short is simply replaced by E's short. No net change in OI; it stays 150. Volume for the day = 50."], "reasons": ["Correct — 150, unchanged. A's short is simply replaced by E's short.", "OI doesn't fall", "No new pair created", "It doesn't fall to 50"], "notes": ["Easy way to remember: One closes, one opens → OI unchanged."], "id": 104}, "105": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "On Mar 4, C closes his long 100 by selling and D closes his short 100 by buying. Open interest becomes:", "options": ["150", "250", "50", "0"], "answer": 2, "why": ["Workbook: OI falls to 50 because existing long and short positions are both closed.", "Key point: Both sides close existing positions, so OI falls by 100 from 150 to 50."], "reasons": ["150 would mean no change", "250 would mean new positions", "Correct — 150 − 100 = 50. Both sides close existing positions, so OI falls by 100 from 150 to 50.", "The remaining 50 (B long, E short) stays open"], "notes": ["Easy way to remember: Both close → OI down."], "id": 105}, "106": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "A new buyer purchases 20 contracts from a seller who is squaring off an existing long of 20. Effect on open interest?", "options": ["Increases by 20", "Decreases by 20", "Unchanged", "Increases by 40"], "answer": 2, "why": ["If one side is new and the other side is closing, the open position just changes hands. OI is unchanged; volume increases by 20.", "Key point: A long simply passes from one holder to another. OI unchanged; volume increases by 20."], "reasons": ["Would need both sides new", "Would need both sides closing", "Correct — unchanged. A long simply passes from one holder to another.", "OI never counts both sides"], "notes": ["Easy way to remember: Hand-over, not creation."], "id": 106}, "107": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "Open interest counts:", "options": ["Both long and short contracts, added together", "Only one side of outstanding contracts", "Total contracts traded during the day", "Number of trades during the contract's life"], "answer": 1, "why": ["The workbook: long futures always equal short futures, so \"only one side of contracts is considered while calculating/mentioning open interest\".", "Key point: Total longs always equal total shorts, so only one side is counted."], "reasons": ["Adding both sides double counts", "Correct — one side only. Total longs always equal total shorts, so only one side is counted.", "That is traded volume", "That is the number of trades"], "notes": ["Easy way to remember: OI = one side of what's still open."], "id": 107}, "108": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "The previous day's closing price of a futures contract is Rs 100 and the price band is 10%. The permissible trading range next day is:", "options": ["Rs 95 – Rs 105", "Rs 90.91 – Rs 110", "Rs 100 – Rs 110", "Rs 90 – Rs 110"], "answer": 3, "why": ["The workbook: price band = range around previous day's close. 10% of 100 gives 90–110.", "Working: Band = previous close ± 10% = 90 to 110."], "reasons": ["That is a 5% band", "90.91 would be a band computed differently", "Bands work on both sides", "Correct — 90 to 110. Band = previous close ± 10% = 90 to 110."], "notes": ["Easy way to remember: Band = close ± %."], "id": 108}, "109": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "On the first trading day of a new stock futures contract, the price band is based on:", "options": ["The theoretical futures price", "The previous day's closing price of the underlying stock in the cash market", "The near-month futures closing price", "The strike price of the ATM option"], "answer": 1, "why": ["The workbook: on the first trading day, the price band is based on the previous day's closing price of the underlying stock in the cash market.", "Key point: With no prior futures close, the band uses the underlying's previous close in the cash market."], "reasons": ["Not the theoretical price", "With no prior futures close, the band uses the underlying's previous close in the cash market.", "The near-month futures close is not used for a new contract", "The strike price is irrelevant"], "notes": ["Easy way to remember: New contract → borrow the cash market close."], "id": 109}, "110": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "Mr X is short 5 Infosys futures and long 3 Reliance futures. Next day he buys 2 Infosys futures of the same expiry. His open position is:", "options": ["Short 3 Infosys, long 3 Reliance", "Short 7 Infosys, long 3 Reliance", "Long 2 Infosys, long 3 Reliance", "Short 5 Infosys, long 5 Reliance"], "answer": 0, "why": ["Workbook example: buying 2 Infosys reduces the short from 5 to 3; Reliance long stays 3.", "Key point: Buying 2 against a short of 5 reduces it to short 3. Reliance long unchanged."], "reasons": ["Correct — short 3 Infosys, long 3 Reliance. Buying 2 against a short of 5 reduces it to short 3.", "Buying doesn't increase a short", "The short is not fully closed", "Reliance is unchanged"], "notes": ["Easy way to remember: Opposite trade reduces the position."], "id": 110}, "111": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "Mr A is short 3 one-month, long 2 two-month and long 3 three-month futures on the same underlying. His position consists of:", "options": ["2 spreads (month 1–2), 1 spread (month 1–3), and 2 naked three-month longs", "3 calendar spreads and 2 naked longs", "5 spreads and no naked position", "2 spreads (month 2–3) and 3 naked short"], "answer": 0, "why": ["Workbook example: calendar spreads are computed with respect to the near month. 3 short near-month pair with 2 long month-2 and 1 long month-3; 2 month-3 longs remain naked.", "Key point: Spreads are computed against the near month. 2 of the 3 shorts pair with the 2 month-2 longs; the remaining 1 short pairs with 1 month-3 long. 2 month-3 longs remain naked."], "reasons": ["Correct — 2 (1–2) + 1 (1–3) spreads; 2 month-3 longs naked", "3 spreads is right but the naked count/type is wrong", "Not all 5 far longs can pair with only 3 near shorts", "Spreads are computed against the near month, not months 2–3"], "notes": ["Easy way to remember: Pair from the near month outward."], "id": 111}, "112": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "A trader is long 5 near-month, short 3 mid-month and short 4 far-month futures on the same stock. Calendar spreads and naked positions are:", "options": ["5 spreads; 2 mid-month shorts naked", "3 near–mid spreads; 2 near longs and 4 far shorts naked", "3 near–mid, 2 near–far spreads; 2 far-month shorts naked", "4 near–far spreads; 1 near long and 3 mid shorts naked"], "answer": 2, "why": ["Same rule as the workbook: spreads are computed with respect to the near month. Pair near longs first with mid shorts, then with far shorts.", "Key point: Pair near month first: 3 near longs vs 3 mid shorts; remaining 2 near longs vs 2 far shorts. 2 far shorts left naked."], "reasons": ["5 spreads is right, but the naked position is in the far month", "Near longs are not naked; they pair with far shorts", "3 near–mid + 2 near–far; 2 far shorts naked. Pair near month first: 3 near longs vs 3 mid shorts; remaining 2 near longs vs 2 far shorts.", "Pairing order is wrong"], "notes": ["Easy way to remember: Near month is the anchor."], "id": 112}, "113": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "When the near leg of a calendar spread in index futures expires, the far leg:", "options": ["Is automatically closed out", "Becomes a regular open (naked) position", "Is converted into an option", "Remains a spread against the next month automatically"], "answer": 1, "why": ["Workbook sample (True): when the near leg expires, the farther leg becomes a regular open position.", "Key point: A calendar spread becomes a naked/open position once the near month expires or either leg is closed."], "reasons": ["It is not automatically closed", "Correct — becomes naked/open. A calendar spread becomes a naked/open position once the near month expires or either leg is closed.", "Futures don't convert into options", "It doesn't auto-pair with a new contract"], "notes": ["Easy way to remember: One leg gone → the other stands alone."], "id": 113}, "114": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "A calendar spread in index futures generally attracts:", "options": ["The same margin as the sum of the two legs", "Higher margin than the two legs", "No margin", "Lower margin than the sum of the two independent legs"], "answer": 3, "why": ["Workbook sample: a calendar spread attracts lower margin than the sum of two independent legs, because the legs offset each other's risk.", "Key point: The legs offset each other's risk, so margin is lower than the sum of the two naked legs (note: the benefit is removed on expiry day for the expiring contract)."], "reasons": ["Equal margin ignores the offset", "Higher margin is wrong", "Some margin is still payable", "Correct — lower margin. The legs offset each other's risk, so margin is lower than the sum of the two naked legs (note: the benefit is removed on expiry day for the expiring contract)."], "notes": ["⚠️ Important: SEBI removed the calendar spread benefit on EXPIRY DAY for contracts expiring that day (index from Feb 1, 2025; single stocks from May 5, 2026).", "Easy way to remember: Offsetting legs → margin discount."], "id": 114}, "115": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "Which is an example of \"closing a position\"?", "options": ["Buying futures when you have no position", "Selling futures when you already hold a short in the same contract", "Selling futures you had bought earlier", "Buying a different underlying's futures"], "answer": 2, "why": ["The workbook: closing means buying or selling a contract that reduces the client's open position — selling what was bought or buying what was sold.", "Key point: Closing reduces an existing open position — selling what you bought or buying back what you sold."], "reasons": ["That opens a new long", "That increases the short", "Correct — selling what you bought earlier. Closing reduces an existing open position — selling what you bought or buying back what you sold.", "A different underlying is a new position"], "notes": ["Easy way to remember: Close = reverse the same contract."], "id": 115}, "116": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "A naked position in futures means:", "options": ["A futures position without margin", "A futures position hedged with options", "A spread between two exchanges", "A long or short futures position without any position in the underlying"], "answer": 3, "why": ["The workbook: a naked position is a long or short position in a futures contract without any position in the underlying asset.", "Key point: The workbook defines naked as a futures position with no corresponding position in the underlying."], "reasons": ["Margin is always required", "Hedged with options is not naked", "An inter-exchange position is arbitrage", "The workbook defines naked as a futures position with no corresponding position in the underlying."], "notes": ["Easy way to remember: Naked = no underlying cover."], "id": 116}, "117": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "Which difference between forwards and futures is correctly stated?", "options": ["Forwards have high liquidity; futures have low liquidity", "Futures have customised terms; forwards are standardised", "Price discovery is more efficient in forwards", "In futures, the clearing agency becomes counterparty to all trades; in forwards counterparty risk exists"], "answer": 3, "why": ["Workbook comparison table: forwards — OTC, tailor-made, counterparty risk, low liquidity, inefficient price discovery. Futures — exchange-traded, standardised, clearing agency as counterparty, high liquidity, efficient price discovery.", "Key point: Futures have clearing-house guarantee, standardisation, high liquidity and efficient price discovery. Forwards bear counterparty risk."], "reasons": ["Liquidity is reversed", "Customisation is reversed", "Price discovery is more efficient in futures", "Futures have clearing-house guarantee, standardisation, high liquidity and efficient price discovery."], "notes": ["Easy way to remember: Futures win on liquidity, guarantee and discovery."], "id": 117}, "118": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "Price discovery in forward markets is inefficient mainly because:", "options": ["Markets are scattered and there is no common order book", "Prices are set by the RBI", "Forwards are always settled in cash", "Forwards have daily price limits"], "answer": 0, "why": ["The workbook: price discovery in forwards is \"not efficient, as markets are scattered\"; futures use a common order book on a centralised platform.", "Key point: Without a centralised platform, buyers and sellers don't meet in one order book."], "reasons": ["Without a centralised platform, buyers and sellers don't meet in one order book.", "RBI doesn't set forward prices", "Settlement type is not the reason", "Forwards don't have daily price limits"], "notes": ["Easy way to remember: Scattered market = poor discovery."], "id": 118}, "119": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "A trader goes long futures at Rs 100. At expiry the underlying is Rs 70. His payoff is:", "options": ["+30", "−100", "−30", "0"], "answer": 2, "why": ["Long futures payoff = Spot at expiry − Futures price. Workbook table: at 70 → −30.", "Working: Long futures payoff = S_T − F = 70 − 100 = −30. Futures have linear, unlimited profit/loss."], "reasons": ["+30 would be the short's payoff", "−100 would need the price to fall to zero", "70 − 100 = −30. Long futures payoff = S_T − F = 70 − 100 = −30.", "Futures payoffs are linear, not zero"], "notes": ["Easy way to remember: Long futures: gain what's above, lose what's below."], "id": 119}, "120": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "Which statement about futures payoffs is correct?", "options": ["Long futures has limited loss, unlimited gain", "Short futures makes profit when prices rise", "Futures payoffs are asymmetric like options", "Both long and short futures have linear payoffs with unlimited profit or loss potential"], "answer": 3, "why": ["The workbook: long and short futures both have unlimited profit or loss potential, resulting in linear payoffs. Options have asymmetric payoffs.", "Key point: Futures are symmetric and linear. (Technically, long loss is capped at the price because prices can't go below zero, but it is treated as unlimited.)"], "reasons": ["Limited loss describes a long option", "Short futures profits when prices FALL", "Futures are symmetric; options are asymmetric", "Correct — linear, unlimited both ways. Futures are symmetric and linear."], "notes": ["Easy way to remember: Futures = straight line."], "id": 120}, "121": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "The X-axis of a payoff chart is not drawn to the left of the origin because:", "options": ["Profits cannot be negative", "The Y-axis shows only losses on the left", "Prices cannot go below zero", "Options cannot be exercised below zero strike"], "answer": 2, "why": ["The workbook: \"We do not draw the X Axis on the Left-Hand Side (LHS), as prices cannot go below zero.\"", "Key point: The X-axis shows the underlying price at expiry, which cannot be negative."], "reasons": ["The Y-axis handles profits and losses", "Not the reason", "Correct — prices can't be negative. The X-axis shows the underlying price at expiry, which cannot be negative.", "Not the reason"], "notes": ["Easy way to remember: No negative prices → no left X-axis."], "id": 121}, "122": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "A short futures at Rs 100 is squared up at expiry with the underlying at Rs 60. The profit is:", "options": ["−40", "60", "40", "160"], "answer": 2, "why": ["Short futures payoff = Futures price − Spot at expiry. Workbook: shorted at 100, prices fall to 60 → profit 40.", "Working: Short payoff = F − S_T = 100 − 60 = 40."], "reasons": ["Shorts gain when prices fall", "60 is the price, not the profit", "100 − 60 = 40. Short payoff = F − S_T = 100 − 60 = 40.", "160 adds instead of subtracts"], "notes": ["Easy way to remember: Short gains the fall."], "id": 122}, "123": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "The Cost of Carry model is also known as the:", "options": ["No-arbitrage model", "Expectations model", "Binomial model", "Convenience-yield model"], "answer": 0, "why": ["The workbook: \"Cost of Carry model is also known as the no-arbitrage model\" — it assumes arbitrage opportunities cannot persist in an efficient market.", "Key point: It assumes arbitrage cannot persist in an efficient market, so futures must equal spot plus carry."], "reasons": ["It assumes arbitrage cannot persist in an efficient market, so futures must equal spot plus carry.", "The expectations model is a different model", "Binomial is an option pricing model", "Convenience yield is a concept, not the model's name"], "notes": ["Easy way to remember: Carry model = No-arbitrage model."], "id": 123}, "124": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "Spot gold is Rs 62,130/10 g and total 3-month carry (financing, storage, insurance) is Rs 100. The 3-month futures trades at Rs 62,280. The arbitrage and its profit are:", "options": ["Reverse cash-and-carry; Rs 150", "Cash-and-carry (buy spot, sell futures); Rs 50", "Cash-and-carry; Rs 150", "No arbitrage exists"], "answer": 1, "why": ["Fair futures = Spot + cost of carry. If actual futures > fair, do cash-and-carry: buy spot, sell futures. Workbook: fair 62,230 vs actual 62,280 → Rs 50.", "Working: Fair futures = 62,130 + 100 = 62,230. Actual 62,280 is overpriced by 50 → buy spot, sell futures, lock Rs 50."], "reasons": ["Reverse cash-and-carry is for futures BELOW fair value", "Correct — futures overpriced by 50. Fair futures = 62,130 + 100 = 62,230.", "150 = futures − spot, ignoring carry cost", "A 50-point mispricing exists"], "notes": ["Easy way to remember: Futures too high → buy cash, sell futures."], "id": 124}, "125": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "In reverse cash-and-carry arbitrage the arbitrageur:", "options": ["Sells (borrowed) spot and buys futures, earning interest on sale proceeds", "Buys spot and sells futures", "Buys futures on two exchanges", "Sells call options and buys puts"], "answer": 0, "why": ["The workbook: when futures < fair price, traders sell gold (borrowed) in cash, earn interest on proceeds, and buy futures to return the gold later.", "Key point: When futures are below fair value, the arbitrageur shorts the asset in cash, invests the proceeds, and buys futures to reacquire the asset."], "reasons": ["When futures are below fair value, the arbitrageur shorts the asset in cash, invests the proceeds, and buys futures to reacquire the asset.", "That is cash-and-carry", "That is inter-exchange arbitrage", "Options are not involved"], "notes": ["Easy way to remember: Reverse = Sell cash, Buy futures."], "id": 125}, "126": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "As cash-and-carry arbitrage proceeds, what happens to prices?", "options": ["Spot falls and futures rise", "Spot rises and futures fall until aligned", "Both rise equally", "Both fall equally"], "answer": 1, "why": ["The workbook: as people buy gold in cash and sell futures, \"spot gold price will go up and gold futures price will come down\" until aligned.", "Key point: Arbitrageurs buy spot (pushing it up) and sell futures (pushing it down) until the mispricing disappears."], "reasons": ["Opposite direction", "Arbitrageurs buy spot (pushing it up) and sell futures (pushing it down) until the mispricing disappears.", "Prices don't rise equally", "Prices don't fall equally"], "notes": ["Easy way to remember: Buying pushes up, selling pushes down."], "id": 126}, "127": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "Transaction costs, taxes and margins in futures markets create:", "options": ["Contango", "Convenience yield", "No-arbitrage bounds around the fair price", "Negative basis"], "answer": 2, "why": ["The workbook: cost components create no-arbitrage bounds; if futures price stays within these bounds around fair value, arbitrage will not take place.", "Key point: Frictions create a band around fair value; arbitrage triggers only when futures move outside the band."], "reasons": ["Contango is futures above spot", "Convenience yield comes from holding commodities", "Frictions create a band around fair value; arbitrage triggers only when futures move outside the band.", "Negative basis is futures above spot"], "notes": ["Easy way to remember: Costs draw a fence around fair value."], "id": 127}, "128": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "Wider no-arbitrage bounds imply:", "options": ["The market is farther from equilibrium and less efficient", "The market is closer to equilibrium", "Higher convenience yield", "Lower implied volatility"], "answer": 0, "why": ["The workbook: \"wider the no-arbitrage bounds, farther the markets are from the equilibrium\". Lower costs narrow the bounds and improve efficiency.", "Key point: Higher costs widen bounds, allowing larger mispricing to persist; lower costs make markets more efficient."], "reasons": ["Higher costs widen bounds, allowing larger mispricing to persist; lower costs make markets more efficient.", "Reversed", "Convenience yield is unrelated", "Implied volatility is unrelated"], "notes": ["Easy way to remember: Wider fence = less efficient."], "id": 128}, "129": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "An index is at 17,500. Financing cost is 12% p.a. and the index yield is 4% p.a. Using discrete compounding, the fair price of a 90-day futures is closest to:", "options": ["17,700.00", "17,848.63", "17,835.26", "18,900.00"], "answer": 2, "why": ["Workbook formula: F = S × (1 + r − q)^(T/365). Example: 17,500 × (1.08)^(90/365) = 17,835.26.", "Working: F = 17,500 × (1 + 0.12 − 0.04)^(90/365) = 17,500 × 1.08^0.2466 = 17,835.26."], "reasons": ["17,700 has no basis in the formula", "17,848.63 is the continuous compounding answer", "Correct — discrete compounding. F = 17,500 × (1 + 0.12 − 0.04)^(90/365) = 17,500 × 1.08^0.2466 = 17,835.26.", "18,900 applies a full year"], "notes": ["Easy way to remember: Discrete: (1 + r − q)^T."], "id": 129}, "130": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "Same data (index 17,500; r = 12%; q = 4%; 90 days) using continuous compounding gives a fair futures price of:", "options": ["17,835.26", "17,920.00", "17,848.63", "17,780.00"], "answer": 2, "why": ["Continuous compounding: F = S × e^((r − q)T). Workbook: 17,500 × e^(0.08 × 90/365) = 17,848.63.", "Working: F = 17,500 × e^((0.12−0.04)×90/365) = 17,848.63. Continuous compounding gives a slightly higher value."], "reasons": ["17,835.26 is the discrete answer", "17,920 is not the result", "F = 17,500 × e^((0.12−0.04)×90/365) = 17,848.63.", "17,780 is below both answers"], "notes": ["⚠️ Important: Continuous compounding always gives a slightly HIGHER value than discrete for the same rate.", "Easy way to remember: Continuous: e^((r − q)T)."], "id": 130}, "131": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "An index is at 20,000; financing cost 10% p.a.; dividend yield 2% p.a. The fair value of a 3-month (0.25 year) futures using F = S(1 + r − q)^T is closest to:", "options": ["20,400.00", "20,404.03", "20,388.53", "20,500.00"], "answer": 2, "why": ["Discrete formula F = S(1 + r − q)^T with T = 0.25.", "Working: F = 20,000 × (1.08)^0.25 = 20,000 × 1.019427 = 20,388.53."], "reasons": ["20,400 is the simple-interest approximation", "20,404.03 is the continuous compounding answer", "20,000 × 1.08^0.25 = 20,388.53. F = 20,000 × (1.08)^0.25 = 20,000 × 1.019427 = 20,388.53.", "20,500 overstates"], "notes": ["Easy way to remember: Net rate = r − q; raise to the power of T in years."], "id": 131}, "132": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "Nifty spot is 24,000; r = 7%; dividend yield q = 1.5%; 60 days to expiry. Continuous-compounding fair futures price is closest to:", "options": ["24,218", "24,110", "24,276", "24,354"], "answer": 0, "why": ["F = S × e^((r − q) × t). Net rate 5.5%, t = 60/365.", "Working: F = 24,000 × e^(0.055 × 60/365) = 24,000 × e^0.009041 = 24,217.97."], "reasons": ["24,000 × e^(0.055 × 0.1644) = 24,217.97. F = 24,000 × e^(0.055 × 60/365) = 24,000 × e^0.009041 = 24,217.97.", "24,110 understates", "24,276 ignores the dividend yield", "24,354 is too high"], "notes": ["Easy way to remember: Subtract q before multiplying by time."], "id": 132}, "133": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "A stock at Rs 1,000; interest 9% p.a.; no dividend; 2 months to expiry. Fair futures price (continuous compounding):", "options": ["Rs 1,007.53", "Rs 1,015.11", "Rs 1,018.00", "Rs 1,090.00"], "answer": 1, "why": ["F = S × e^(rt), with t = 2/12. No dividend, so q = 0.", "Working: F = 1,000 × e^(0.09 × 2/12) = 1,000 × e^0.015 = 1,015.11."], "reasons": ["1,007.53 is for one month", "1,000 × e^0.015 = 1,015.11. F = 1,000 × e^(0.09 × 2/12) = 1,000 × e^0.015 = 1,015.11.", "1,018 overstates", "1,090 applies a full year"], "notes": ["Easy way to remember: Convert months to years: 2/12."], "id": 133}, "134": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "If an index futures trades above its fair price (computed with continuous compounding), the arbitrageur should:", "options": ["Buy futures and sell index stocks", "Buy index stocks and sell index futures", "Buy both", "Do nothing, since futures always trade above spot"], "answer": 1, "why": ["The workbook: if index futures trade above fair value, buy index stocks in cash and sell index futures to lock the difference (cash-and-carry).", "Key point: Futures overpriced → cash-and-carry: long the underlying basket, short futures, lock the difference."], "reasons": ["That is reverse cash-and-carry, for futures below fair value", "Futures overpriced → cash-and-carry: long the underlying basket, short futures, lock the difference.", "Buying both is not arbitrage", "Futures above spot is normal, but above FAIR value is mispricing"], "notes": ["Easy way to remember: Sell what's expensive, buy what's cheap."], "id": 134}, "135": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "Which is NOT an important assumption of the Cost of Carry model?", "options": ["The underlying is available in abundance", "The underlying can be sold short", "Demand and supply of the underlying are seasonal", "There are no transaction costs, taxes or margins"], "answer": 2, "why": ["Workbook assumptions: underlying abundant, demand/supply NOT seasonal, easy to hold, can be sold short, no transaction costs, no taxes, no margins.", "Key point: The model assumes demand and supply are NOT seasonal. Seasonal commodities break the model."], "reasons": ["Listed assumption", "Listed assumption", "Seasonality breaks the model — the assumption is that it is NOT seasonal", "Listed assumptions"], "notes": ["Easy way to remember: Model needs a boring, storable, shortable asset."], "id": 135}, "136": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "The Cost of Carry model is said to be more suitable for pricing forwards than futures because:", "options": ["Forwards are exchange-traded", "Futures cannot be arbitraged", "Forwards have no carry cost", "The model ignores margins, which are a feature of futures"], "answer": 3, "why": ["The workbook: \"Margins are not considered while computing the fair value... That is why this model is suitable for pricing forward contracts rather than futures contracts.\"", "Key point: Margins are not considered in the model; since futures involve margins and MTM, it fits forwards better."], "reasons": ["Forwards are OTC, not exchange-traded", "Futures can be arbitraged", "Forwards do have carry costs", "Correct — margins ignored. Margins are not considered in the model; since futures involve margins and MTM, it fits forwards better."], "notes": ["Easy way to remember: No margins in the model → fits forwards."], "id": 136}, "137": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "The Cost of Carry model fails for an asset that is:", "options": ["Highly liquid and storable", "Available in abundance", "Not storable or cannot be held/maintained easily", "A broad equity index"], "answer": 2, "why": ["The workbook: when an asset is not storable/not easy to hold, one cannot carry it to the future, so the model is not applicable.", "Key point: If the asset can't be carried to the future date, the synthetic futures position can't be created."], "reasons": ["That fits the model", "Abundance is an assumption of the model", "If the asset can't be carried to the future date, the synthetic futures position can't be created.", "A broad index is a financial asset that fits the model"], "notes": ["Easy way to remember: Can't carry it → can't use carry model."], "id": 137}, "138": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "Convenience yield is:", "options": ["The dividend yield on an index", "The interest earned on margin deposits", "An intangible benefit perceived from physically holding a commodity, especially during scarcity", "The yield on treasury bills"], "answer": 2, "why": ["The workbook: intangible inflows — the convenience or mental comfort of holding the asset, e.g., storing essentials during floods — are convenience yield.", "Key point: It is the \"comfort\" of holding the physical asset during shortages, like stocking grain before a flood."], "reasons": ["Dividend yield is a tangible inflow", "Interest on margin is not convenience yield", "It is the \"comfort\" of holding the physical asset during shortages, like stocking grain before a flood.", "T-bill yield is unrelated"], "notes": ["Easy way to remember: Convenience yield = comfort of having it in hand."], "id": 138}, "139": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "When convenience yield dominates the cost of carry, futures typically:", "options": ["Trade at a premium to spot and cash-and-carry arbitrage restores balance", "Trade at a discount to spot and reverse arbitrage may not be possible because nobody lends the asset", "Converge to zero", "Stop trading"], "answer": 1, "why": ["The workbook: convenience yield may dominate carry, making futures trade at a discount; reverse arbitrage isn't possible because no one lends the asset; the model breaks down.", "Key point: Futures trade below spot; reverse arbitrage fails since holders won't lend a scarce asset for short selling, so the model breaks down."], "reasons": ["Futures would be at a discount, not premium", "Futures trade below spot; reverse arbitrage fails since holders won't lend a scarce asset for short selling, so the model breaks down.", "Futures don't go to zero", "Trading continues"], "notes": ["Easy way to remember: Scarcity → futures discount → model breaks."], "id": 139}, "140": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "Convenience yield is usually observed in:", "options": ["Consumption commodities during scarcity", "Equity index futures", "Currency futures", "Government bond futures"], "answer": 0, "why": ["The workbook: convenience yield usually arises for consumption assets (commodities) during scarcity, not financial assets like equities, bonds or currencies.", "Key point: It mainly arises for consumption assets (commodities) with low inventory, not financial assets."], "reasons": ["It mainly arises for consumption assets (commodities) with low inventory, not financial assets.", "Equity index is a financial asset", "Currency is a financial asset", "Bonds are financial assets"], "notes": ["Easy way to remember: Convenience yield lives in commodities."], "id": 140}, "141": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "According to the Expectations model, the futures price is:", "options": ["Spot plus cost of carry", "Always equal to the current spot price", "Spot minus dividends", "The expected spot price of the asset at expiry"], "answer": 3, "why": ["The workbook: under the expectations hypothesis, the futures price is the expected spot price of the asset in the future.", "Key point: The expectations hypothesis says futures price reflects the market's expected future spot price."], "reasons": ["That is the cost of carry model", "Futures can trade at a premium or discount", "That is a dividend adjustment, not the model", "The expectations hypothesis says futures price reflects the market's expected future spot price."], "notes": ["Easy way to remember: Expectations model: F = expected future spot."], "id": 141}, "142": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "A market in which futures trade above spot, suggesting the spot price is expected to rise, is called:", "options": ["Backwardation", "Contango", "Convergence", "Normal basis"], "answer": 1, "why": ["The workbook: futures > spot → expectedly rising market = contango. Futures < spot → expectedly falling market = backwardation.", "Key point: Futures > spot = contango (expected rising market). Futures < spot = backwardation."], "reasons": ["Backwardation is futures below spot", "Futures > spot = contango (expected rising market).", "Convergence happens at expiry", "Not a workbook term"], "notes": ["Easy way to remember: Contango climbs; backwardation falls back."], "id": 142}, "143": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "Wheat spot is Rs 2,400/quintal and the 3-month futures is Rs 2,310. Under the Expectations model, the market is in:", "options": ["Backwardation, expecting prices to fall", "Contango, expecting prices to rise", "Equilibrium", "Arbitrage-free contango"], "answer": 0, "why": ["Futures below spot indicates participants expect the spot price to fall — backwardation under the expectations model.", "Key point: Futures below spot → backwardation, indicating expectation of a falling spot price."], "reasons": ["Futures below spot → backwardation, indicating expectation of a falling spot price.", "Contango needs futures above spot", "Prices differ, so not equilibrium", "Not a workbook term"], "notes": ["Easy way to remember: F < S = backwardation."], "id": 143}, "144": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "As per SEBI's October 2024 circular, a new index derivative contract must have a value of not less than ___ at introduction, and lot size is fixed so that the contract value on review day falls within ___.", "options": ["Rs 15 lakh; Rs 15–20 lakh", "Rs 5 lakh; Rs 5–10 lakh", "Rs 10 lakh; Rs 10–15 lakh", "Rs 20 lakh; Rs 20–25 lakh"], "answer": 0, "why": ["The workbook: the earlier Rs 5–10 lakh band was set in 2015. SEBI decided a derivative contract must be worth not less than Rs 15 lakh at introduction, with lot size fixed so contract value on review day is Rs 15–20 lakh, effective November 2024.", "Key point: The earlier Rs 5–10 lakh band (set in 2015) was raised to a minimum of Rs 15 lakh with lot size fixed for a Rs 15–20 lakh contract value, effective November 2024."], "reasons": ["Correct — Rs 15 lakh; Rs 15–20 lakh. The earlier Rs 5–10 lakh band (set in 2015) was raised to a minimum of Rs 15 lakh with lot size fixed for a Rs 15–20 lakh contract value, effective November 2024.", "The old 2015 limit", "Not in the workbook", "Too high"], "notes": ["Easy way to remember: New floor = 15 lakh; band 15–20."], "id": 144}, "145": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "SEBI raised the minimum contract size mainly because:", "options": ["Exchanges wanted higher STT collections", "Market values and prices had risen about three times since the limit was last set in 2015", "Retail participation had fallen", "Lot sizes had become fractional"], "answer": 1, "why": ["The workbook: the limit was last set in 2015; since then broad market values and prices increased around three times.", "Key point: The Rs 5–10 lakh limit dated from 2015; broad market values rose ~3x since then."], "reasons": ["STT is not the stated reason", "The Rs 5–10 lakh limit dated from 2015; broad market values rose ~3x since then.", "Not the stated reason", "Not the stated reason"], "notes": ["Easy way to remember: Markets 3x since 2015 → contract size up."], "id": 145}, "146": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "If a futures price is 25,000 and the exchange must keep contract value between Rs 15 lakh and Rs 20 lakh, which lot size fits?", "options": ["25", "50", "75", "100"], "answer": 2, "why": ["Contract value = price × lot. Choose the lot that keeps value within Rs 15–20 lakh.", "Working: 25,000 × 75 = 18.75 lakh (within band). 50 → 12.5 lakh (too low); 100 → 25 lakh (too high)."], "reasons": ["25 × 25,000 = 6.25 lakh — too low", "50 × 25,000 = 12.5 lakh — too low", "75 × 25,000 = 18.75 lakh — within the band. 25,000 × 75 = 18.75 lakh (within band).", "100 × 25,000 = 25 lakh — too high"], "notes": ["Easy way to remember: Price × lot must land in 15–20 lakh."], "id": 146}, "147": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "Index and stock futures on NSE follow a three-month cycle. On Oct 03, 2025, which contracts are available?", "options": ["Nov, Dec 2025, Jan 2026", "Oct, Nov, Dec 2025", "Oct 2025 only plus weekly", "Oct 2025, Jan 2026, Apr 2026"], "answer": 1, "why": ["The workbook: on Oct 03, 2025, NSE futures were available for the near (Oct), next (Nov) and far (Dec) months.", "Key point: Near (Oct), next (Nov) and far (Dec) month contracts trade simultaneously."], "reasons": ["Oct is still trading on Oct 03", "Near (Oct), next (Nov) and far (Dec) month contracts trade simultaneously.", "Monthly futures, not only Oct", "Not a three-month cycle"], "notes": ["Easy way to remember: Near-Next-Far."], "id": 147}, "148": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "When the near-month futures contract expires on NSE, a new far-month contract is introduced:", "options": ["On the same expiry day after market close only for index", "On the trading day following the expiry day", "One week after expiry", "At the start of the next calendar month"], "answer": 1, "why": ["The workbook: a new contract is introduced on the trading day following the expiry day of the near-month contract.", "Key point: The new contract is introduced on the trading day after the near-month contract expires."], "reasons": ["Not on expiry day", "The new contract is introduced on the trading day after the near-month contract expires.", "Not a week later", "Not tied to the calendar month start"], "notes": ["Easy way to remember: Old expires, new arrives next day."], "id": 148}, "149": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "Under SEBI's May 26, 2025 circular on expiry days, which statement is correct?", "options": ["Each exchange may choose any weekday as expiry", "Exchanges may only choose Tuesday or Thursday as the expiry day for all equity derivatives", "Weekly options are allowed on all indices", "Exchanges can change expiry days without SEBI approval"], "answer": 1, "why": ["Key measures: exchanges can only choose Tuesday or Thursday as expiry for all equity derivatives; only one benchmark index weekly options contract; others minimum 1-month tenor; changing the expiry day needs prior SEBI approval.", "Key point: Only Tuesday or Thursday may be chosen; changing requires prior SEBI approval; only one benchmark index weekly options contract is allowed."], "reasons": ["Only Tuesday or Thursday are allowed", "Only Tuesday or Thursday may be chosen; changing requires prior SEBI approval; only one benchmark index weekly options contract is allowed.", "Only one benchmark index gets weekly options", "SEBI approval is required"], "notes": ["Easy way to remember: Tuesday or Thursday only."], "id": 149}, "150": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "Which exchange-expiry pairing is correct as per the workbook?", "options": ["NSE – Tuesday; BSE – Thursday", "NSE – Thursday; BSE – Tuesday", "Both – Tuesday", "Both – Thursday"], "answer": 0, "why": ["The workbook: \"NSE has chosen Tuesday as its expiry day, and BSE has chosen Thursday.\"", "Key point: NSE chose Tuesday and BSE chose Thursday."], "reasons": ["NSE chose Tuesday and BSE chose Thursday.", "Reversed", "BSE chose Thursday", "NSE chose Tuesday"], "notes": ["Easy way to remember: NSE-Tuesday, BSE-Thursday."], "id": 150}, "151": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "Under the uniform expiry framework, single stock futures and non-benchmark index derivatives must have:", "options": ["Weekly expiries only", "Quarterly expiries only", "A minimum tenor of 1 month, expiring on the last Tuesday/Thursday of the month", "Daily expiries"], "answer": 2, "why": ["The workbook: all equity derivatives other than one benchmark index weekly options — benchmark index futures, non-benchmark index derivatives, single stock F&O — must have a minimum 1-month tenor.", "Key point: Only one benchmark index options contract can be weekly; all other equity derivatives must have at least a 1-month tenor."], "reasons": ["Weekly is only for one benchmark index's options", "Not quarterly-only", "Only one benchmark index options contract can be weekly; all other equity derivatives must have at least a 1-month tenor.", "No daily expiries"], "notes": ["Easy way to remember: Only one weekly; everything else monthly or longer."], "id": 151}, "152": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "NSE's Nifty monthly futures expire on the last Tuesday of the month. If that Tuesday is a trading holiday, expiry is on:", "options": ["The following Wednesday", "The previous trading day", "The next month's first Tuesday", "The last Thursday"], "answer": 1, "why": ["The workbook: contracts expire on the last Tuesday \"(or the day before if the last Tuesday is a trading holiday)\".", "Key point: Expiry moves to the day before (previous trading day) if the last Tuesday is a holiday."], "reasons": ["Expiry is never pushed forward", "Correct — previous trading day. Expiry moves to the day before (previous trading day) if the last Tuesday is a holiday.", "Not the next month", "Thursday is BSE's day"], "notes": ["Easy way to remember: Holiday on expiry → go back a day."], "id": 152}, "153": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "The tick size for Nifty futures is:", "options": ["1 paisa", "10 paise", "5 paise", "Re 1"], "answer": 2, "why": ["The workbook: \"Tick size for Nifty futures is 5 paisa.\"", "Key point: The minimum price movement for Nifty futures is Rs 0.05."], "reasons": ["1 paisa applies to stocks below Rs 250 on NSE", "10 paise is not the tick", "Correct — Rs 0.05. The minimum price movement for Nifty futures is Rs 0.05.", "Re 1 is too large"], "notes": ["Easy way to remember: Nifty tick = 5 paise."], "id": 153}, "154": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "The daily settlement price of a futures contract, as per Chapter 3, is based on:", "options": ["The opening price of the day", "The last half-hour weighted average price of that futures contract", "The average of high and low", "The closing price of the underlying in the cash market"], "answer": 1, "why": ["The workbook: daily settlement price is calculated on the basis of the last half-an-hour weighted average price of that futures contract.", "Key point: Daily settlement uses the last 30 minutes' (volume-)weighted average price of that futures contract."], "reasons": ["Opening price isn't used", "Daily settlement uses the last 30 minutes' (volume-)weighted average price of that futures contract.", "High-low average isn't used", "The underlying's close is used for FINAL settlement, not daily"], "notes": ["⚠️ Important: Daily settlement = futures' own last-30-min average; final settlement = underlying's close.", "Easy way to remember: Daily → futures' last 30 min; Final → spot close."], "id": 154}, "155": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "The final settlement price of Oct Nifty futures is:", "options": ["The last traded price of the Oct futures", "The daily settlement price of the Nov futures", "The opening price on the expiry date", "The closing value of Nifty spot on the expiry date"], "answer": 3, "why": ["The workbook: final settlement price is the closing price of the underlying index in the cash segment on the last trading day.", "Key point: Final settlement is at the closing price of the underlying index in the cash segment on the last trading day."], "reasons": ["The futures' last trade is not used", "Nov futures are unrelated", "The opening price isn't used", "Correct — Nifty spot close on expiry. Final settlement is at the closing price of the underlying index in the cash segment on the last trading day."], "notes": ["Easy way to remember: Final = spot close."], "id": 155}, "156": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "A clearing holiday differs from a trading holiday in that on a clearing holiday:", "options": ["Neither trading nor settlement takes place", "Trading is possible but no clearing/settlement takes place as banks are closed", "Only settlement takes place", "Only options trade"], "answer": 1, "why": ["The workbook: trading holidays — exchanges closed. Clearing holidays — exchanges open and trading possible, but no clearing/settlement as banks are closed.", "Key point: Exchanges are open for trading, but clearing/settlement doesn't happen because banks are shut."], "reasons": ["That is a trading holiday", "Exchanges are open for trading, but clearing/settlement doesn't happen because banks are shut.", "Settlement doesn't happen on clearing holidays", "Not about options"], "notes": ["Easy way to remember: Clearing holiday: trade yes, settle no."], "id": 156}, "157": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "The BSE Sensex futures contract specification in the workbook shows a contract size of:", "options": ["10", "15", "25", "20"], "answer": 3, "why": ["Workbook table: Sensex futures — contract size 20; tick Rs 0.05; 7 serial weekly and 3 serial monthly contracts; monthly expiry last Thursday.", "Key point: Sensex futures: contract size 20, tick Rs 0.05, 7 serial weekly and 3 serial monthly contracts, monthly expiry last Thursday."], "reasons": ["Not 10", "Not 15", "Not 25", "Correct — 20. Sensex futures: contract size 20, tick Rs 0.05, 7 serial weekly and 3 serial monthly contracts, monthly expiry last Thursday."], "notes": ["Easy way to remember: Sensex lot = 20."], "id": 157}, "158": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "Because Sensex and Nifty move with high correlation, traders can use them in a:", "options": ["Pairs trading strategy", "Calendar spread", "Butterfly spread", "Covered call"], "answer": 0, "why": ["The workbook: \"The high correlation between the movements of the Sensex and Nifty enables market participants to trade in Nifty and Sensex futures as part of a pairs trading strategy.\"", "Key point: The workbook mentions pairs trading using Nifty and Sensex futures given their high correlation."], "reasons": ["The workbook mentions pairs trading using Nifty and Sensex futures given their high correlation.", "A calendar spread uses different maturities of the same underlying", "Butterfly is an options strategy", "Covered call uses stock and a short call"], "notes": ["Easy way to remember: Twins → pairs trade."], "id": 158}, "159": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "To roll over a long futures position from the expiring contract to the next month, a trader must:", "options": ["Buy the expiring contract and sell the next contract", "Sell the expiring contract and buy the next contract, simultaneously", "Just buy the next contract", "Convert futures into call options"], "answer": 1, "why": ["The workbook: for a long position, rolling over means selling the expiring contract and buying the next contract; both sides executed at the same time.", "Key point: Rolling a long means selling the near contract and buying the next, executed at the same time."], "reasons": ["Reversed — that rolls a short", "Rolling a long means selling the near contract and buying the next, executed at the same time.", "The expiring long must be closed", "Options are not involved"], "notes": ["Easy way to remember: Roll long = sell near, buy next."], "id": 159}, "160": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "On May 14 the May index futures trades at 22,308.70. Under the expectations model, this means:", "options": ["The index will definitely reach 22,308.70", "The cost of carry is 22,308.70", "The futures will settle at today's spot", "The market expects the spot index to close at 22,308.70 on the May expiry day"], "answer": 3, "why": ["The workbook: under the expectations model, it means the market expects the spot index to settle at 22,308.70 at the close on the last trading day.", "Key point: Participants are predicting the spot index level at one point in time — the close on the last trading day."], "reasons": ["Expectations are not certainties", "22,308.70 is the futures price, not the carry", "Futures settle at expiry spot, not today's spot", "Participants are predicting the spot index level at one point in time — the close on the last trading day."], "notes": ["Easy way to remember: Futures price = crowd's guess of the expiry close."], "id": 160}, "161": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "An arbitrageur buys stock at Rs 100 in cash and sells May futures at Rs 110 (lot 50). At expiry the stock is Rs 95. His total arbitrage profit for the lot is:", "options": ["Rs 250", "Rs 500", "Rs 750", "−Rs 250"], "answer": 1, "why": ["Workbook example: buy cash at 100, sell futures at 110 → Rs 10 locked per share whatever the expiry price. At 95: cash −5, futures +15.", "Working: Cash leg: 95 − 100 = −5. Futures leg: 110 − 95 = +15. Net = +10 × 50 = 500. Locked irrespective of the expiry price (before costs)."], "reasons": ["250 is half the locked profit", "(−5 + 15) × 50 = 500. Cash leg: 95 − 100 = −5.", "750 counts only the futures leg", "The arbitrage doesn't lose money here"], "notes": ["Easy way to remember: Spread locked = profit locked."], "id": 161}, "162": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "Same arbitrage (buy cash at 100, sell futures at 110, lot 50), expiry price Rs 130. Profit for the lot:", "options": ["Rs 500", "Rs 1,500", "−Rs 1,000", "Rs 2,000"], "answer": 0, "why": ["Same locked Rs 10 spread. At 130: cash +30, futures −20.", "Working: Cash +30; futures −20; net +10 × 50 = 500. The spread was locked at entry."], "reasons": ["(30 − 20) × 50 = 500. Cash +30; futures −20; net +10 × 50 = 500.", "1,500 counts only the cash leg", "The futures loss is fully offset by the cash gain", "2,000 is wrong"], "notes": ["Easy way to remember: Direction doesn't matter once the spread is locked."], "id": 162}, "163": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "The biggest execution risk faced by an arbitrageur is:", "options": ["Time lag or illiquidity causing only one leg to be executed, leaving a naked exposure", "Unlimited profits", "Receiving too much MTM", "Futures converging to spot at expiry"], "answer": 0, "why": ["The workbook: there may be a time lag between legs; if one leg is illiquid, only one leg may execute, leaving the arbitrageur with a naked exposure.", "Key point: If one leg is illiquid and doesn't execute, the arbitrageur is left with an unhedged position."], "reasons": ["Correct — legging risk. If one leg is illiquid and doesn't execute, the arbitrageur is left with an unhedged position.", "Unlimited profits aren't a risk", "MTM receipts aren't a risk", "Convergence is what makes arbitrage work"], "notes": ["Easy way to remember: One leg filled, one leg not = naked."], "id": 163}, "164": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "A strike by factory workers that hits a company's sales is an example of:", "options": ["Systematic risk", "Liquidity risk", "Interest rate risk", "Unsystematic (specific) risk"], "answer": 3, "why": ["The workbook lists strikes, loss of key managers and a strong new competitor as examples of specific (unsystematic) risk.", "Key point: Company-specific events are unsystematic risk, reducible by diversification."], "reasons": ["Systematic risk is economy-wide", "Liquidity risk is about exiting positions", "Interest rate risk is a market-wide factor", "Company-specific events are unsystematic risk, reducible by diversification."], "notes": ["Easy way to remember: Company-only event = unsystematic."], "id": 164}, "165": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "A sudden change in RBI monetary policy that moves the whole market is:", "options": ["Unsystematic risk", "Operational risk", "Systematic (market) risk", "Counterparty risk"], "answer": 2, "why": ["Workbook examples of systematic risk: sudden change in monetary or fiscal policy, currency depreciation, declaration of war.", "Key point: Economy-wide factors (monetary/fiscal policy, war, currency depreciation) are systematic, non-diversifiable risk."], "reasons": ["Unsystematic risk is company-specific", "Operational risk is about processes", "Economy-wide factors (monetary/fiscal policy, war, currency depreciation) are systematic, non-diversifiable risk.", "Counterparty risk is about default"], "notes": ["Easy way to remember: Hits everyone = systematic."], "id": 165}, "166": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "A stock has a beta of 2. Historically, if the index rose 10%, the stock would have moved about:", "options": ["20%", "5%", "12%", "2%"], "answer": 0, "why": ["The workbook: a beta of 2 means historically the stock moved 20% when the index moved 10% — more volatile than the index.", "Working: Beta 2 → stock moves twice the index: 2 × 10% = 20%. The stock is more volatile than the index."], "reasons": ["2 × 10% = 20%. Beta 2 → stock moves twice the index: 2 × 10% = 20%.", "5% would be beta 0.5", "12% would be beta 1.2", "2% confuses beta with a percentage"], "notes": ["Easy way to remember: Stock move ≈ beta × index move."], "id": 166}, "167": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "A portfolio has four stocks with betas 0.5, 1.1, 1.3 and 0.9 and weights 35%, 15%, 20% and 30%. Portfolio beta is:", "options": ["0.95", "0.87", "0.95 × 4", "1.00"], "answer": 1, "why": ["Workbook example: portfolio beta = weighted average of individual betas: Σ(weight × beta).", "Working: 0.5×0.35 + 1.1×0.15 + 1.3×0.20 + 0.9×0.30 = 0.175 + 0.165 + 0.26 + 0.27 = 0.87."], "reasons": ["0.95 is the simple (unweighted) average", "0.175 + 0.165 + 0.26 + 0.27 = 0.87. 0.5×0.35 + 1.1×0.15 + 1.3×0.20 + 0.9×0.30 = 0.175 + 0.165 + 0.26 + 0.27 = 0.87.", "Multiplying by 4 is meaningless", "1.00 assumes a market portfolio"], "notes": ["⚠️ Important: Always weight by investment proportion — a simple average of the four betas gives 0.95 (a trap).", "Easy way to remember: βp = Σ w × β."], "id": 167}, "168": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "A portfolio: Stock P (beta 1.2, 40%), Q (beta 0.8, 35%), R (beta 1.5, 25%). Portfolio beta:", "options": ["1.135", "1.00", "1.167", "1.25"], "answer": 0, "why": ["Portfolio beta = Σ weight × beta.", "Working: 1.2×0.40 + 0.8×0.35 + 1.5×0.25 = 0.48 + 0.28 + 0.375 = 1.135 (weighted average, not simple average)."], "reasons": ["0.48 + 0.28 + 0.375 = 1.135. 1.2×0.40 + 0.8×0.35 + 1.5×0.25 = 0.48 + 0.28 + 0.375 = 1.135 (weighted average, not simple average).", "1.00 is a guess", "1.167 is the simple average", "1.25 overstates"], "notes": ["Easy way to remember: Weight first, then add."], "id": 168}, "169": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "An investor holds 550 HDFC Bank shares and the futures lot size is 550. To hedge company-specific risk, she should short:", "options": ["0.5 lots", "Lots based on HDFC Bank's beta vs Nifty", "1 lot (1:1 hedge ratio)", "2 lots"], "answer": 2, "why": ["The workbook: when stock futures hedge a single stock, a 1:1 hedge ratio works. With lot 550, one contract hedges 550 shares.", "Key point: Stock futures on the same stock match the underlying, so a 1:1 hedge ratio works."], "reasons": ["Half a lot doesn't hedge fully and lots aren't fractional", "Beta vs Nifty applies to index futures hedging", "Stock futures on the same stock match the underlying, so a 1:1 hedge ratio works.", "2 lots over-hedges"], "notes": ["Easy way to remember: Same stock → 1:1."], "id": 169}, "170": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "Why can't a 1:1 hedge ratio be used when hedging a 10-stock portfolio with index futures?", "options": ["Index futures are cash settled", "Index futures have no lot size", "SEBI prohibits it", "The portfolio differs from the index in composition and beta"], "answer": 3, "why": ["The workbook: the index futures contract represents 30 or 50 stocks, not the investor's 10, and the portfolio beta may differ from the index's; so the hedge ratio uses beta.", "Key point: The hedging instrument (index) differs from the portfolio; beta adjusts for the relative sensitivity."], "reasons": ["Cash settlement is not the reason", "Index futures do have a lot size", "Not prohibited", "The hedging instrument (index) differs from the portfolio; beta adjusts for the relative sensitivity."], "notes": ["Easy way to remember: Different basket → use beta."], "id": 170}, "171": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "Portfolio value Rs 90 lakh, beta 1.3; index futures at 17,700, lot 50. Number of contracts to hedge:", "options": ["13", "10", "15", "17"], "answer": 0, "why": ["Workbook formula: Number of contracts = Vp × βp ÷ Vi, where Vi = futures level × lot size.", "Working: N = (90,00,000 × 1.3) / (17,700 × 50) = 1,17,00,000 / 8,85,000 = 13.22 ≈ 13 contracts (short)."], "reasons": ["90,00,000 × 1.3 ÷ (17,700 × 50) = 13.22 → 13. N = (90,00,000 × 1.3) / (17,700 × 50) = 1,17,00,000 / 8,85,000 = 13.22 ≈ 13 contracts (short).", "10 ignores beta", "15 over-hedges", "17 over-hedges"], "notes": ["Easy way to remember: N = Value × Beta ÷ (Futures × Lot)."], "id": 171}, "172": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "Portfolio value Rs 1.5 crore, beta 1.2; Nifty futures at 24,000, lot 75. How many lots to short for a full hedge?", "options": ["10", "8", "12", "83"], "answer": 0, "why": ["N = Vp × βp ÷ (futures × lot).", "Working: N = 1,50,00,000 × 1.2 / (24,000 × 75) = 1,80,00,000 / 18,00,000 = 10."], "reasons": ["1,50,00,000 × 1.2 ÷ 18,00,000 = 10. N = 1,50,00,000 × 1.2 / (24,000 × 75) = 1,80,00,000 / 18,00,000 = 10.", "8 would ignore beta and round down wrongly", "12 is not the result", "83 forgets to multiply the futures by the lot size"], "notes": ["Easy way to remember: Convert crore carefully: 1.5 crore = 1,50,00,000."], "id": 172}, "173": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "An investor expects to receive funds next month and fears the market will rise before then. The appropriate futures strategy is a:", "options": ["Short hedge", "Cross hedge", "Calendar spread", "Long hedge"], "answer": 3, "why": ["The workbook: a long hedge is going long futures to hedge a planned future purchase; on receiving money, invest in cash and unwind futures.", "Key point: Buying index futures now locks in the entry level for a planned future purchase — a long hedge."], "reasons": ["A short hedge protects existing holdings", "A cross hedge uses a related asset", "A calendar spread uses two maturities", "Buying index futures now locks in the entry level for a planned future purchase — a long hedge."], "notes": ["Easy way to remember: Will buy later → buy futures now."], "id": 173}, "174": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "A portfolio holder planning to sell next month and fearing a fall should use a:", "options": ["Long hedge", "Short hedge", "Reverse cash-and-carry", "Naked long"], "answer": 1, "why": ["The workbook: to protect a portfolio you plan to liquidate, short index futures of an equivalent amount; futures profits offset cash losses.", "Key point: Shorting index futures protects the portfolio's value — a short hedge."], "reasons": ["A long hedge is for planned purchases", "Shorting index futures protects the portfolio's value — a short hedge.", "Reverse arbitrage is not a hedge", "A naked long increases risk"], "notes": ["Easy way to remember: Will sell later → sell futures now."], "id": 174}, "175": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "An airline hedges jet fuel using crude oil futures because jet fuel futures are unavailable. This is a:", "options": ["Long hedge", "Calendar spread", "Cross hedge", "Inter-exchange arbitrage"], "answer": 2, "why": ["The workbook: when futures on your asset aren't available, trade futures of a closely associated asset — a cross hedge. The workbook's example is jet fuel hedged with crude, heating oil or gasoline.", "Key point: Using futures on a closely related asset is a cross hedge. Hedging a portfolio with index futures is also a (crude) cross hedge."], "reasons": ["Direction alone doesn't define this", "A calendar spread involves two maturities", "Using futures on a closely related asset is a cross hedge.", "Not arbitrage"], "notes": ["Easy way to remember: Related asset = cross hedge."], "id": 175}, "176": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "On May 10, an investor decides to sell his portfolio on June 20 and wants to hedge with index futures. Which contract should he short?", "options": ["June contract", "May contract", "July contract", "Any weekly contract"], "answer": 0, "why": ["The workbook's thumb rule: select the futures contract that expires just after the date you wish to unwind; here short the June contract, not May.", "Key point: Thumb rule: use the contract expiring just after the date you unwind. June expiry (last Tuesday) falls after June 20."], "reasons": ["Thumb rule: use the contract expiring just after the date you unwind.", "May expires before June 20 — the hedge would lapse", "July is further than necessary", "Weekly contracts aren't the workbook's recommendation"], "notes": ["Easy way to remember: Hedge month = first expiry after your exit date."], "id": 176}, "177": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "A spread position consisting of long and short positions in two contracts with the same maturity on different products is called:", "options": ["Calendar spread", "Horizontal spread", "Inter-commodity (inter-product) spread", "Time spread"], "answer": 2, "why": ["The workbook: same maturity, different products = inter-commodity/inter-product spread; same product, different maturities = calendar/time/horizontal spread.", "Key point: Same maturity, different products = inter-commodity spread. Same product, different maturities = calendar/time/horizontal spread."], "reasons": ["Calendar spread uses different maturities", "Horizontal spread = calendar spread", "Same maturity, different products = inter-commodity spread.", "Time spread = calendar spread"], "notes": ["Easy way to remember: Different products = inter-commodity; different months = calendar."], "id": 177}, "178": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "August futures on stock Z trade at Rs 101 on NSE and Rs 100 on BSE. The inter-market arbitrageur will:", "options": ["Buy on NSE and sell on BSE", "Buy on both", "Wait for expiry", "Buy on BSE and sell on NSE"], "answer": 3, "why": ["The workbook: buy the contract at BSE (100) and sell at NSE (101); reverse when the difference squeezes.", "Key point: Buy cheap (BSE, 100) and sell expensive (NSE, 101); reverse when the difference squeezes."], "reasons": ["Buying the costlier one is backwards", "Buying both is not arbitrage", "Waiting doesn't capture the gap", "Buy cheap (BSE, 100) and sell expensive (NSE, 101); reverse when the difference squeezes."], "notes": ["Easy way to remember: Buy the cheap exchange, sell the dear one."], "id": 178}, "179": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "Arbitrageurs, unlike traders, generally:", "options": ["Take naked positions", "Bet on direction", "Lock in their profits through simultaneous offsetting trades", "Avoid liquid markets"], "answer": 2, "why": ["The workbook: \"arbitrageurs generally lock in their profits unlike traders who trade naked contracts.\"", "Key point: Arbitrageurs lock in profits; traders take naked directional positions."], "reasons": ["That is traders", "That is traders", "Arbitrageurs lock in profits; traders take naked directional positions.", "Arbitrageurs prefer liquid markets"], "notes": ["Easy way to remember: Arbitrageur locks; trader bets."], "id": 179}, "180": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "A trader expects Sensex one-month futures (now 61,000) to settle higher at expiry. He should:", "options": ["Short Sensex futures", "Buy a calendar spread", "Go long Sensex futures", "Sell index stocks"], "answer": 2, "why": ["The workbook: a trader with a view that the index will settle higher takes a long position in index futures.", "Key point: A bullish view with no underlying position → naked long futures."], "reasons": ["Short is for a bearish view", "A calendar spread has no directional bet", "A bullish view with no underlying position → naked long futures.", "Selling stocks is bearish"], "notes": ["Easy way to remember: Bullish view → long futures."], "id": 180}, "181": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "The one-month and two-month futures on a stock trade at Rs 505 and Rs 509 while spot is Rs 500. What does the Rs 4 difference between the two futures represent in theory?", "options": ["Initial margin", "STT", "Dividend yield for two months", "Cost of carry for the extra month"], "answer": 3, "why": ["The workbook: the price difference between consecutive maturities should equal the cost of carrying the asset between those dates.", "Key point: The price difference between consecutive maturities should equal the carry cost between those dates."], "reasons": ["Margins don't affect price differences", "STT is a transaction tax", "A dividend reduces carry; it is not the difference itself", "The price difference between consecutive maturities should equal the carry cost between those dates."], "notes": ["Easy way to remember: Futures ladder steps = carry."], "id": 181}, "182": {"ch": 3, "chapter": "Introduction to Forwards and Futures", "q": "Leverage in futures is described as a \"double-edged sword\" because:", "options": ["It doubles margin requirements", "It magnifies both gains and losses relative to capital deployed", "It applies to both exchanges", "It forces physical delivery"], "answer": 1, "why": ["The workbook: futures positions are leveraged; if the price moves the other way the trader can suffer a large loss — \"Leverage acts as a double-edged sword.\"", "Key point: Small margin controls a large contract — favourable moves give big percentage gains, adverse moves big losses."], "reasons": ["Leverage doesn't double margins", "Small margin controls a large contract — favourable moves give big percentage gains, adverse moves big losses.", "Not about exchanges", "Not about delivery"], "notes": ["Easy way to remember: Small money controls big exposure — both ways."], "id": 182}, "183": {"ch": 4, "chapter": "Introduction to Options", "q": "The main reason options emerged, according to the workbook, is that some participants want to:", "options": ["Ride the upside while restricting the downside", "Avoid paying margins entirely", "Settle all contracts physically", "Earn a fixed interest income"], "answer": 0, "why": ["The workbook: futures have linear payoffs with unlimited losses and profits; \"some market participants desire to ride the upside but restrict the downside\", so options emerged.", "Key point: Futures have linear, unlimited payoffs; options let the buyer participate in favourable moves while limiting loss to the premium."], "reasons": ["Futures have linear, unlimited payoffs; options let the buyer participate in favourable moves while limiting loss to the premium.", "Option sellers still pay margins", "Index options are cash settled", "Options don't pay interest"], "notes": ["Easy way to remember: Options = upside with a seatbelt."], "id": 183}, "184": {"ch": 4, "chapter": "Introduction to Options", "q": "The option buyer pays the premium:", "options": ["At expiry only if the option is exercised", "Upfront, at the time of buying the option", "In daily instalments via MTM", "Only if the option ends out-of-the-money"], "answer": 1, "why": ["The workbook: \"The option buyer must pay the premium to the option seller upfront, i.e., at the time of buying the option.\"", "Key point: The premium is paid upfront. (SEBI also mandates upfront collection of the full premium from option buyers from Feb 1, 2025.)"], "reasons": ["Not deferred to expiry", "The premium is paid upfront.", "Premium is not paid through MTM", "Premium is paid regardless of outcome"], "notes": ["Easy way to remember: Pay first, decide later."], "id": 184}, "185": {"ch": 4, "chapter": "Introduction to Options", "q": "The writer of a put option has:", "options": ["The right to sell the underlying", "The obligation to sell the underlying if the put is exercised", "The right to buy the underlying", "The obligation to buy the underlying if the put is exercised"], "answer": 3, "why": ["The workbook: the writer has a buy obligation in a put (when the put holder exercises the right to sell) and a sell obligation in a call.", "Key point: The put holder has the right to sell; the put writer must buy if exercised."], "reasons": ["That's the put buyer's right", "That's the call writer's obligation", "That's the call buyer's right", "The put holder has the right to sell; the put writer must buy if exercised."], "notes": ["Easy way to remember: Put holder sells → put writer buys."], "id": 185}, "186": {"ch": 4, "chapter": "Introduction to Options", "q": "The writer of a call option has:", "options": ["A buy obligation", "A right to sell", "No obligation after receiving the premium", "A sell obligation if the call is exercised"], "answer": 3, "why": ["The writer of a call has a sell obligation when the call holder exercises the right to buy.", "Key point: When the call holder exercises the right to buy, the call writer must sell."], "reasons": ["That's the put writer", "Writers have obligations, not rights", "Receiving premium creates the obligation", "When the call holder exercises the right to buy, the call writer must sell."], "notes": ["Easy way to remember: Call holder buys → call writer sells."], "id": 186}, "187": {"ch": 4, "chapter": "Introduction to Options", "q": "In India, index and stock options are:", "options": ["American style", "Bermudan style", "American for stocks, European for index", "European style"], "answer": 3, "why": ["The workbook: \"In India, all index and stock options are European style options\" — exercisable only on the expiry date.", "Key point: All index and stock options in India are European — exercisable only on expiry day."], "reasons": ["American options allow exercise any time before expiry", "Not a workbook category", "No split by type", "All index and stock options in India are European — exercisable only on expiry day."], "notes": ["Easy way to remember: India = European."], "id": 187}, "188": {"ch": 4, "chapter": "Introduction to Options", "q": "\"A European call gives the buyer the right but not the obligation to buy the underlying at the prevailing market price on or before expiry.\" This statement is:", "options": ["True", "False"], "answer": 1, "why": ["Workbook sample — FALSE. A call gives the right to buy at the STRIKE price, and a European option can be exercised ONLY ON the expiry date.", "Key point: Two errors: exercise is at the STRIKE price (not market price), and a European option is exercisable ONLY ON expiry (not \"on or before\")."], "reasons": ["Two errors in the statement", "Correct — the statement is false. Two errors: exercise is at the STRIKE price (not market price), and a European option is exercisable ONLY ON expiry (not \"on or before\")."], "notes": ["⚠️ Important: \"On or before\" describes American options; \"prevailing market price\" is wrong — exercise is at strike.", "Easy way to remember: European = expiry day only, at the strike."], "id": 188}, "189": {"ch": 4, "chapter": "Introduction to Options", "q": "The buyer of an option cannot lose more than the premium paid. This is:", "options": ["True for all options", "True only for European options", "True only for American options", "False for all options"], "answer": 0, "why": ["Workbook sample: true for all options. The buyer's potential loss is limited to the premium paid because he can let the option lapse.", "Key point: For any option buyer, maximum loss is the premium, since he can let the option lapse."], "reasons": ["For any option buyer, maximum loss is the premium, since he can let the option lapse.", "Applies to American options too", "Applies to European options too", "False is wrong"], "notes": ["Easy way to remember: Buyer's worst case = premium gone."], "id": 189}, "190": {"ch": 4, "chapter": "Introduction to Options", "q": "A Nifty 18,400 call trades at Rs 124.50 when Nifty is at 18,315.10. The call is:", "options": ["In-the-money with intrinsic value 84.90", "At-the-money", "In-the-money with time value zero", "Out-of-the-money with intrinsic value zero"], "answer": 3, "why": ["A call is ITM when spot > strike; OTM when spot < strike. Workbook: 18,315.10 < 18,400, so the call is OTM and its entire premium is time value.", "Key point: Call is ITM only when spot > strike. Here 18,315.10 < 18,400, so OTM; entire premium 124.50 is time value."], "reasons": ["84.90 is the PUT's intrinsic value", "ATM would be the strike closest to spot", "It isn't ITM", "Call is ITM only when spot > strike."], "notes": ["Easy way to remember: Call is worth exercising only above the strike."], "id": 190}, "191": {"ch": 4, "chapter": "Introduction to Options", "q": "A Nifty 18,400 put trades at Rs 177.60 with Nifty at 18,315.10. Its intrinsic value and time value are:", "options": ["92.70 and 84.90", "84.90 and 92.70", "0 and 177.60", "177.60 and 0"], "answer": 1, "why": ["Workbook: put intrinsic value = X − S = 84.90; time value = premium − IV = 92.70.", "Working: Put IV = X − S = 18,400 − 18,315.10 = 84.90. Time value = 177.60 − 84.90 = 92.70."], "reasons": ["Values swapped", "Put IV = X − S = 18,400 − 18,315.10 = 84.90.", "The put is ITM, so it has intrinsic value", "Time value exists before expiry"], "notes": ["Easy way to remember: Premium = IV + TV."], "id": 191}, "192": {"ch": 4, "chapter": "Introduction to Options", "q": "XYZ stock is at Rs 286. The Rs 260 call is quoted at Rs 45. Its intrinsic value is:", "options": ["19", "26", "45", "0"], "answer": 1, "why": ["Workbook sample: call intrinsic value = S − X.", "Working: Call IV = S − X = 286 − 260 = 26. (Time value = 45 − 26 = 19.)"], "reasons": ["19 is the time value", "286 − 260 = 26. Call IV = S − X = 286 − 260 = 26.", "45 is the premium", "The call is ITM, so IV isn't zero"], "notes": ["Easy way to remember: Call IV = S − X."], "id": 192}, "193": {"ch": 4, "chapter": "Introduction to Options", "q": "In the same case (stock 286, 260 call at Rs 45), the time value is:", "options": ["26", "19", "45", "71"], "answer": 1, "why": ["Time value = Premium − Intrinsic value.", "Working: Time value = Premium − Intrinsic value = 45 − 26 = 19."], "reasons": ["26 is intrinsic value", "45 − 26 = 19. Time value = Premium − Intrinsic value = 45 − 26 = 19.", "45 is the full premium", "71 adds instead of subtracts"], "notes": ["Easy way to remember: TV = Premium − IV."], "id": 193}, "194": {"ch": 4, "chapter": "Introduction to Options", "q": "A stock is at Rs 1,150. The 1,200 put trades at Rs 68. What are its intrinsic and time values?", "options": ["18 and 50", "0 and 68", "50 and 18", "68 and 0"], "answer": 2, "why": ["Put IV = X − S when positive; time value = premium − IV.", "Working: Put IV = 1,200 − 1,150 = 50; time value = 68 − 50 = 18."], "reasons": ["Swapped", "The put is ITM (spot below strike)", "1,200 − 1,150 = 50; 68 − 50 = 18. Put IV = 1,200 − 1,150 = 50; time value = 68 − 50 = 18.", "Time value is positive before expiry"], "notes": ["Easy way to remember: Put IV = X − S."], "id": 194}, "195": {"ch": 4, "chapter": "Introduction to Options", "q": "A stock is at Rs 540. The 500 put trades at Rs 6. Its intrinsic value is:", "options": ["40", "0", "6", "−40"], "answer": 1, "why": ["Put IV = max(X − S, 0). With spot above strike, the put is OTM and IV is zero.", "Working: Put IV = max(X − S, 0) = max(500 − 540, 0) = 0. Intrinsic value can never be negative."], "reasons": ["40 is the call IV at that strike", "Correct — zero. Put IV = max(X − S, 0) = max(500 − 540, 0) = 0.", "6 is the premium (all time value)", "IV can never be negative"], "notes": ["Easy way to remember: OTM → IV = 0."], "id": 195}, "196": {"ch": 4, "chapter": "Introduction to Options", "q": "Intrinsic value of an option can never be negative because:", "options": ["The holder is not bound to exercise when exercise results in a loss", "SEBI sets a floor", "The writer refunds losses", "Options are always ITM"], "answer": 0, "why": ["The workbook: IV can never be negative because the holder is not bound to exercise when exercise would result in a loss.", "Key point: Minimum intrinsic value is zero because the holder will simply not exercise an unfavourable option."], "reasons": ["Minimum intrinsic value is zero because the holder will simply not exercise an unfavourable option.", "SEBI doesn't set a floor", "Writers don't refund losses", "Options aren't always ITM"], "notes": ["Easy way to remember: Right, not obligation → floor at zero."], "id": 196}, "197": {"ch": 4, "chapter": "Introduction to Options", "q": "Index at 18,415; strikes available: 18,350, 18,400, 18,450. The ATM option is:", "options": ["18,400", "18,350", "18,450", "No option is ATM"], "answer": 0, "why": ["The workbook: an ATM option is the one whose strike is closest to the spot price. Workbook example: index 18,415 → 18,400 strike is ATM.", "Working: ATM = strike closest to spot; 18,400 is 15 points away, closest."], "reasons": ["15 points away — closest. ATM = strike closest to spot; 18,400 is 15 points away, closest.", "65 points away", "35 points away", "There is always a nearest strike"], "notes": ["Easy way to remember: ATM = nearest strike."], "id": 197}, "198": {"ch": 4, "chapter": "Introduction to Options", "q": "A put option is in-the-money when:", "options": ["Spot price < strike price", "Spot price > strike price", "Spot price = strike price", "Premium > intrinsic value"], "answer": 0, "why": ["The workbook: a put is ITM when spot price is lower than strike.", "Key point: A put gives the right to sell at strike; it has value when spot is below strike."], "reasons": ["A put gives the right to sell at strike; it has value when spot is below strike.", "That is OTM for a put", "That is ATM", "Premium vs IV is about time value"], "notes": ["Easy way to remember: Put ITM: spot below strike."], "id": 198}, "199": {"ch": 4, "chapter": "Introduction to Options", "q": "An in-the-money option is:", "options": ["An option with negative intrinsic value", "An option that cannot be profitably exercised immediately", "An option with positive intrinsic value", "An option with zero time value"], "answer": 2, "why": ["Workbook sample: an ITM option has positive intrinsic value — it gives a positive cash flow if exercised immediately.", "Key point: ITM = would give positive cash flow if exercised now, i.e., positive intrinsic value."], "reasons": ["IV can't be negative", "That describes OTM", "ITM = would give positive cash flow if exercised now, i.e., positive intrinsic value.", "Zero time value applies at expiry"], "notes": ["Easy way to remember: ITM = positive IV."], "id": 199}, "200": {"ch": 4, "chapter": "Introduction to Options", "q": "ATM and OTM options have:", "options": ["Only intrinsic value", "Both intrinsic and time value", "Neither — their premium is zero", "Only time value"], "answer": 3, "why": ["The workbook: \"ATM and OTM options have only time value because the intrinsic value of such options is zero.\"", "Key point: Their intrinsic value is zero, so the entire premium is time value."], "reasons": ["They have zero IV", "Only ITM options have both", "Premiums are positive before expiry", "Their intrinsic value is zero, so the entire premium is time value."], "notes": ["Easy way to remember: ATM/OTM = pure time value."], "id": 200}, "201": {"ch": 4, "chapter": "Introduction to Options", "q": "Assignment of options means:", "options": ["Allocation of exercised options to one or more option sellers", "Buying an option", "Transferring options to another broker", "Rolling over options"], "answer": 0, "why": ["The workbook: \"Assignment of options means the allocation of exercised options to one or more option sellers.\"", "Key point: When a holder exercises, the exercise is assigned to option writers of the same series."], "reasons": ["When a holder exercises, the exercise is assigned to option writers of the same series.", "Buying is an opening purchase", "Transfer between brokers isn't assignment", "Rolling over is different"], "notes": ["Easy way to remember: Holder exercises → writer gets assigned."], "id": 201}, "202": {"ch": 4, "chapter": "Introduction to Options", "q": "A trader holding a long call wants to close it. He must:", "options": ["Buy a put with the same strike", "Sell futures", "Buy another call", "Sell the same call (same strike, same expiry) — a closing sale"], "answer": 3, "why": ["The workbook: \"A trader does not close out a long call position by purchasing a put.\" Closing requires the same strike and expiry — a closing sale.", "Key point: Closing requires an offsetting transaction in the same contract. Buying a put does not close a long call."], "reasons": ["Buying a put creates a new position", "Futures don't close options", "Buying adds to the position", "Closing requires an offsetting transaction in the same contract."], "notes": ["Easy way to remember: Close with the same contract."], "id": 202}, "203": {"ch": 4, "chapter": "Introduction to Options", "q": "A trader who had written 5 calls now buys 5 identical calls. This is a:", "options": ["Opening purchase", "Opening sale", "Closing purchase (\"covering\")", "Closing sale"], "answer": 2, "why": ["The workbook: a closing purchase reduces or eliminates a short position, \"frequently referred to as covering a short position\".", "Key point: A purchase that reduces a short position is a closing purchase, also called covering."], "reasons": ["An opening purchase creates/increases a long", "An opening sale creates a short", "Correct — covering. A purchase that reduces a short position is a closing purchase, also called covering.", "A closing sale reduces a long"], "notes": ["Easy way to remember: Buy back what you sold = covering."], "id": 203}, "204": {"ch": 4, "chapter": "Introduction to Options", "q": "A trader already long 2 calls buys 3 more of the same series. This is a/an:", "options": ["Opening purchase", "Closing purchase", "Closing sale", "Assignment"], "answer": 0, "why": ["The workbook: an opening purchase creates or increases a long position in a given series.", "Key point: An opening purchase creates or increases a long position."], "reasons": ["An opening purchase creates or increases a long position.", "Closing purchase reduces a short", "Closing sale reduces a long", "Assignment is for writers"], "notes": ["Easy way to remember: Adding to longs = opening purchase."], "id": 204}, "205": {"ch": 4, "chapter": "Introduction to Options", "q": "The Nifty 18,400 call premium is Rs 124.50 and lot size is 50. Total premium payable for one lot is:", "options": ["Rs 124.50", "Rs 8,880", "Rs 6,225", "Rs 9,20,000"], "answer": 2, "why": ["The workbook: premium is quoted per unit; total = premium × lot size. Workbook: 124.50 × 50 = 6,225.", "Working: 124.50 × 50 = 6,225."], "reasons": ["Per unit only", "8,880 is the put's total premium (177.60 × 50)", "124.50 × 50 = 6,225.", "9,20,000 is the contract value"], "notes": ["Easy way to remember: Premium × lot = cash outlay."], "id": 205}, "206": {"ch": 4, "chapter": "Introduction to Options", "q": "Stock options on NSE follow which trading cycle?", "options": ["Weekly only", "Quarterly cycle", "Half-yearly cycle", "Three-month cycle — near, next and far month"], "answer": 3, "why": ["The workbook: stock options on NSE follow a three-month trading cycle (near, next, far month).", "Key point: Stock options trade in a three-month cycle. Index options have weekly, monthly, quarterly and long-term expiries."], "reasons": ["Weekly options are only for one benchmark index", "Quarterly expiries are for index options", "Half-yearly are for long-term index options", "Stock options trade in a three-month cycle."], "notes": ["Easy way to remember: Stocks → 3 months."], "id": 206}, "207": {"ch": 4, "chapter": "Introduction to Options", "q": "Long-term index options, available after the three quarterly expiries, have:", "options": ["4 annual expiries", "8 half-yearly expiries following the June–December cycle", "12 monthly expiries", "5 yearly expiries"], "answer": 1, "why": ["The workbook: exchanges offer long-term index options having 8 half-yearly expiries (June–December cycle) after the three quarterly expiries.", "Key point: Exchanges offer long-term index options with 8 half-yearly expiries (June–December cycle)."], "reasons": ["Not annual", "Exchanges offer long-term index options with 8 half-yearly expiries (June–December cycle).", "Not 12 monthly", "Not 5 yearly"], "notes": ["Easy way to remember: 8 half-years = 4 years out."], "id": 207}, "208": {"ch": 4, "chapter": "Introduction to Options", "q": "As per SEBI's Oct 01, 2024 circular (effective Nov 20, 2024), weekly expiry derivatives may be offered on:", "options": ["All indices of an exchange", "Only Nifty 50 across all exchanges", "Only one benchmark index per exchange", "No index"], "answer": 2, "why": ["The workbook: exchanges may provide weekly expiry derivatives for only one of their benchmark indices, effective Nov 20, 2024.", "Key point: Each exchange may offer weekly expiry on only one of its benchmark indices (e.g., BSE: Sensex or Bankex, not both)."], "reasons": ["Not all indices", "It is one per exchange, not only Nifty", "Each exchange may offer weekly expiry on only one of its benchmark indices (e.g., BSE: Sensex or Bankex, not both).", "One index is allowed"], "notes": ["Easy way to remember: One exchange, one weekly index."], "id": 208}, "209": {"ch": 4, "chapter": "Introduction to Options", "q": "On NSE, the tick size for a stock trading below Rs 250 is:", "options": ["Rs 0.01", "Rs 0.05", "Rs 0.10", "Re 1"], "answer": 0, "why": ["The workbook: NSE tick size is 0.01 for stocks below Rs 250 and 0.05 above Rs 250; this applies to their futures too. On BSE, 0.01 applies below Rs 100.", "Key point: The workbook states Rs 0.01 below Rs 250 and Rs 0.05 above Rs 250, applying to futures of these stocks too. (On BSE, 0.01 applies below Rs 100.)"], "reasons": ["The workbook states Rs 0.01 below Rs 250 and Rs 0.05 above Rs 250, applying to futures of these stocks too.", "0.05 is for stocks above Rs 250", "Not 0.10", "Not Re 1"], "notes": ["Easy way to remember: NSE: below 250 → 1 paisa."], "id": 209}, "210": {"ch": 4, "chapter": "Introduction to Options", "q": "Which is true about daily settlement of options?", "options": ["There is no daily MTM settlement of options; premium is settled and final exercise settlement occurs at expiry", "Options are marked to market daily like futures for both buyer and seller", "Options are settled weekly", "Only option buyers pay daily MTM"], "answer": 0, "why": ["The workbook: \"Unlike the futures contracts, there is no daily settlement of options contracts.\" Exercise/assignment happens only on expiry.", "Key point: Unlike futures, there's no daily settlement of option contracts; the seller's risk is handled through margins."], "reasons": ["Unlike futures, there's no daily settlement of option contracts; the seller's risk is handled through margins.", "Options aren't MTM-settled daily like futures", "Not weekly", "Buyers pay premium upfront, not daily MTM"], "notes": ["Easy way to remember: Futures settle daily; options settle at expiry."], "id": 210}, "211": {"ch": 4, "chapter": "Introduction to Options", "q": "The final settlement price of index and stock options in India is:", "options": ["The option's last traded premium", "The closing price of the underlying in the cash segment on the last trading day", "The average price of the underlying over the expiry week", "The strike price"], "answer": 1, "why": ["The workbook: the closing price of the relevant index or stock in the cash segment on the last trading day.", "Key point: Final settlement is at the underlying's closing price on the expiry day."], "reasons": ["Not the option premium", "Final settlement is at the underlying's closing price on the expiry day.", "Not a weekly average", "The strike is fixed, not a settlement price"], "notes": ["Easy way to remember: Options settle on the spot close."], "id": 211}, "212": {"ch": 4, "chapter": "Introduction to Options", "q": "BSE Sensex options, per the workbook specification, have a contract size of:", "options": ["10", "15", "30", "20"], "answer": 3, "why": ["Workbook table: Sensex options — contract size 20, tick Rs 0.05, European, cash settled.", "Key point: Sensex options: contract size 20, tick Rs 0.05, European, cash settled; monthly/quarterly/semi-annual expiry on last Thursday; weekly on Thursday."], "reasons": ["Not 10", "Not 15", "Not 30", "Correct — 20. Sensex options: contract size 20, tick Rs 0.05, European, cash settled; monthly/quarterly/semi-annual expiry on last Thursday; weekly on Thursday."], "notes": ["Easy way to remember: Sensex lot = 20 (futures and options)."], "id": 212}, "213": {"ch": 4, "chapter": "Introduction to Options", "q": "You buy a 17,500 index call at Rs 95 when the index is at 17,562. The break-even at expiry is:", "options": ["17,405", "17,500", "17,657", "17,595"], "answer": 3, "why": ["The workbook: BEP for a call = Strike + Premium. Workbook: 17,500 + 95 = 17,595.", "Working: Call BEP = Strike + Premium = 17,500 + 95 = 17,595."], "reasons": ["17,405 is strike − premium (put formula)", "Strike itself — ignores premium", "17,657 adds the premium to spot", "Call BEP = Strike + Premium = 17,500 + 95 = 17,595."], "notes": ["Easy way to remember: Call BEP = X + P."], "id": 213}, "214": {"ch": 4, "chapter": "Introduction to Options", "q": "Same long call (strike 17,500, premium 95). If the index closes at 18,000 on expiry, the net profit per unit is:", "options": ["500", "405", "595", "95"], "answer": 1, "why": ["Workbook: payoff 500, less premium 95 → net profit 405.", "Working: Payoff = 18,000 − 17,500 = 500; net = 500 − 95 = 405."], "reasons": ["500 ignores the premium", "Payoff = 18,000 − 17,500 = 500; net = 500 − 95 = 405.", "595 adds the premium", "95 is the premium"], "notes": ["Easy way to remember: Net = payoff − premium."], "id": 214}, "215": {"ch": 4, "chapter": "Introduction to Options", "q": "Same long call (strike 17,500, premium 95), lot size 50. The maximum loss per lot is:", "options": ["Rs 95", "Rs 4,750", "Rs 8,75,000", "Unlimited"], "answer": 1, "why": ["The workbook: maximum loss for a buyer = premium × lot = 95 × 50 = Rs 4,750.", "Working: Maximum loss = premium × lot = 95 × 50 = 4,750."], "reasons": ["Per unit only", "Maximum loss = premium × lot = 95 × 50 = 4,750.", "That is contract value", "A buyer's loss is limited"], "notes": ["Easy way to remember: Buyer's max loss = premium × lot."], "id": 215}, "216": {"ch": 4, "chapter": "Introduction to Options", "q": "A long 17,500 call bought at 95 — at which expiry index level does the buyer lose exactly Rs 45 per unit?", "options": ["17,455", "17,550", "17,545", "17,640"], "answer": 1, "why": ["Net P&L = (S − X) − P for S above X. Solve (S − 17,500) − 95 = −45.", "Working: Net P&L = (S − 17,500) − 95 = −45 → S = 17,550."], "reasons": ["Below strike the loss is the full 95", "S = 17,550 → payoff 50, net −45. Net P&L = (S − 17,500) − 95 = −45 → S = 17,550.", "17,545 gives −50", "17,640 gives +45"], "notes": ["Easy way to remember: Between strike and BEP, loss shrinks point by point."], "id": 216}, "217": {"ch": 4, "chapter": "Introduction to Options", "q": "A trader writes a 17,500 call at Rs 95. The index closes at 17,700 on expiry. His P&L per unit:", "options": ["−105", "+95", "−200", "+105"], "answer": 0, "why": ["Short call P&L = Premium − max(S − X, 0). Workbook table: at 17,700 the short call loses 105.", "Working: Short call loss = −(17,700 − 17,500) + 95 = −200 + 95 = −105."], "reasons": ["95 − 200 = −105. Short call loss = −(17,700 − 17,500) + 95 = −200 + 95 = −105.", "+95 only if the index stays below 17,500", "−200 ignores the premium received", "+105 is the long call's result"], "notes": ["Easy way to remember: Short call = mirror of long call."], "id": 217}, "218": {"ch": 4, "chapter": "Introduction to Options", "q": "The break-even of a SHORT call (strike X, premium P) is:", "options": ["X + P", "X − P", "P − X", "X"], "answer": 0, "why": ["The workbook: \"BEP for a short call position will also be equal to X + P. BEP is independent of position (long or short), it is instrument specific (call option).\"", "Key point: BEP is instrument-specific, not position-specific. For any call it is X + P; for any put X − P."], "reasons": ["BEP is instrument-specific, not position-specific.", "That's the put formula", "Meaningless", "Ignores the premium"], "notes": ["Easy way to remember: BEP depends on call/put, not long/short."], "id": 218}, "219": {"ch": 4, "chapter": "Introduction to Options", "q": "You buy a 17,500 put at Rs 150. The break-even and maximum theoretical profit per unit are:", "options": ["17,650 and unlimited", "17,350 and 17,350", "17,350 and 17,500", "17,500 and 150"], "answer": 1, "why": ["Workbook: put BEP = X − P = 17,350. Max profit when the index falls to zero = 17,500 − 150 = 17,350.", "Working: BEP = X − P = 17,350. Max profit if the index falls to zero = 17,500 − 150 = 17,350."], "reasons": ["A put's profit is not unlimited", "BEP = X − P = 17,350.", "Max profit subtracts the premium", "These are strike and premium, not BEP/profit"], "notes": ["Easy way to remember: Put max profit = X − P (price can't go below 0)."], "id": 219}, "220": {"ch": 4, "chapter": "Introduction to Options", "q": "You sold a put with strike Rs 245 and received Rs 49 premium. Theoretical maximum loss:", "options": ["206", "0", "196", "49"], "answer": 2, "why": ["Workbook sample: max loss for a short put occurs when the stock goes to zero: X − P = 245 − 49 = 196.", "Working: Worst case: stock goes to 0. Loss = 245 − 49 = 196."], "reasons": ["206 is an arithmetic slip", "The writer can lose", "Worst case: stock goes to 0.", "49 is the maximum GAIN"], "notes": ["Easy way to remember: Short put worst case = X − P."], "id": 220}, "221": {"ch": 4, "chapter": "Introduction to Options", "q": "A trader buys an 800 put at Rs 25. At expiry the stock is Rs 760. Net profit per share:", "options": ["40", "25", "−10", "15"], "answer": 3, "why": ["Long put net = (X − S) − P.", "Working: Payoff = 800 − 760 = 40; net = 40 − 25 = 15. (BEP = 775.)"], "reasons": ["40 ignores the premium", "25 is the premium", "−10 has the wrong sign", "800 − 760 − 25 = 15. Payoff = 800 − 760 = 40; net = 40 − 25 = 15."], "notes": ["Easy way to remember: Put BEP = 775; below that, profit."], "id": 221}, "222": {"ch": 4, "chapter": "Introduction to Options", "q": "A trader writes a 900 put at Rs 20. At expiry the stock is Rs 850. His P&L per share:", "options": ["+20", "−50", "−30", "+30"], "answer": 2, "why": ["Short put P&L = Premium − max(X − S, 0).", "Working: Short put pays out 900 − 850 = 50; net = 20 − 50 = −30."], "reasons": ["+20 only if the stock stays above 900", "−50 ignores the premium", "20 − 50 = −30. Short put pays out 900 − 850 = 50; net = 20 − 50 = −30.", "+30 has the wrong sign"], "notes": ["Easy way to remember: Writer keeps premium, pays intrinsic."], "id": 222}, "223": {"ch": 4, "chapter": "Introduction to Options", "q": "A trader buys a 1,500 call at Rs 40 (lot 500). At expiry the stock is Rs 1,580. Net P&L for the lot:", "options": ["Rs 20,000", "Rs 40,000", "Rs 60,000", "Rs 80,000"], "answer": 0, "why": ["Net per share = (S − X) − P; then × lot.", "Working: Per share: (1,580 − 1,500) − 40 = 40. Per lot: 40 × 500 = 20,000."], "reasons": ["(80 − 40) × 500 = 20,000. Per share: (1,580 − 1,500) − 40 = 40.", "40,000 ignores the premium", "60,000 is wrong", "80,000 is wrong"], "notes": ["Easy way to remember: Per unit first, then × lot."], "id": 223}, "224": {"ch": 4, "chapter": "Introduction to Options", "q": "A trader writes a 1,200 call at Rs 30. At expiry the stock is Rs 1,275. P&L per share:", "options": ["+30", "−75", "−45", "+45"], "answer": 2, "why": ["Short call P&L = P − (S − X).", "Working: Short call: 30 − (1,275 − 1,200) = 30 − 75 = −45."], "reasons": ["+30 only if below 1,200", "−75 ignores the premium", "30 − 75 = −45. Short call: 30 − (1,275 − 1,200) = 30 − 75 = −45.", "+45 is the buyer's result"], "notes": ["Easy way to remember: Short call loses above X + P."], "id": 224}, "225": {"ch": 4, "chapter": "Introduction to Options", "q": "Which position must pay margin to the exchange?", "options": ["Long call", "Short call", "Long put", "Both long call and long put"], "answer": 1, "why": ["The workbook: the call seller \"must pay a margin to the Exchange on the short position\", as he has an obligation and potentially unlimited losses. Buyers pay no margin.", "Key point: Only option sellers have an obligation and potentially unlimited loss, so they pay margin. Buyers have already paid the premium."], "reasons": ["Buyers pay no margin", "Only option sellers have an obligation and potentially unlimited loss, so they pay margin.", "Buyers pay no margin", "Both are long positions"], "notes": ["Easy way to remember: Obligation → margin."], "id": 225}, "226": {"ch": 4, "chapter": "Introduction to Options", "q": "Why does a long call holder not pay margin?", "options": ["Brokers waive it", "Calls are cash settled", "His payment obligation is limited to the premium already paid", "Calls have unlimited profit potential"], "answer": 2, "why": ["The workbook: the buyer's payment obligation is restricted to the premium already paid; he cannot cause further loss to the system.", "Key point: A margin is needed only when there is an obligation; the buyer has none beyond the premium already paid."], "reasons": ["Not a broker waiver", "Settlement type isn't the reason", "A margin is needed only when there is an obligation; the buyer has none beyond the premium already paid.", "Unlimited profit doesn't create risk to the system"], "notes": ["Easy way to remember: Paid in full already → nothing to secure."], "id": 226}, "227": {"ch": 4, "chapter": "Introduction to Options", "q": "Match the risk-return profile: Short option position has:", "options": ["Unlimited risk, return limited to premium received", "Limited risk, unlimited return", "Limited risk, limited return", "Unlimited risk, unlimited return"], "answer": 0, "why": ["Workbook table: Long — risk = premium paid, return = unlimited. Short — risk = unlimited, return = premium received.", "Key point: Writers keep at most the premium but face (theoretically) unlimited loss."], "reasons": ["Writers keep at most the premium but face (theoretically) unlimited loss.", "That's the long position", "Not for single options", "Returns are capped for shorts"], "notes": ["Easy way to remember: Short options: pick up coins, risk the steamroller."], "id": 227}, "228": {"ch": 4, "chapter": "Introduction to Options", "q": "Options are called products with \"asymmetric\" payoffs because:", "options": ["Premiums are different for calls and puts", "Only buyers pay margins", "Only sellers get premium", "Gains in one direction differ significantly from losses in the other"], "answer": 3, "why": ["The workbook: options have asymmetric risk exposure — gains in one direction differ significantly from losses in the other. Futures are symmetric.", "Key point: E.g., a call buyer's loss is capped at premium, while gains grow with the stock. Futures payoffs are symmetric."], "reasons": ["Premium levels aren't the reason", "Margin is not the reason", "Premium received isn't the reason", "E.g., a call buyer's loss is capped at premium, while gains grow with the stock."], "notes": ["Easy way to remember: Options bend; futures are straight."], "id": 228}, "229": {"ch": 4, "chapter": "Introduction to Options", "q": "A long call on an index at strike 17,500 costs Rs 95 (lot 50). The premium as a percentage of contract value (strike × lot) is approximately:", "options": ["0.54%", "5.4%", "1.08%", "9.5%"], "answer": 0, "why": ["The workbook: an option buyer pays a small premium relative to contract value — this is leverage. 4,750 ÷ 8,75,000.", "Working: Premium = 4,750; contract value = 8,75,000. 4,750/8,75,000 = 0.54% — illustrating option leverage."], "reasons": ["4,750/8,75,000 = 0.54%. Premium = 4,750; contract value = 8,75,000.", "5.4% misplaces the decimal", "1.08% doubles", "9.5% is wrong"], "notes": ["Easy way to remember: Tiny premium, big exposure = leverage."], "id": 229}, "230": {"ch": 4, "chapter": "Introduction to Options", "q": "Which statement about futures vs options is correct?", "options": ["In futures both parties pay/receive daily MTM; in options only the seller is subject to daily margins", "Both buyer and seller of options pay initial margin", "Option buyers face unlimited loss", "Futures give the buyer a right without obligation"], "answer": 0, "why": ["Workbook comparison table: futures — both pay margin and both MTM daily. Options — buyer pays premium; seller deposits margin and only the seller is subject to daily MTM margins.", "Key point: Futures: both parties margined and MTM'd daily. Options: buyer pays premium; only the seller is margined daily."], "reasons": ["Futures: both parties margined and MTM'd daily.", "Buyers don't pay margin", "Buyers' loss is limited", "That describes an option buyer"], "notes": ["Easy way to remember: Futures: both margined. Options: only writer margined."], "id": 230}, "231": {"ch": 4, "chapter": "Introduction to Options", "q": "Who fixes option premiums on Indian exchanges?", "options": ["SEBI", "The stock exchange", "None — premiums are discovered by buyers and sellers in the market", "The clearing corporation"], "answer": 2, "why": ["The workbook: \"Prices are never fixed by stock exchanges or SEBI or anybody.\" Exchanges provide the platform; SEBI ensures smooth functioning; price is discovered by buyers and sellers.", "Key point: Prices are never fixed by exchanges or SEBI; the exchange provides the platform and SEBI ensures smooth functioning."], "reasons": ["SEBI doesn't fix prices", "Exchanges don't fix prices", "Prices are never fixed by exchanges or SEBI; the exchange provides the platform and SEBI ensures smooth functioning.", "The clearing corporation doesn't fix prices"], "notes": ["Easy way to remember: The market sets the premium."], "id": 231}, "232": {"ch": 4, "chapter": "Introduction to Options", "q": "Which is NOT one of the five fundamental factors affecting option price?", "options": ["Spot price", "Strike price", "Trading volume of the option", "Volatility"], "answer": 2, "why": ["The workbook's five factors: spot price, strike price, volatility, time to expiration, interest rates.", "Key point: The five factors are spot, strike, volatility, time to expiry and interest rates."], "reasons": ["Listed factor", "Listed factor", "Trading volume isn't one of the five. The five factors are spot, strike, volatility, time to expiry and interest rates.", "Listed factor"], "notes": ["Easy way to remember: S-X-σ-T-r."], "id": 232}, "233": {"ch": 4, "chapter": "Introduction to Options", "q": "If the underlying rises from 17,500 to 18,000, all else equal, a 17,500 call will ___ and a 17,500 put will ___.", "options": ["Rise; fall", "Rise; rise", "Fall; rise", "Fall; fall"], "answer": 0, "why": ["The workbook: if the underlying goes up, the call value increases and the put value decreases.", "Key point: Higher spot increases call value and reduces put value."], "reasons": ["Higher spot increases call value and reduces put value.", "The put falls", "Reversed", "The call rises"], "notes": ["Easy way to remember: Spot up → call up, put down."], "id": 233}, "234": {"ch": 4, "chapter": "Introduction to Options", "q": "All else equal, as the strike price increases:", "options": ["Call premium rises, put premium falls", "Both rise", "Both fall", "Call premium falls, put premium rises"], "answer": 3, "why": ["The workbook: higher strike reduces the call's intrinsic value (and value) and increases the put's.", "Key point: Higher strike reduces call intrinsic value and raises put intrinsic value."], "reasons": ["Reversed", "Not both", "Not both", "Higher strike reduces call intrinsic value and raises put intrinsic value."], "notes": ["Easy way to remember: Higher strike: bad for calls, good for puts."], "id": 234}, "235": {"ch": 4, "chapter": "Introduction to Options", "q": "With the index at 17,562, which call will trade at a higher premium (same expiry)?", "options": ["17,700 strike", "Both equal", "Cannot be determined", "17,600 strike"], "answer": 3, "why": ["The workbook: with the index at 17,562, a 17,600 call trades higher than a 17,700 call because intrinsic value is progressively lower for higher strikes.", "Key point: Lower strike calls are more valuable; the 17,600 call is closer to the money than 17,700."], "reasons": ["Higher strike → cheaper call", "They differ", "It can be determined", "Lower strike calls are more valuable; the 17,600 call is closer to the money than 17,700."], "notes": ["Easy way to remember: Lower strike call costs more."], "id": 235}, "236": {"ch": 4, "chapter": "Introduction to Options", "q": "An unexpected event sharply increases a stock's volatility. What happens to its call and put premiums?", "options": ["Call rises, put falls", "Both rise", "Call falls, put rises", "Both fall"], "answer": 1, "why": ["The workbook: volatility affects calls and puts the same way — higher volatility, higher premium for both.", "Key point: Higher volatility raises the chance of ending ITM for both, so both premiums increase."], "reasons": ["Put also rises", "Higher volatility raises the chance of ending ITM for both, so both premiums increase.", "Call also rises", "Reversed"], "notes": ["Easy way to remember: Volatility lifts all premiums."], "id": 236}, "237": {"ch": 4, "chapter": "Introduction to Options", "q": "All else equal, a 3-month option vs a 1-month option with the same strike:", "options": ["The 3-month option generally trades higher", "The 1-month option trades higher", "Both trade equally", "Longer maturity lowers premium for calls only"], "answer": 0, "why": ["The workbook: longer maturity → greater uncertainty → higher premium. A 3-month 17,500 option generally trades above a 1-month one.", "Working: More time = more uncertainty = more time value, for both calls and puts."], "reasons": ["More time = more uncertainty = more time value, for both calls and puts.", "Reversed", "They differ", "Time affects both calls and puts"], "notes": ["Easy way to remember: More time, more premium."], "id": 237}, "238": {"ch": 4, "chapter": "Introduction to Options", "q": "Options are called \"wasting assets\" because:", "options": ["They expire worthless always", "Their intrinsic value falls daily", "Their time value decays as expiry approaches", "They pay no dividends"], "answer": 2, "why": ["The workbook: the time value portion decreases with the passage of time (time decay); hence options are \"wasting assets\".", "Key point: Time value erodes with the passage of time (time decay), reaching zero at expiry."], "reasons": ["Not always worthless", "Intrinsic value depends on spot, not time", "Time value erodes with the passage of time (time decay), reaching zero at expiry.", "Dividends are unrelated"], "notes": ["Easy way to remember: Time eats the premium."], "id": 238}, "239": {"ch": 4, "chapter": "Introduction to Options", "q": "The workbook says option sellers have a \"fundamental advantage\" because:", "options": ["They never lose money", "They don't pay margins", "They receive dividends", "The time value component inherently tends to fall, so premiums decline by expiry if other factors are constant"], "answer": 3, "why": ["The workbook: the time value component \"is inherently biased towards reducing in value\", so if all else is constant the option price falls by expiry — an advantage for sellers.", "Key point: Time decay works in the seller's favour; if nothing else changes, the option price falls by expiry."], "reasons": ["Sellers can lose heavily", "Sellers pay margins", "Not about dividends", "Time decay works in the seller's favour; if nothing else changes, the option price falls by expiry."], "notes": ["Easy way to remember: Theta works for the seller."], "id": 239}, "240": {"ch": 4, "chapter": "Introduction to Options", "q": "Higher interest rates, all else equal, will:", "options": ["Increase both call and put premiums", "Decrease call premiums and increase put premiums", "Increase call premiums and decrease put premiums", "Have no effect"], "answer": 2, "why": ["The workbook: \"high interest rates will result in an increase in the value of a call option and a decrease in the value of a put option.\"", "Key point: Higher rates raise call values and lower put values."], "reasons": ["Not both up", "Reversed", "Higher rates raise call values and lower put values.", "Rates do matter"], "notes": ["Easy way to remember: Rates up → calls up, puts down."], "id": 240}, "241": {"ch": 4, "chapter": "Introduction to Options", "q": "Delta measures:", "options": ["Change in option premium for a change in volatility", "Change in delta per unit change in underlying", "Change in option premium per day", "Change in option premium per unit change in the underlying price"], "answer": 3, "why": ["The workbook: Delta = change in option premium ÷ unit change in price of the underlying.", "Key point: Delta = Δ premium / Δ underlying price."], "reasons": ["That's vega", "That's gamma", "That's theta", "Delta = Δ premium / Δ underlying price."], "notes": ["Easy way to remember: Delta = speed vs the underlying."], "id": 241}, "242": {"ch": 4, "chapter": "Introduction to Options", "q": "A call has delta 0.60. If the stock rises by Rs 1, the call premium changes by approximately:", "options": ["Rs 0.60", "Rs 1.60", "Rs 0.40", "Rs 6.00"], "answer": 0, "why": ["The workbook: delta 0.60 means a Re 1 change in the underlying changes the call price by 60 paise.", "Key point: Delta 0.60 → premium changes 60 paise per Rs 1 move."], "reasons": ["Delta 0.60 → premium changes 60 paise per Rs 1 move.", "1.60 adds 1", "0.40 is 1 − delta", "6.00 misplaces the decimal"], "notes": ["Easy way to remember: Delta × move = premium change."], "id": 242}, "243": {"ch": 4, "chapter": "Introduction to Options", "q": "A call premium is Rs 50 with delta 0.45. The stock rises by Rs 4. Using delta only, the new premium is approximately:", "options": ["Rs 54.00", "Rs 50.45", "Rs 48.20", "Rs 51.80"], "answer": 3, "why": ["Approximate new premium = old + delta × change in underlying.", "Working: Change ≈ 0.45 × 4 = 1.80; new premium ≈ 51.80."], "reasons": ["54 assumes delta 1", "50.45 ignores the size of the move", "The call rises when the stock rises", "50 + 0.45 × 4 = 51.80. Change ≈ 0.45 × 4 = 1.80; new premium ≈ 51.80."], "notes": ["Easy way to remember: Multiply delta by the full move."], "id": 243}, "244": {"ch": 4, "chapter": "Introduction to Options", "q": "A put has delta −0.40. The stock rises by Rs 5. The put premium will approximately:", "options": ["Rise by Rs 2", "Rise by Rs 5", "Fall by Rs 2", "Fall by Rs 0.40"], "answer": 2, "why": ["The workbook: put buyer's delta is negative — value rises as the underlying falls. Change = −0.40 × 5.", "Working: Change = −0.40 × 5 = −2. Put value falls when the underlying rises."], "reasons": ["A rising stock hurts a put", "Delta isn't 1", "−0.40 × 5 = −2. Change = −0.40 × 5 = −2.", "0.40 ignores the move size"], "notes": ["Easy way to remember: Put delta negative → stock up, put down."], "id": 244}, "245": {"ch": 4, "chapter": "Introduction to Options", "q": "The delta of a long put and a short put are, respectively:", "options": ["Positive; negative", "Negative; positive", "Both positive", "Both negative"], "answer": 1, "why": ["The workbook: delta for a put buyer is negative; for a put seller the same magnitude with the opposite sign (positive).", "Key point: Long put is like a bearish position (negative delta); the seller has the same magnitude with opposite sign (positive)."], "reasons": ["Reversed", "Long put is like a bearish position (negative delta); the seller has the same magnitude with opposite sign (positive).", "Not both positive", "Not both negative"], "notes": ["Easy way to remember: Long put bearish (−), short put bullish (+)."], "id": 245}, "246": {"ch": 4, "chapter": "Introduction to Options", "q": "Which position has a delta range of 0 to −1?", "options": ["Short call", "Long call", "Short put", "Long futures"], "answer": 0, "why": ["Workbook table: long futures +1; short futures −1; long call 0 to +1; short call 0 to −1; long put 0 to −1; short put 0 to +1.", "Working: Short call: 0 to −1 (loses as underlying rises). Long put is also 0 to −1. Long call and short put are 0 to +1; long futures = +1."], "reasons": ["Correct — short call 0 to −1. Short call: 0 to −1 (loses as underlying rises).", "Long call is 0 to +1", "Short put is 0 to +1", "Long futures = +1"], "notes": ["Easy way to remember: Negative delta = gains when price falls."], "id": 246}, "247": {"ch": 4, "chapter": "Introduction to Options", "q": "The delta of an option is often called the:", "options": ["Time decay", "Hedge ratio", "Volatility ratio", "Leverage factor"], "answer": 1, "why": ["The workbook: \"The delta is often called the hedge ratio.\"", "Key point: Delta tells how many units of underlying offset the option's exposure — the hedge ratio."], "reasons": ["Time decay is theta", "Delta tells how many units of underlying offset the option's exposure — the hedge ratio.", "Not a workbook term", "Not a workbook term"], "notes": ["Easy way to remember: Delta = hedge ratio."], "id": 247}, "248": {"ch": 4, "chapter": "Introduction to Options", "q": "An investor holds 6,000 shares. The call delta is 0.60. How many calls must he write to be delta-neutral?", "options": ["3,600", "10,000", "6,000", "16,000"], "answer": 1, "why": ["The workbook: 'n' shares ÷ delta = number of calls to write for a delta-neutral hedge.", "Working: Calls to write = n / delta = 6,000 / 0.60 = 10,000 (units). Delta of calls = −0.6 × 10,000 = −6,000, offsetting +6,000."], "reasons": ["3,600 multiplies instead of divides", "6,000 ÷ 0.60 = 10,000. Calls to write = n / delta = 6,000 / 0.60 = 10,000 (units).", "6,000 assumes delta 1", "16,000 is wrong"], "notes": ["Easy way to remember: Calls to write = shares ÷ delta."], "id": 248}, "249": {"ch": 4, "chapter": "Introduction to Options", "q": "Gamma measures:", "options": ["Rate of change of delta per unit change in the underlying price", "Sensitivity of premium to interest rates", "Sensitivity of premium to time", "Sensitivity to implied volatility"], "answer": 0, "why": ["The workbook: gamma = change in delta ÷ unit change in underlying price; the second derivative, \"acceleration of the delta\".", "Key point: Gamma is the second derivative — change in delta per unit change in underlying; the \"acceleration\" of delta."], "reasons": ["Gamma is the second derivative — change in delta per unit change in underlying; the \"acceleration\" of delta.", "Interest sensitivity is rho", "Time is theta", "Volatility is vega"], "notes": ["Easy way to remember: Gamma = delta's accelerator."], "id": 249}, "250": {"ch": 4, "chapter": "Introduction to Options", "q": "A call has delta 0.50 and gamma 0.08. If the stock rises Rs 1, the new delta is:", "options": ["0.58", "0.42", "0.50", "0.08"], "answer": 0, "why": ["Workbook example: a Re 1 rise changes delta by 0.08, so new delta = 0.58.", "Working: New delta = 0.50 + 0.08 = 0.58."], "reasons": ["New delta = 0.50 + 0.08 = 0.58.", "Delta rises, not falls", "Ignores gamma", "0.08 is just gamma"], "notes": ["Easy way to remember: New delta = delta + gamma × move."], "id": 250}, "251": {"ch": 4, "chapter": "Introduction to Options", "q": "A call has delta 0.55 and gamma 0.03. The stock falls by Rs 2. The new delta is approximately:", "options": ["0.61", "0.49", "0.52", "0.58"], "answer": 1, "why": ["New delta ≈ delta + gamma × change = 0.55 + 0.03 × (−2).", "Working: Delta change = 0.03 × (−2) = −0.06 → new delta 0.49."], "reasons": ["0.61 adds instead of subtracting", "0.55 − 0.06 = 0.49. Delta change = 0.03 × (−2) = −0.06 → new delta 0.49.", "0.52 uses a Re 1 move", "0.58 is wrong direction"], "notes": ["Easy way to remember: Stock down → call delta down."], "id": 251}, "252": {"ch": 4, "chapter": "Introduction to Options", "q": "A call with 5 days to expiry has theta 1.2. All else constant, its premium will:", "options": ["Rise by Rs 1.20 per day", "Fall by Rs 6 at once today", "Fall by Rs 1.20 per day", "Stay unchanged till expiry"], "answer": 2, "why": ["Workbook example: theta 1.2 means the option price will decline by Rs 1.20 each day till expiry.", "Working: Theta = daily time decay. Premium falls ~Rs 1.20 per day."], "reasons": ["Theta causes decline, not rise", "Decay is daily, not immediate", "Theta = daily time decay.", "Time value does decay"], "notes": ["Easy way to remember: Theta = daily melt."], "id": 252}, "253": {"ch": 4, "chapter": "Introduction to Options", "q": "An option premium is Rs 60 with theta −2.5 per day. After 4 days, with nothing else changing, the premium will be about:", "options": ["Rs 57.50", "Rs 70.00", "Rs 50.00", "Rs 52.50"], "answer": 2, "why": ["Premium after n days ≈ premium + theta × n (theta negative).", "Working: Decay = 2.5 × 4 = 10 → 60 − 10 = 50."], "reasons": ["57.50 is one day", "Premium doesn't rise", "60 − 10 = 50. Decay = 2.5 × 4 = 10 → 60 − 10 = 50.", "52.50 is three days"], "notes": ["Easy way to remember: Theta × days."], "id": 253}, "254": {"ch": 4, "chapter": "Introduction to Options", "q": "Theta for a long option position (call or put) is usually:", "options": ["Positive", "Negative", "Zero", "Positive for calls, negative for puts"], "answer": 1, "why": ["The workbook: \"Usually, theta is negative for a long option, whether it is a call or a put.\"", "Key point: Long options lose time value daily; theta is negative for buyers."], "reasons": ["Positive theta is for writers", "Long options lose time value daily; theta is negative for buyers.", "Not zero", "Same sign for calls and puts"], "notes": ["Easy way to remember: Long options bleed time."], "id": 254}, "255": {"ch": 4, "chapter": "Introduction to Options", "q": "Vega is positive for:", "options": ["Both long call and long put", "Long call only", "Long put only", "Short call and short put"], "answer": 0, "why": ["The workbook: \"Vega is positive for a long call and a long put.\"", "Key point: Higher volatility increases expected reward for any long option; vega is positive for both long calls and puts."], "reasons": ["Higher volatility increases expected reward for any long option; vega is positive for both long calls and puts.", "Also for long put", "Also for long call", "Short options have negative vega"], "notes": ["Easy way to remember: Long options love volatility."], "id": 255}, "256": {"ch": 4, "chapter": "Introduction to Options", "q": "An option costs Rs 80 with vega 5 (Rs per 1 percentage point of volatility). Implied volatility rises from 18% to 21%. The new premium is approximately:", "options": ["Rs 85", "Rs 83", "Rs 105", "Rs 95"], "answer": 3, "why": ["Vega = change in premium per 1 percentage point change in volatility. 3-point rise × 5.", "Working: Change = 5 × 3 = 15 → 80 + 15 = 95."], "reasons": ["85 uses a 1-point rise", "83 uses 3 × 1", "105 overstates", "80 + 15 = 95. Change = 5 × 3 = 15 → 80 + 15 = 95."], "notes": ["Easy way to remember: Vega × vol change."], "id": 256}, "257": {"ch": 4, "chapter": "Introduction to Options", "q": "Rho measures the change in option price for a change in:", "options": ["Risk-free interest rate / cost of funding", "Volatility", "Time", "Underlying price"], "answer": 0, "why": ["The workbook: rho is the change in option price for a one percentage point change in the risk-free interest rate (cost of funding).", "Key point: Rho = change in premium per one percentage point change in risk-free rate."], "reasons": ["Rho = change in premium per one percentage point change in risk-free rate.", "Volatility is vega", "Time is theta", "Underlying is delta"], "notes": ["Easy way to remember: Rho = Rate."], "id": 257}, "258": {"ch": 4, "chapter": "Introduction to Options", "q": "Match the Greek: sensitivity of option price to the passage of one day.", "options": ["Delta", "Gamma", "Theta", "Vega"], "answer": 2, "why": ["The workbook: theta is the change in option price given a one-day decrease in time to expiration.", "Key point: Theta measures time decay."], "reasons": ["Delta — underlying", "Gamma — delta change", "Theta measures time decay.", "Vega — volatility"], "notes": ["Easy way to remember: Theta = Time."], "id": 258}, "259": {"ch": 4, "chapter": "Introduction to Options", "q": "The binomial option pricing model, as per the workbook, was developed by:", "options": ["Fisher Black and Myron Scholes in 1973", "Robert Merton in 1990", "William Sharpe in 1978", "John Hull in 1985"], "answer": 2, "why": ["The workbook: the binomial model was developed by William Sharpe in 1978; Black & Scholes published in 1973.", "Key point: The workbook credits William Sharpe (1978). Black & Scholes published in 1973."], "reasons": ["That's Black-Scholes", "Not in the workbook", "Correct as per the workbook. The workbook credits William Sharpe (1978).", "Not in the workbook"], "notes": ["Easy way to remember: Binomial — Sharpe 1978; B-S — 1973."], "id": 259}, "260": {"ch": 4, "chapter": "Introduction to Options", "q": "Which statement about the Black-Scholes model is correct?", "options": ["It relies on iteration like the binomial model", "It can only price American options", "It is a relatively simple, fast closed-form model using five key inputs, ignoring dividends in its basic form", "It doesn't need volatility"], "answer": 2, "why": ["The workbook: B-S is popular, relatively simple and fast; unlike binomial it does not rely on iteration; uses five inputs; ignores dividends in its basic form.", "Key point: B-S uses stock price, strike, volatility, time and risk-free rate; basic form ignores dividends; no iteration needed."], "reasons": ["That's the binomial model", "Indian options are European", "B-S uses stock price, strike, volatility, time and risk-free rate; basic form ignores dividends; no iteration needed.", "Volatility is a key input"], "notes": ["Easy way to remember: B-S = fast, closed-form, 5 inputs."], "id": 260}, "261": {"ch": 4, "chapter": "Introduction to Options", "q": "Which statement about the binomial model is correct?", "options": ["It is fast but inaccurate", "It assumes prices can take any value at each step", "It was published by Black and Scholes", "It is accurate and flexible as it is iterative, but complex and time-consuming to implement"], "answer": 3, "why": ["The workbook: very accurate because iterative, but complex and time-consuming; prices move only up or down at fixed rates at each step.", "Key point: It models price evolution as a tree of up/down moves; accurate but computationally intensive."], "reasons": ["It is accurate, not inaccurate", "Only two moves per step", "That's Black-Scholes", "It models price evolution as a tree of up/down moves; accurate but computationally intensive."], "notes": ["Easy way to remember: Binomial = accurate but slow tree."], "id": 261}, "262": {"ch": 4, "chapter": "Introduction to Options", "q": "In the Black-Scholes formula C = S·N(d1) − X·e^(−rt)·N(d2), N(x) represents:", "options": ["Natural logarithm", "Number of shares", "Standard normal cumulative distribution function", "Nominal interest rate"], "answer": 2, "why": ["The workbook: N(x) = standard normal cumulative distribution function; ln = natural logarithm.", "Key point: N(x) is the cumulative standard normal distribution; ln is natural log."], "reasons": ["That's \"In/ln\"", "Not shares", "N(x) is the cumulative standard normal distribution; ln is natural log.", "Not an interest rate"], "notes": ["Easy way to remember: N = Normal distribution."], "id": 262}, "263": {"ch": 4, "chapter": "Introduction to Options", "q": "Implied volatility is:", "options": ["Standard deviation of past returns", "Volatility derived by running an option pricing model in reverse using the market price of the option", "Volatility fixed by the exchange", "The VIX value always"], "answer": 1, "why": ["The workbook: traders calculate expected volatility by running the Black-Scholes model in reverse, using the option's market price.", "Key point: Plug the market premium and other inputs into B-S and solve for volatility — this is implied volatility."], "reasons": ["That's historical volatility", "Plug the market premium and other inputs into B-S and solve for volatility — this is implied volatility.", "Exchanges don't fix volatility", "VIX isn't in the workbook definition"], "notes": ["Easy way to remember: IV = volatility backed out of the price."], "id": 263}, "264": {"ch": 4, "chapter": "Introduction to Options", "q": "Historical volatility of a stock is 15%, but IV jumps to 80% a day before a court verdict. Option traders would typically:", "options": ["Sell options because premiums are high", "Buy options aggressively", "Avoid all trades as IV is irrelevant", "Buy futures only"], "answer": 0, "why": ["The workbook: when IV is high, option traders start selling options; when low, they buy. Pharma court-case example: IV 80% vs HV 15%.", "Working: High IV = expensive premiums; traders tend to sell. Low IV favours buying."], "reasons": ["High IV = expensive premiums; traders tend to sell.", "Buying expensive options is the opposite", "IV is highly relevant", "Futures aren't the workbook's suggestion"], "notes": ["Easy way to remember: High IV → sell; low IV → buy."], "id": 264}, "265": {"ch": 4, "chapter": "Introduction to Options", "q": "Historical volatility differs from implied volatility in that historical volatility:", "options": ["Measures past price fluctuations; implied volatility reflects expected volatility over the option's remaining life", "Is forward-looking", "Is always higher", "Is used by exchanges to fix premiums"], "answer": 0, "why": ["The workbook: historical volatility measures past percentage price changes (e.g., std dev of weekly Nifty changes); implied volatility reflects how volatile the stock is expected to be over the option's remaining life.", "Key point: HV is backward-looking (e.g., std dev of weekly Nifty changes over a year); IV is forward-looking."], "reasons": ["HV is backward-looking (e.g., std dev of weekly Nifty changes over a year); IV is forward-looking.", "HV is backward-looking", "HV is not always higher", "Exchanges don't fix premiums"], "notes": ["Easy way to remember: HV looks back; IV looks forward."], "id": 265}, "266": {"ch": 4, "chapter": "Introduction to Options", "q": "For which moneyness is uncertainty (and hence time value) highest?", "options": ["Deep ITM", "ATM", "Deep OTM", "All equal"], "answer": 1, "why": ["The workbook: for ATM options uncertainty is highest — even a small move can tip it ITM or OTM — captured in time value.", "Key point: Small moves can tip an ATM option either way, maximising uncertainty, captured in time value."], "reasons": ["Deep ITM stays ITM", "Small moves can tip an ATM option either way, maximising uncertainty, captured in time value.", "Deep OTM stays OTM", "Not equal"], "notes": ["Easy way to remember: ATM = maximum uncertainty."], "id": 266}, "267": {"ch": 4, "chapter": "Introduction to Options", "q": "Index at 17,562. A 17,300 call trades at 327. Its time value is:", "options": ["65", "327", "262", "0"], "answer": 0, "why": ["Workbook example: IV = 17,562 − 17,300 = 262; time value = 327 − 262 = 65.", "Working: IV = 17,562 − 17,300 = 262; time value = 327 − 262 = 65."], "reasons": ["IV = 17,562 − 17,300 = 262; time value = 327 − 262 = 65.", "327 is the premium", "262 is intrinsic value", "ITM options have time value before expiry"], "notes": ["Easy way to remember: TV = premium − IV."], "id": 267}, "268": {"ch": 4, "chapter": "Introduction to Options", "q": "Index at 17,562. A 17,600 put trades at 167. Its intrinsic and time values are:", "options": ["129 and 38", "0 and 167", "167 and 0", "38 and 129"], "answer": 3, "why": ["Workbook example: put IV = 17,600 − 17,562 = 38; time value 129.", "Working: Put IV = 17,600 − 17,562 = 38; time value = 167 − 38 = 129."], "reasons": ["Swapped", "The put is ITM", "Not at expiry", "Put IV = 17,600 − 17,562 = 38; time value = 167 − 38 = 129."], "notes": ["Easy way to remember: Put IV = X − S."], "id": 268}, "269": {"ch": 4, "chapter": "Introduction to Options", "q": "Calls at strikes 17,300 (327), 17,400 (250), 17,500 (185), 17,600 (130). If the index expires at 17,800, which strike gives the highest ROI?", "options": ["17,500 (62%)", "17,300 (53%)", "17,400 (60%)", "17,600 (54%)"], "answer": 0, "why": ["Workbook: ROI = net profit ÷ premium paid. At 17,800: 173/327 = 53%, 150/250 = 60%, 115/185 = 62%, 70/130 = 54%.", "Working: Profits: 173, 150, 115, 70. ROI = profit / premium: 53%, 60%, 62%, 54%. 17,500 is highest."], "reasons": ["Correct — 62%, highest. Profits: 173, 150, 115, 70.", "53% — lowest ROI", "60%", "54%"], "notes": ["⚠️ Important: The deepest ITM call earns the highest RUPEE profit (173) but the lowest ROI.", "Easy way to remember: ROI = profit ÷ premium."], "id": 269}, "270": {"ch": 4, "chapter": "Introduction to Options", "q": "Using the same calls, at which expiry level does the 17,600 call (premium 130) break even?", "options": ["17,600", "17,730", "17,470", "17,692"], "answer": 1, "why": ["Call BEP = strike + premium.", "Working: BEP = 17,600 + 130 = 17,730."], "reasons": ["The strike ignores the premium", "17,600 + 130 = 17,730. BEP = 17,600 + 130 = 17,730.", "17,470 subtracts", "17,692 is not the BEP"], "notes": ["Easy way to remember: Call BEP = X + P."], "id": 270}, "271": {"ch": 4, "chapter": "Introduction to Options", "q": "Puts at 17,300 (65), 17,400 (91), 17,500 (121), 17,600 (167). If the index falls to 17,000, the ROI on the 17,300 put is about:", "options": ["362%", "259%", "313%", "340%"], "answer": 0, "why": ["Workbook: if the index falls to 17,000: 17,300 put profit 235 → ROI 362%; the workbook notes deep OTM puts give the highest ROI on sharp falls.", "Working: Profit = 17,300 − 17,000 − 65 = 235; ROI = 235/65 = 362%. Deep OTM puts give highest ROI on sharp falls."], "reasons": ["Correct — 235/65 = 362%. Profit = 17,300 − 17,000 − 65 = 235; ROI = 235/65 = 362%.", "259% is the 17,600 put", "313% is the 17,500 put", "340% is the 17,400 put"], "notes": ["Easy way to remember: Cheap put + big fall = biggest % return."], "id": 271}, "272": {"ch": 4, "chapter": "Introduction to Options", "q": "With the same puts, the 17,600 put (premium 167) gives what profit if the index expires at 17,000?", "options": ["433", "600", "167", "259"], "answer": 0, "why": ["Put profit = X − S − P.", "Working: 17,600 − 17,000 − 167 = 433 (ROI 259%)."], "reasons": ["17,600 − 17,000 − 167 = 433. 17,600 − 17,000 − 167 = 433 (ROI 259%).", "600 ignores the premium", "167 is the premium", "259 is the ROI %"], "notes": ["Easy way to remember: Payoff minus premium."], "id": 272}, "273": {"ch": 4, "chapter": "Introduction to Options", "q": "Using the same put table, a seller of the 17,400 put (premium 91) at an expiry of 17,300 will:", "options": ["Gain 91", "Lose 9", "Gain 9", "Lose 100"], "answer": 1, "why": ["Workbook seller table: at 17,300 the 17,400 put seller shows −9.", "Working: Payout = 17,400 − 17,300 = 100; net = 91 − 100 = −9."], "reasons": ["Only above 17,400 does he keep 91", "91 − 100 = −9. Payout = 17,400 − 17,300 = 100; net = 91 − 100 = −9.", "Sign wrong", "Ignores the premium"], "notes": ["Easy way to remember: Writer: premium minus payout."], "id": 273}, "274": {"ch": 4, "chapter": "Introduction to Options", "q": "A call option seller's view is typically:", "options": ["Strongly bullish", "Neutral to bearish", "Neutral to bullish", "Expecting high volatility"], "answer": 1, "why": ["The workbook: \"A call option seller has a neutral to bearish perspective regarding the underlying price.\"", "Key point: A call seller profits if the price stays below strike — neutral to bearish."], "reasons": ["That's a call buyer", "A call seller profits if the price stays below strike — neutral to bearish.", "That's a put seller", "High volatility hurts sellers"], "notes": ["Easy way to remember: Call seller: price stays below strike."], "id": 274}, "275": {"ch": 4, "chapter": "Introduction to Options", "q": "A put option seller's view is typically:", "options": ["Neutral to bullish", "Neutral to bearish", "Strongly bearish", "Expecting a crash"], "answer": 0, "why": ["The workbook: \"A put option seller has a neutral to bullish perspective regarding the underlying price.\"", "Key point: A put writer keeps the premium if the price stays above the strike — neutral to bullish."], "reasons": ["A put writer keeps the premium if the price stays above the strike — neutral to bullish.", "That's a put buyer", "That's a put buyer", "A crash hurts a put seller"], "notes": ["Easy way to remember: Put seller: price stays above strike."], "id": 275}, "276": {"ch": 4, "chapter": "Introduction to Options", "q": "Selling deep ITM puts compared with deep OTM puts:", "options": ["Fetches higher premium but carries higher risk", "Fetches lower premium and lower risk", "Fetches higher premium with lower risk", "Carries no risk"], "answer": 0, "why": ["The workbook: sellers of deep ITM puts face higher risk though they fetch higher premiums; deep OTM puts are less risky but fetch lower premiums.", "Key point: Deep ITM puts earn more premium but are already in the money, so losses are more likely and larger."], "reasons": ["Deep ITM puts earn more premium but are already in the money, so losses are more likely and larger.", "Deep ITM premiums are higher, not lower", "Higher premium comes with higher risk", "Selling options always carries risk"], "notes": ["Easy way to remember: More premium = more risk."], "id": 276}, "277": {"ch": 4, "chapter": "Introduction to Options", "q": "When an index option expires in-the-money, the long holder receives:", "options": ["Delivery of all index stocks", "A new futures position", "The premium back", "Cash equal to the difference between the closing index value and strike"], "answer": 3, "why": ["The workbook: long index option positions are cash-settled on expiry; an ITM call holder receives the difference between the closing index and strike.", "Key point: Index options are cash settled; the holder receives intrinsic value at expiry."], "reasons": ["Index options aren't delivery-settled", "No futures are created", "The premium isn't refunded", "Index options are cash settled; the holder receives intrinsic value at expiry."], "notes": ["Easy way to remember: Index options pay cash intrinsic value."], "id": 277}, "278": {"ch": 4, "chapter": "Introduction to Options", "q": "A trader expects the market to move sharply but is unsure of direction. IV is very low. Which is the most suitable single-leg view based on IV alone?", "options": ["Sell options since IV is low", "Buy futures", "Do nothing", "Buy options since IV is low and premiums are cheap"], "answer": 3, "why": ["The workbook: \"When implied volatility is low, traders like to buy options\"; when high, they sell.", "Key point: The workbook notes traders like to buy options when IV is low (cheap premiums) and sell when IV is high."], "reasons": ["Selling cheap options is the opposite", "Futures need a direction", "Doing nothing ignores the opportunity", "The workbook notes traders like to buy options when IV is low (cheap premiums) and sell when IV is high."], "notes": ["Easy way to remember: Low IV → options are cheap → buy."], "id": 278}, "279": {"ch": 4, "chapter": "Introduction to Options", "q": "A stock at Rs 400 has a 420 call priced at Rs 12 and a 380 put priced at Rs 8. Both options are:", "options": ["ITM", "OTM, and their entire premiums are time value", "ATM", "The call is ITM and the put OTM"], "answer": 1, "why": ["A call is OTM when spot < strike; a put is OTM when spot > strike. OTM options have only time value.", "Key point: Call OTM (400 < 420); put OTM (400 > 380). Intrinsic values are zero; premiums are pure time value."], "reasons": ["Neither is ITM", "Call OTM (400 < 420); put OTM (400 > 380).", "Neither strike is closest", "The call is not ITM"], "notes": ["Easy way to remember: Both OTM → all premium is time value."], "id": 279}, "280": {"ch": 4, "chapter": "Introduction to Options", "q": "Which option has the highest intrinsic value? Stock at Rs 500.", "options": ["480 call", "460 call", "520 put", "530 put"], "answer": 1, "why": ["Call IV = S − X; put IV = X − S.", "Working: 480 call: 20; 460 call: 40; 520 put: 20; 530 put: 30. Highest = 460 call (40)."], "reasons": ["500 − 480 = 20", "500 − 460 = 40 — highest. 480 call: 20; 460 call: 40; 520 put: 20; 530 put: 30.", "520 − 500 = 20", "530 − 500 = 30"], "notes": ["Easy way to remember: Compute each IV, then compare."], "id": 280}, "281": {"ch": 4, "chapter": "Introduction to Options", "q": "An option's premium is Rs 30 and its intrinsic value is Rs 30. It is:", "options": ["Deep OTM", "ATM", "An ITM option with zero time value, typical at expiry", "Impossible"], "answer": 2, "why": ["Premium = IV + TV; if premium equals IV, time value is zero — typical at expiry for ITM options.", "Working: Premium = IV means no time value — typical of ITM options at expiry."], "reasons": ["Deep OTM would have zero IV", "ATM has zero IV", "Premium = IV means no time value — typical of ITM options at expiry.", "It is possible"], "notes": ["Easy way to remember: No time left = no time value."], "id": 281}, "282": {"ch": 4, "chapter": "Introduction to Options", "q": "Which Greek would a trader primarily watch to understand how quickly an option will move from ATM to ITM as the underlying moves?", "options": ["Theta", "Vega", "Rho", "Gamma"], "answer": 3, "why": ["The workbook: gamma \"signifies the speed with which an option will go either in-the-money or out-of-the-money due to a change in price of the underlying asset\".", "Key point: Gamma signals the speed at which delta changes, i.e., how fast the option moves into or out of the money."], "reasons": ["Theta measures time", "Vega measures volatility", "Rho measures rates", "Gamma signals the speed at which delta changes, i.e., how fast the option moves into or out of the money."], "notes": ["Easy way to remember: Gamma = moneyness speed."], "id": 282}, "283": {"ch": 4, "chapter": "Introduction to Options", "q": "A trader is long a call with delta 0.30 on 1,000 shares' worth (units). The stock rises Rs 10. Approximate gain on the position:", "options": ["Rs 300", "Rs 10,000", "Rs 3,000", "Rs 30,000"], "answer": 2, "why": ["Position change ≈ delta × price move × units.", "Working: Gain ≈ delta × move × units = 0.30 × 10 × 1,000 = 3,000."], "reasons": ["300 ignores the units", "10,000 assumes delta 1", "0.30 × 10 × 1,000 = 3,000. Gain ≈ delta × move × units = 0.30 × 10 × 1,000 = 3,000.", "30,000 overstates"], "notes": ["Easy way to remember: Delta × move × quantity."], "id": 283}, "284": {"ch": 4, "chapter": "Introduction to Options", "q": "Which of the following gives the option BUYER the right to sell?", "options": ["Long put", "Long call", "Short call", "Short put"], "answer": 0, "why": ["The workbook: an option giving the holder the right to sell is a put.", "Key point: A put gives the holder the right to sell the underlying at the strike price."], "reasons": ["A put gives the holder the right to sell the underlying at the strike price.", "Long call = right to buy", "Short call = obligation to sell", "Short put = obligation to buy"], "notes": ["Easy way to remember: Put = right to sell."], "id": 284}, "285": {"ch": 4, "chapter": "Introduction to Options", "q": "Put option open interest in the workbook's Nifty quote refers to:", "options": ["Total put contracts outstanding (not yet closed) for that series", "Total puts traded that day", "Number of put buyers", "Premium value of all puts"], "answer": 0, "why": ["The workbook: open interest is the total number of option contracts outstanding for an underlying.", "Key point: Open interest = contracts outstanding; traded volume = contracts traded during the day."], "reasons": ["Open interest = contracts outstanding; traded volume = contracts traded during the day.", "That's traded volume", "Not the number of buyers", "Not premium value"], "notes": ["Easy way to remember: OI = contracts still open."], "id": 285}, "286": {"ch": 4, "chapter": "Introduction to Options", "q": "If the index expires exactly at the strike of a long call bought at premium P, the buyer's result is:", "options": ["Zero", "Loss of P", "Gain of P", "Loss of 2P"], "answer": 1, "why": ["At the strike, payoff is zero, so the buyer loses the premium — workbook table: at 17,500 the long call shows −95.", "Key point: At the strike, payoff is zero, so the buyer loses the full premium."], "reasons": ["The premium is lost", "At the strike, payoff is zero, so the buyer loses the full premium.", "No gain", "The loss can't exceed the premium"], "notes": ["Easy way to remember: At the strike, the buyer loses the whole premium."], "id": 286}, "287": {"ch": 5, "chapter": "Strategies using Equity Futures and Equity Options", "q": "You plan to buy 1,500 ABC shares on June 20 when your FD matures. Today ABC is Rs 455 and June futures are Rs 457.30 (lot 1,500). On June 20, spot is Rs 520 and futures Rs 521.20. What is your effective purchase price per share after squaring off the long futures?", "options": ["Rs 455.00", "Rs 456.10", "Rs 457.30", "Rs 520.00"], "answer": 1, "why": ["Workbook long hedge example: a long futures position locks in the price of a planned future purchase. Net cost = cash cost − futures gain.", "Working: Futures gain = (521.20 − 457.30) × 1,500 = 95,850. Cash cost = 7,80,000. Net = 6,84,150 / 1,500 = 456.10 — close to the locked futures price."], "reasons": ["455 is today's spot, not the effective cost", "7,80,000 − 95,850 = 6,84,150 ÷ 1,500 = 456.10", "457.30 is the futures price; the actual is close to but not exactly this", "520 ignores the futures gain"], "notes": ["Easy way to remember: Long hedge: cash cost up, futures gain offsets."], "id": 287}, "288": {"ch": 5, "chapter": "Strategies using Equity Futures and Equity Options", "q": "Same long hedge (futures bought at 457.30), but on June 20 spot is Rs 390 and futures Rs 391.10. The futures loss and the effective price per share are:", "options": ["Rs 99,300 gain; Rs 323.80", "Rs 99,300 loss; Rs 456.20", "Rs 97,950 loss; Rs 455.30", "Rs 99,300 loss; Rs 390.00"], "answer": 1, "why": ["Workbook: if the stock falls, the futures loss is added to the cheaper cash purchase; the effective price again stays near the futures price.", "Working: Loss = (457.30 − 391.10) × 1,500 = 99,300. Net cost = 5,85,000 + 99,300 = 6,84,300 → Rs 456.20/share."], "reasons": ["Buying futures at 457.30 and selling at 391.10 is a loss, not a gain", "Loss 99,300; 5,85,000 + 99,300 = 6,84,300 → 456.20", "97,950 is an arithmetic slip", "390 ignores the futures loss"], "notes": ["⚠️ Important: A hedge removes BOTH downside and upside — you don't benefit from the price fall.", "Easy way to remember: Hedge = locked price, both ways."], "id": 288}, "289": {"ch": 5, "chapter": "Strategies using Equity Futures and Equity Options", "q": "You plan to sell 1,200 PQR shares in July. Spot Rs 1,690; July futures Rs 1,706; lot size 600. How many lots do you short?", "options": ["1", "2", "3", "1,200"], "answer": 1, "why": ["Number of lots = shares to hedge ÷ lot size (1:1 hedge ratio with stock futures).", "Working: 1,200 / 600 = 2 lots, shorted at 1,706."], "reasons": ["One lot hedges only 600", "1,200 ÷ 600 = 2. 1,200 / 600 = 2 lots, shorted at 1,706.", "3 lots over-hedges", "Lots aren't counted in shares"], "notes": ["Easy way to remember: Shares ÷ lot size."], "id": 289}, "290": {"ch": 5, "chapter": "Strategies using Equity Futures and Equity Options", "q": "In the PQR short hedge (2 lots short at 1,706, lot 600), in July the stock is Rs 1,440 and futures Rs 1,441. The effective selling price per share is:", "options": ["Rs 1,440", "Rs 1,690", "Rs 1,705", "Rs 1,706"], "answer": 2, "why": ["Workbook: amount received = cash sale + futures gain.", "Working: Cash = 1,440 × 1,200 = 17,28,000. Futures gain = 265 × 1,200 = 3,18,000. Total 20,46,000 / 1,200 = 1,705."], "reasons": ["1,440 ignores the futures gain", "1,690 is the spot on May 10", "17,28,000 + 3,18,000 = 20,46,000 ÷ 1,200 = 1,705", "1,706 is the futures price, not the realised price"], "notes": ["Easy way to remember: Short hedge: cash down, futures up."], "id": 290}, "291": {"ch": 5, "chapter": "Strategies using Equity Futures and Equity Options", "q": "In the same PQR short hedge, if in July the stock is Rs 1,800 and futures Rs 1,802, the effective selling price per share is:", "options": ["Rs 1,800", "Rs 1,706", "Rs 1,896", "Rs 1,704"], "answer": 3, "why": ["Workbook: the futures loss offsets the higher cash sale.", "Working: Cash = 21,60,000. Futures loss = 96 × 1,200 = 1,15,200. Net = 20,44,800 / 1,200 = 1,704."], "reasons": ["1,800 ignores the futures loss", "1,706 is the entry futures price", "1,896 adds the loss instead of subtracting", "21,60,000 − 1,15,200 = 20,44,800 ÷ 1,200 = 1,704"], "notes": ["Easy way to remember: Hedge gives up the rally."], "id": 291}, "292": {"ch": 5, "chapter": "Strategies using Equity Futures and Equity Options", "q": "A trader expects XYZ (Rs 1,298) to rise; futures Rs 1,300, lot 850, margin Rs 2,21,000. He squares off futures at Rs 1,346. His return on margin is about:", "options": ["3.62%", "11.8%", "20%", "17.69%"], "answer": 3, "why": ["Workbook leverage example: futures ROI = profit ÷ margin; cash ROI = profit ÷ full cost.", "Working: Profit = 46 × 850 = 39,100; ROI = 39,100 / 2,21,000 = 17.69%, vs 3.62% for buying shares — the leverage effect."], "reasons": ["3.62% is the ROI from buying shares", "11.8% is not the result", "20% is the margin rate", "39,100 ÷ 2,21,000 = 17.69%. Profit = 46 × 850 = 39,100; ROI = 39,100 / 2,21,000 = 17.69%, vs 3.62% for buying shares — the leverage effect."], "notes": ["Easy way to remember: Same move, smaller capital → bigger %."], "id": 292}, "293": {"ch": 5, "chapter": "Strategies using Equity Futures and Equity Options", "q": "A trader shorts RSB Bank futures at Rs 1,602 (lot 550) with margin Rs 1,76,220 and covers at Rs 1,527. ROI on margin:", "options": ["4.7%", "18.2%", "41.25%", "23.41%"], "answer": 3, "why": ["Workbook example: gain on short = (sell − buy) × lot; ROI on margin.", "Working: Gain = 75 × 550 = 41,250; ROI = 41,250 / 1,76,220 = 23.41%."], "reasons": ["4.7% is the price % change", "18.2% is not the result", "41.25% misreads the gain", "41,250 ÷ 1,76,220 = 23.41%. Gain = 75 × 550 = 41,250; ROI = 41,250 / 1,76,220 = 23.41%."], "notes": ["Easy way to remember: Short futures = bearish view without owning the stock."], "id": 293}, "294": {"ch": 5, "chapter": "Strategies using Equity Futures and Equity Options", "q": "Why is shorting futures preferred over selling shares for a trader with a bearish view who doesn't own the stock?", "options": ["Futures have no margin", "Short selling shares requires delivery on settlement; futures allow a short without owning the stock", "Futures are exempt from STT", "Futures cannot make losses"], "answer": 1, "why": ["The workbook: selling shares requires delivery on the settlement date, so it's possible only if the trader holds shares; he can always short the futures instead.", "Key point: A cash-market sale needs shares in the demat account for delivery; a short futures position does not."], "reasons": ["Futures need margin", "A cash-market sale needs shares in the demat account for delivery; a short futures position does not.", "STT applies to futures", "Futures can lose money"], "notes": ["Easy way to remember: No shares? Short futures."], "id": 294}, "295": {"ch": 5, "chapter": "Strategies using Equity Futures and Equity Options", "q": "Stock A: spot Rs 1,500; 3-month futures Rs 1,550; lot 100; cost of carry 9% p.a. Fair futures = 1,500 × e^(0.09 × 3/12) = 1,534.13. The cash-and-carry arbitrage profit per lot is:", "options": ["Rs 5,000", "Rs 3,413", "Rs 1,587", "Rs 1,534"], "answer": 2, "why": ["Workbook cash-and-carry example: profit = (actual futures − fair futures) × lot = 15.87 × 100.", "Working: Profit = (1,550 − 1,534.13) × 100 = 1,587. Gross locked gain 5,000 minus financing 3,413."], "reasons": ["5,000 is gross, before financing cost", "3,413 is the financing cost", "Correct — 1,587. Profit = (1,550 − 1,534.13) × 100 = 1,587.", "1,534 is the fair price"], "notes": ["Easy way to remember: Arbitrage profit = mispricing × lot."], "id": 295}, "296": {"ch": 5, "chapter": "Strategies using Equity Futures and Equity Options", "q": "In the same cash-and-carry case, if the stock ends at Rs 1,480 on expiry, the gross gain before financing on the lot is:", "options": ["Rs 2,000", "Rs 5,000", "Rs 7,000", "Rs 1,587"], "answer": 1, "why": ["Workbook Case II: loss on stock 2,000; profit on futures 7,000; gross 5,000 — same as Case I.", "Working: Loss on stock 2,000; gain on futures 7,000; gross 5,000 — the same as in any scenario. Net of 3,413 financing = 1,587."], "reasons": ["2,000 is the stock loss only", "Loss on stock 2,000; gain on futures 7,000; gross 5,000 — the same as in any scenario.", "7,000 is the futures gain only", "1,587 is net of financing"], "notes": ["Easy way to remember: Gross gain = entry spread × lot, any scenario."], "id": 296}, "297": {"ch": 5, "chapter": "Strategies using Equity Futures and Equity Options", "q": "Stock B trades at Rs 100 and its 1-month futures at Rs 90 (lot 200). The arbitrageur sells 200 shares and buys 1 futures. Ignoring interest, the locked profit is:", "options": ["Rs 1,000", "Rs 3,000", "Rs 2,000", "Rs 150.56"], "answer": 2, "why": ["Workbook reverse cash-and-carry: sell spot at 100, buy futures at 90 → locked Rs 10 per share. Interest on the sale proceeds (~Rs 150.56) is extra.", "Working: Reverse cash-and-carry: (100 − 90) × 200 = 2,000. Investing the Rs 20,000 proceeds at 9% for a month adds ~Rs 150.56."], "reasons": ["1,000 is half", "3,000 is the Case II cash profit only", "(100 − 90) × 200 = 2,000. Reverse cash-and-carry: (100 − 90) × 200 = 2,000.", "150.56 is the interest component"], "notes": ["Easy way to remember: Futures below spot → sell cash, buy futures."], "id": 297}, "298": {"ch": 5, "chapter": "Strategies using Equity Futures and Equity Options", "q": "A key assumption behind executing reverse cash-and-carry is that the arbitrageur:", "options": ["Has cash to buy the stock", "Can buy puts", "Can get physical delivery on futures", "Has the stock (or can borrow it) to sell in the cash market"], "answer": 3, "why": ["The workbook: the arbitrageur must have the stock to sell in cash (bought back later); if not, he must borrow it.", "Key point: He must sell the stock today — so he must own it or borrow it (e.g., via securities lending)."], "reasons": ["That's needed for cash-and-carry", "Puts aren't needed", "Delivery isn't the assumption", "He must sell the stock today — so he must own it or borrow it (e.g., via securities lending)."], "notes": ["Easy way to remember: Reverse arbitrage needs the stock to sell."], "id": 298}, "299": {"ch": 5, "chapter": "Strategies using Equity Futures and Equity Options", "q": "Stock at Rs 120; near-month futures Rs 121.30; mid-month Rs 121.50; interest 8%. Fair prices are ~120.80 and ~121.61. The calendar spread trade is:", "options": ["Long near, short mid", "Short near, long mid", "Long both", "No trade — both are overpriced equally"], "answer": 1, "why": ["Workbook calendar spread example: fair spread ~0.81 but actual spread only 0.20, so the near month is overpriced relative to the mid month → short near, long mid.", "Key point: Fair spread ≈ 0.81 but actual is 0.20. The near month is overpriced relative to the mid month → short near, long mid."], "reasons": ["Reversed", "Fair spread ≈ 0.81 but actual is 0.20.", "Buying both isn't a spread", "Mispricing exists between the two"], "notes": ["Easy way to remember: Short the overpriced, buy the underpriced."], "id": 299}, "300": {"ch": 5, "chapter": "Strategies using Equity Futures and Equity Options", "q": "Calendar spread arbitrages are typically:", "options": ["High risk, high return", "Directional bets", "Risk-free and high return", "Low risk, low return, with no directional bet"], "answer": 3, "why": ["The workbook: calendar spreads are \"typically low risk – low return strategies\"; no directional bet.", "Key point: Opposite positions in two maturities protect against big moves; the gain is only the small mispricing."], "reasons": ["Not high risk", "No directional bet", "Not high return", "Opposite positions in two maturities protect against big moves; the gain is only the small mispricing."], "notes": ["Easy way to remember: Calendar spread = small, steady."], "id": 300}, "301": {"ch": 5, "chapter": "Strategies using Equity Futures and Equity Options", "q": "A bull call spread is created by:", "options": ["Buying a higher strike call and selling a lower strike call", "Buying a call and a put at the same strike", "Selling two calls", "Buying a lower strike call and selling a higher strike call"], "answer": 3, "why": ["The workbook: take a long call at a lower strike and sell a call at a higher strike; net outflow at the start.", "Key point: Long lower-strike call + short higher-strike call, same expiry. It is a net debit strategy."], "reasons": ["Reversed — that's a bear call spread", "That's a straddle", "That's a naked short", "Long lower-strike call + short higher-strike call, same expiry."], "notes": ["Easy way to remember: Bull call = buy low strike, sell high strike."], "id": 301}, "302": {"ch": 5, "chapter": "Strategies using Equity Futures and Equity Options", "q": "Bull call spread: long 17,500 call at 185, short 17,800 call at 61. Maximum profit, maximum loss and BEP are:", "options": ["124; 176; 17,624", "300; 124; 17,685", "176; 124; 17,561", "176; 124; 17,624"], "answer": 3, "why": ["Workbook: net debit = 185 − 61 = 124 = max loss; max profit = strike difference − net debit = 300 − 124 = 176; BEP = lower strike + net debit.", "Working: Net debit = 124 (max loss). Max profit = (17,800 − 17,500) − 124 = 176. BEP = 17,500 + 124 = 17,624."], "reasons": ["Profit and loss swapped", "300 is the strike gap", "17,561 is wrong BEP", "Net debit = 124 (max loss)."], "notes": ["Easy way to remember: Debit spread: max loss = debit; max gain = width − debit."], "id": 302}, "303": {"ch": 5, "chapter": "Strategies using Equity Futures and Equity Options", "q": "A bull put spread (short 17,500 put at 125, long 17,000 put at 34) has:", "options": ["Net debit of 91", "Max profit 409, max loss 91", "Net credit of 91, max profit 91, max loss 409, BEP 17,409", "Unlimited loss"], "answer": 2, "why": ["Workbook: a net premium receipt strategy. Max profit = net credit 91; max loss = 500 − 91 = 409; BEP = higher strike − credit = 17,409.", "Working: Credit = 125 − 34 = 91 (max profit). Max loss = 500 − 91 = 409. BEP = 17,500 − 91 = 17,409."], "reasons": ["It is a credit, not debit", "Swapped (that's the bear put spread)", "Credit = 125 − 34 = 91 (max profit).", "The long put caps the loss"], "notes": ["Easy way to remember: Credit spread: max gain = credit; max loss = width − credit."], "id": 303}, "304": {"ch": 5, "chapter": "Strategies using Equity Futures and Equity Options", "q": "A bear call spread (short 17,500 call at 185, long 17,800 call at 61) has maximum profit of:", "options": ["176", "300", "124", "Unlimited"], "answer": 2, "why": ["Workbook: starts with a net inflow of 124 = max profit; max loss 176; BEP 17,624.", "Working: Net credit = 124 = max profit; max loss = 300 − 124 = 176; BEP = 17,624."], "reasons": ["176 is the max loss", "300 is the strike width", "Net credit = 124 = max profit; max loss = 300 − 124 = 176; BEP = 17,624.", "Limited, not unlimited"], "notes": ["Easy way to remember: Bear call = sell low strike call, buy high."], "id": 304}, "305": {"ch": 5, "chapter": "Strategies using Equity Futures and Equity Options", "q": "A bear put spread (long 17,500 put at 125, short 17,000 put at 34): at an expiry of 17,200, the net P&L is:", "options": ["+300", "−91", "+409", "+209"], "answer": 3, "why": ["Net P&L = long put payoff − short put payoff − net debit (91).", "Working: Long put payoff 300, short put expires worthless. Net = 300 − 91 (net debit) = 209."], "reasons": ["300 ignores the net debit", "−91 is the loss above 17,500", "409 is the max profit at 17,000 or below", "300 − 91 = 209. Long put payoff 300, short put expires worthless."], "notes": ["Easy way to remember: Bear put = buy high strike put, sell low."], "id": 305}, "306": {"ch": 5, "chapter": "Strategies using Equity Futures and Equity Options", "q": "Which spread starts with a net premium INFLOW?", "options": ["Bull call spread", "Bear put spread", "Long butterfly", "Bear call spread"], "answer": 3, "why": ["Bull call spread and bear put spread are debit spreads; bear call and bull put are credit spreads. A long butterfly costs money upfront.", "Key point: Bear call spread and bull put spread are credit spreads. Bull call, bear put and long butterfly are debit strategies."], "reasons": ["Debit spread", "Debit spread", "Butterfly cost 30 upfront in the workbook example", "Correct — credit. Bear call spread and bull put spread are credit spreads."], "notes": ["Easy way to remember: \"Sell the expensive one\" spreads = credit."], "id": 306}, "307": {"ch": 5, "chapter": "Strategies using Equity Futures and Equity Options", "q": "If an investor buys a call with a lower strike and sells a call with a higher strike, same underlying and expiry, the strategy is:", "options": ["Bearish spread", "Butterfly spread", "Calendar spread", "Bullish spread"], "answer": 3, "why": ["Workbook sample question: answer is a bullish spread.", "Key point: That is the bull call (vertical) spread."], "reasons": ["A bear call spread is the reverse", "Butterfly uses three strikes", "Calendar uses different expiries", "That is the bull call (vertical) spread."], "notes": ["Easy way to remember: Buy low, sell high strike calls = bullish."], "id": 307}, "308": {"ch": 5, "chapter": "Strategies using Equity Futures and Equity Options", "q": "A horizontal spread uses options of:", "options": ["Same expiry, different strikes", "Different strikes and different expiries", "Different underlyings", "Same type and strike, different expiries"], "answer": 3, "why": ["The workbook: a horizontal spread involves options of the same type and strike but different expiry dates (time or calendar spread).", "Key point: Horizontal = time/calendar spread (same strike, different expiry). Vertical = same expiry, different strikes. Diagonal = both differ."], "reasons": ["That's vertical", "That's diagonal", "Spreads use the same underlying", "Horizontal = time/calendar spread (same strike, different expiry)."], "notes": ["Easy way to remember: Vertical = strikes; Horizontal = time; Diagonal = both."], "id": 308}, "309": {"ch": 5, "chapter": "Strategies using Equity Futures and Equity Options", "q": "Why can't a simple payoff chart be drawn for horizontal and diagonal spreads?", "options": ["They have unlimited loss", "They use futures", "The options expire on different dates", "They are OTC only"], "answer": 2, "why": ["The workbook: as the expiry dates differ, it is not possible to draw the payoff chart.", "Key point: With different expiries, there's no single expiry date at which to plot the combined payoff."], "reasons": ["Not the reason", "They use options, not futures", "With different expiries, there's no single expiry date at which to plot the combined payoff.", "They can be exchange-traded"], "notes": ["Easy way to remember: No common expiry → no payoff chart."], "id": 309}, "310": {"ch": 5, "chapter": "Strategies using Equity Futures and Equity Options", "q": "A stock at Rs 6,000: ATM call Rs 257, ATM put Rs 136. A long straddle's break-even points are:", "options": ["5,864 and 6,257", "5,743 and 6,136", "5,607 and 6,393", "6,000 only"], "answer": 2, "why": ["Workbook straddle: total premium 393; BEPs = strike ± total premium = 5,607 and 6,393.", "Working: Total premium = 393. BEPs = 6,000 ± 393 = 5,607 and 6,393."], "reasons": ["Uses the individual premiums separately", "Uses the wrong premium", "Total premium = 393.", "There are two BEPs"], "notes": ["Easy way to remember: Straddle BEP = strike ± both premiums."], "id": 310}, "311": {"ch": 5, "chapter": "Strategies using Equity Futures and Equity Options", "q": "In the same long straddle (6,000 strike; total premium 393), if the stock expires at 5,300, the net profit is:", "options": ["700", "443", "307", "−393"], "answer": 2, "why": ["Workbook: at 5,300 the put pays 700 − 136 = 564; the call loses 257 → net 307.", "Working: Put payoff = 700; minus total premium 393 = 307."], "reasons": ["700 ignores the premiums", "443 is the result at 6,700 for the call leg", "Put payoff = 700; minus total premium 393 = 307.", "−393 occurs only at the strike"], "notes": ["Easy way to remember: Move beyond the BEP = profit."], "id": 311}, "312": {"ch": 5, "chapter": "Strategies using Equity Futures and Equity Options", "q": "A short straddle is suitable when the trader expects:", "options": ["A big move in either direction", "A sharp rise only", "The price to remain stable", "Volatility to rise"], "answer": 2, "why": ["The workbook: short straddle — the view is that the price will not move much; limited profit, unlimited loss.", "Key point: Short straddle profits from low movement (premium retained); it has limited profit and unlimited loss."], "reasons": ["That's a long straddle", "That's a long call", "Short straddle profits from low movement (premium retained); it has limited profit and unlimited loss.", "Rising volatility hurts a short straddle"], "notes": ["Easy way to remember: Short straddle = \"nothing will happen\"."], "id": 312}, "313": {"ch": 5, "chapter": "Strategies using Equity Futures and Equity Options", "q": "Stock at 6,100: 6,200 call at 145 and 6,000 put at 140. A long strangle has:", "options": ["Max loss 285, BEPs 5,815 and 6,385", "Max loss 145, BEPs 5,860 and 6,345", "Max loss 285, BEPs 5,715 and 6,485", "Max loss unlimited"], "answer": 2, "why": ["Workbook long strangle: max loss 285 anywhere between 6,000 and 6,200; BEPs 5,715 and 6,485.", "Working: Total premium 285. Lower BEP = 6,000 − 285 = 5,715; upper = 6,200 + 285 = 6,485."], "reasons": ["Uses the wrong strikes", "One premium only", "Total premium 285.", "Long strangle loss is limited"], "notes": ["Easy way to remember: Strangle BEP: put strike − total, call strike + total."], "id": 313}, "314": {"ch": 5, "chapter": "Strategies using Equity Futures and Equity Options", "q": "In the long strangle (6,200 call at 145, 6,000 put at 140), if the stock expires at 6,800, net profit is:", "options": ["315", "600", "455", "185"], "answer": 0, "why": ["Workbook: at 6,800 the call makes 455 net; the put loses 140 → 315.", "Working: Call payoff 600 − 145 = 455; put loses 140. Net = 315."], "reasons": ["Call payoff 600 − 145 = 455; put loses 140.", "600 ignores both premiums", "455 ignores the put premium", "185 is wrong"], "notes": ["Easy way to remember: Winner leg minus loser leg."], "id": 314}, "315": {"ch": 5, "chapter": "Strategies using Equity Futures and Equity Options", "q": "Compared with a long straddle, a long strangle is:", "options": ["Cheaper (OTM options) but needs a bigger move to profit", "More expensive and needs a smaller move", "Identical in cost", "A limited-profit strategy"], "answer": 0, "why": ["The workbook: both options in a strangle are OTM, so premium is lower, but BEPs are farther — a bigger move is needed.", "Key point: Strangles use OTM options with lower premium, but the BEPs are farther away."], "reasons": ["Strangles use OTM options with lower premium, but the BEPs are farther away.", "Reversed", "Costs differ", "Profit is unlimited"], "notes": ["Easy way to remember: Strangle = cheaper, needs a bigger move."], "id": 315}, "316": {"ch": 5, "chapter": "Strategies using Equity Futures and Equity Options", "q": "Which strategy has maximum profit limited to net premium and maximum loss unlimited on both sides?", "options": ["Long strangle", "Butterfly", "Collar", "Short strangle"], "answer": 3, "why": ["Workbook: short strangle — max loss unlimited in both directions, max profit limited to the premium (285 in the example).", "Key point: A short strangle (sell OTM call and OTM put) keeps premium in a range but loses without limit on big moves."], "reasons": ["Long strangle has limited loss", "Butterfly is limited both ways", "Collar is limited both ways", "A short strangle (sell OTM call and OTM put) keeps premium in a range but loses without limit on big moves."], "notes": ["Easy way to remember: Short strangle = limited gain, unlimited loss."], "id": 316}, "317": {"ch": 5, "chapter": "Strategies using Equity Futures and Equity Options", "q": "Covered call: buy stock at 1,590, sell 1,600 call at 10. If the stock closes at 1,640 at expiry, the net P&L is:", "options": ["20", "50", "−30", "60"], "answer": 0, "why": ["Workbook: at 1,640 — stock +50, short call −30 → +20 (also the maximum profit).", "Working: Stock +50; short call −(40) + 10 = −30. Net = +20 (max profit = 1,600 − 1,590 + 10)."], "reasons": ["Stock +50; short call −(40) + 10 = −30.", "50 ignores the short call", "−30 is the call leg only", "60 is wrong"], "notes": ["Easy way to remember: Covered call max profit = (strike − cost) + premium."], "id": 317}, "318": {"ch": 5, "chapter": "Strategies using Equity Futures and Equity Options", "q": "In the same covered call (stock 1,590; short 1,600 call at 10), the break-even is:", "options": ["1,580", "1,600", "1,610", "1,590"], "answer": 0, "why": ["Covered call BEP = stock purchase price − premium received.", "Working: BEP = stock price − premium = 1,590 − 10 = 1,580."], "reasons": ["1,590 − 10 = 1,580. BEP = stock price − premium = 1,590 − 10 = 1,580.", "1,600 is the strike", "1,610 adds the premium", "1,590 ignores the premium"], "notes": ["Easy way to remember: Premium lowers your cost."], "id": 318}, "319": {"ch": 5, "chapter": "Strategies using Equity Futures and Equity Options", "q": "The payoff of a covered call resembles a:", "options": ["Short put", "Long call", "Long put", "Short call"], "answer": 0, "why": ["The workbook: \"the covered call is called a 'synthetic short put' position\" — capped upside with a large downside.", "Key point: Capped upside and large downside = synthetic short put."], "reasons": ["Capped upside and large downside = synthetic short put.", "Long call has unlimited upside", "Long put gains when prices fall", "Short call alone has unlimited loss on the upside"], "notes": ["Easy way to remember: Long stock + short call = short put."], "id": 319}, "320": {"ch": 5, "chapter": "Strategies using Equity Futures and Equity Options", "q": "Which of the following is a hedged position as per the NISM workbook's sample question?", "options": ["Protective put", "Short straddle", "Short strangle", "Covered call"], "answer": 0, "why": ["This is the workbook's own sample question and its marked answer is Protective Put. In the workbook, a protective put is \"a hedged position\" — the put limits downside. A covered call is described as a synthetic short put: the premium gives only a small cushion and losses can still be large when the stock falls.", "Key point: The workbook's own sample marks Protective Put (long stock + long put), where the put caps the downside. A covered call only cushions the downside by the premium and still behaves like a short put with large downside, so the workbook treats protective put as the hedged position."], "reasons": ["Protective put — long stock + long put; the put caps the loss; the workbook calls it a hedged position", "Short straddle — sell call + sell put; unlimited risk, not hedged", "Short strangle — sell OTM call + OTM put; unlimited risk, not hedged", "Covered call — long stock + short call; only a small premium cushion; behaves like a short put"], "notes": ["⚠️ Important: Other sources may say \"covered call\" or call the question ambiguous, but NISM's marked answer is Protective Put. In the NISM exam, choose Protective Put.", "Easy way to remember: Covered call collects rent; protective put buys insurance — only insurance is a hedge."], "id": 320}, "321": {"ch": 5, "chapter": "Strategies using Equity Futures and Equity Options", "q": "Collar: long stock 1,590, short 1,600 call at 10, long 1,580 put at 7. If the stock expires at 1,490, the net P&L is:", "options": ["−90", "−100", "+13", "−7"], "answer": 3, "why": ["Workbook collar at 1,490: stock −100; short call +10; long put +83 → −7 (covered call alone −90).", "Working: Stock −100; short call +10; long put (1,580 − 1,490) − 7 = +83. Net = −7 (covered call alone would be −90)."], "reasons": ["−90 is the covered call without the put", "−100 is the stock leg only", "+13 is the result at 1,690", "Stock −100; short call +10; long put (1,580 − 1,490) − 7 = +83."], "notes": ["Easy way to remember: Collar = covered call + floor."], "id": 321}, "322": {"ch": 5, "chapter": "Strategies using Equity Futures and Equity Options", "q": "In the same collar, if the stock expires at 1,690, the net P&L is:", "options": ["+20", "+100", "+13", "−7"], "answer": 2, "why": ["Workbook: stock +100; short call −80; long put −7 → +13 (covered call would give +20).", "Working: Stock +100; short call 10 − 90 = −80; long put −7. Net = +13. The put costs 7, reducing the max profit from 20 to 13."], "reasons": ["+20 is the covered call without the put", "+100 is the stock alone", "Stock +100; short call 10 − 90 = −80; long put −7.", "−7 is the downside result"], "notes": ["Easy way to remember: The put costs 7 → max profit falls from 20 to 13."], "id": 322}, "323": {"ch": 5, "chapter": "Strategies using Equity Futures and Equity Options", "q": "A collar is an extension of which strategy?", "options": ["Protective put", "Short straddle", "Bull put spread", "Covered call"], "answer": 3, "why": ["The workbook: \"A collar strategy is an extension of the covered call strategy\" — buy an OTM put to limit downside.", "Key point: It adds a long OTM put to a covered call to put a floor under the downside."], "reasons": ["Protective put has no short call", "Butterfly extends the short straddle", "Bull put spread has no stock", "It adds a long OTM put to a covered call to put a floor under the downside."], "notes": ["Easy way to remember: Collar = covered call + protective put."], "id": 323}, "324": {"ch": 5, "chapter": "Strategies using Equity Futures and Equity Options", "q": "Butterfly using calls: long 6,000 call at 230, short two 6,100 calls at 150 each, long 6,200 call at 100. The net cost, max profit and BEPs are:", "options": ["70; 30; 6,070 and 6,130", "30; 70; 6,030 and 6,170", "30; 100; 6,030 and 6,200", "Net credit 30; unlimited; none"], "answer": 1, "why": ["Workbook: cost 30; max profit 70 at 6,100; BEPs 6,030 and 6,170.", "Working: Cost = 230 + 100 − 300 = 30. Max profit at 6,100 = 100 − 30 = 70. BEPs: 6,000 + 30 and 6,200 − 30."], "reasons": ["Profit and cost swapped", "Cost = 230 + 100 − 300 = 30.", "Wrong max profit and upper BEP", "It is a debit with limited profit"], "notes": ["Easy way to remember: Butterfly: max profit at the middle strike."], "id": 324}, "325": {"ch": 5, "chapter": "Strategies using Equity Futures and Equity Options", "q": "A butterfly spread is an extension of the short straddle designed to:", "options": ["Increase profit", "Remove time decay", "Convert it to a directional trade", "Limit the unlimited downside by buying OTM wings"], "answer": 3, "why": ["The workbook: a butterfly is an extension of the short straddle; buying OTM call and put limits the unlimited downside.", "Key point: Adding long OTM call and put caps losses on big moves; result is limited profit, limited loss."], "reasons": ["Profit actually reduces", "Time decay still matters", "It remains non-directional", "Adding long OTM call and put caps losses on big moves; result is limited profit, limited loss."], "notes": ["Easy way to remember: Butterfly = short straddle with wings."], "id": 325}, "326": {"ch": 5, "chapter": "Strategies using Equity Futures and Equity Options", "q": "To build a butterfly using only puts, you:", "options": ["Sell one highest strike, buy two middle strikes, sell one lowest strike", "Buy three puts at the middle strike", "Buy one highest strike, sell two middle strikes, buy one lowest strike", "Buy puts and sell futures"], "answer": 2, "why": ["The workbook: buy one highest-strike put, sell two middle-strike puts, buy one lowest-strike put.", "Key point: Mirror of the call butterfly: long wings, short two at the body."], "reasons": ["Reversed (that's a short butterfly)", "Not a butterfly", "Mirror of the call butterfly: long wings, short two at the body.", "Futures aren't used"], "notes": ["Easy way to remember: Buy wings, sell two in the body."], "id": 326}, "327": {"ch": 5, "chapter": "Strategies using Equity Futures and Equity Options", "q": "Protective put: buy stock at 1,600 and a 1,600 put at 20. If the stock falls to 1,530, the net P&L is:", "options": ["−70", "+50", "−50", "−20"], "answer": 3, "why": ["Workbook: at 1,530 — stock −70, put +50 → −20, i.e., the premium paid.", "Working: Stock −70; put 70 − 20 = +50. Net −20 = the premium (max loss when strike = purchase price)."], "reasons": ["−70 is the stock alone", "+50 is the put alone", "−50 is wrong", "Stock −70; put 70 − 20 = +50."], "notes": ["Easy way to remember: Protective put max loss = premium (strike = cost)."], "id": 327}, "328": {"ch": 5, "chapter": "Strategies using Equity Futures and Equity Options", "q": "A protective put's payoff is similar to a:", "options": ["Short put", "Long call", "Short call", "Long futures"], "answer": 1, "why": ["The workbook: \"the protective put is called a 'synthetic long call' position\" — unlimited gains, limited loss.", "Key point: Limited loss and unlimited gain — a synthetic long call."], "reasons": ["Short put has limited gain", "Limited loss and unlimited gain — a synthetic long call.", "Short call has unlimited loss", "Long futures has unlimited loss"], "notes": ["Easy way to remember: Stock + put = call."], "id": 328}, "329": {"ch": 5, "chapter": "Strategies using Equity Futures and Equity Options", "q": "Put-call parity is expressed as:", "options": ["c + S = p + X", "c + X·e^(−rt) = p + S", "c − p = X − S", "c + p = S + X"], "answer": 1, "why": ["Workbook formula: c + X·e^(−rt) = p + S₀. Applies only to European options with the same strike and expiry.", "Key point: Call plus PV of strike equals put plus spot. Applies to European options with same strike and expiry."], "reasons": ["Missing discounting and wrong pairing", "Call plus PV of strike equals put plus spot.", "Not the parity equation", "Not the parity equation"], "notes": ["Easy way to remember: Call + PV(strike) = Put + Spot."], "id": 329}, "330": {"ch": 5, "chapter": "Strategies using Equity Futures and Equity Options", "q": "Stock Rs 1,251; 1-month 1,240 call at Rs 47.50; interest 8% p.a. The fair value of the 1,240 put by put-call parity is about:", "options": ["Rs 23.15", "Rs 28.26", "Rs 36.50", "Rs 47.50"], "answer": 1, "why": ["Workbook: p = c + X·e^(−rt) − S = 47.50 + 1,231.76 − 1,251 = 28.26.", "Working: p = c + X·e^(−rt) − S = 47.50 + 1,240 × e^(−0.08/12) − 1,251 = 47.50 + 1,231.76 − 1,251 = 28.26."], "reasons": ["23.15 is the market price, not fair value", "p = c + X·e^(−rt) − S = 47.50 + 1,240 × e^(−0.08/12) − 1,251 = 47.50 + 1,231.76 − 1,251 = 28.26.", "36.50 is wrong", "47.50 is the call"], "notes": ["Easy way to remember: Rearrange parity: p = c + PV(X) − S."], "id": 330}, "331": {"ch": 5, "chapter": "Strategies using Equity Futures and Equity Options", "q": "In that case, the 1,240 put actually trades at Rs 23.15. The arbitrage is:", "options": ["Sell the put, sell the stock, buy the call", "Buy the call and the put", "Buy the put and the stock, sell the call, borrow the net amount", "No arbitrage exists"], "answer": 2, "why": ["Workbook: the put is underpriced → buy the put and the stock, sell the call; net outflow Rs 1,226.65 borrowed at 8%; locked gain ~Rs 5.14.", "Key point: The put is underpriced. Buy put + stock, write call; net outflow 1,226.65 borrowed at 8%. Locks ~Rs 5.14 at expiry."], "reasons": ["Selling the cheap put is backwards", "Buying both is not the parity arbitrage", "The put is underpriced.", "A mispricing exists"], "notes": ["Easy way to remember: Buy the cheap side of the equation, sell the dear side."], "id": 331}, "332": {"ch": 5, "chapter": "Strategies using Equity Futures and Equity Options", "q": "Stock Rs 1,000; 1-month 1,000 call at Rs 40; r = 8% p.a. Using put-call parity (continuous compounding), the fair 1,000 put is about:", "options": ["Rs 26.65", "Rs 40.00", "Rs 33.36", "Rs 46.64"], "answer": 2, "why": ["p = c + X·e^(−rt) − S.", "Working: p = 40 + 1,000 × e^(−0.08/12) − 1,000 = 40 + 993.36 − 1,000 = 33.36."], "reasons": ["26.65 subtracts the interest twice", "40 assumes zero interest", "40 + 993.36 − 1,000 = 33.36. p = 40 + 1,000 × e^(−0.08/12) − 1,000 = 40 + 993.36 − 1,000 = 33.36.", "46.64 adds the interest"], "notes": ["Easy way to remember: ATM with positive rates: put < call."], "id": 332}, "333": {"ch": 5, "chapter": "Strategies using Equity Futures and Equity Options", "q": "Put-call parity relates:", "options": ["Calls and puts on the same stock with the same strike and same maturity", "Futures and options on the same stock", "Calls on the same stock with different strikes", "Puts and calls with different strikes and maturities"], "answer": 0, "why": ["Workbook sample: put-call parity is the relationship between calls and puts on the same stock with the same strike and same maturity.", "Key point: Parity holds only for European calls and puts with identical strike and expiry."], "reasons": ["Parity holds only for European calls and puts with identical strike and expiry.", "Futures aren't part of the relation", "Different strikes don't qualify", "Different strikes/maturities don't qualify"], "notes": ["Easy way to remember: Same stock, same strike, same expiry."], "id": 333}, "334": {"ch": 5, "chapter": "Strategies using Equity Futures and Equity Options", "q": "A trader is short 10 lots of calls (lot 50, delta 0.50). How many lots of stock futures make the position delta-neutral?", "options": ["Long 5 lots", "Short 5 lots", "Long 10 lots", "Long 2.5 lots"], "answer": 0, "why": ["Workbook delta-hedging example: short calls delta = −0.5 × 10 × 50 = −250; each futures lot has delta +50; 5 long lots → delta-neutral.", "Working: Option delta = −0.5 × 10 × 50 = −250. Futures delta = +1 per unit; 5 lots × 50 = +250."], "reasons": ["Option delta = −0.5 × 10 × 50 = −250.", "Shorting futures adds to the risk", "10 lots over-hedges", "2.5 lots under-hedges"], "notes": ["Easy way to remember: Futures lots = option delta ÷ lot."], "id": 334}, "335": {"ch": 5, "chapter": "Strategies using Equity Futures and Equity Options", "q": "In that delta hedge, the stock rises and call delta moves from 0.50 to 0.60. To stay delta-neutral the trader must:", "options": ["Sell 1 futures lot", "Buy 1 more futures lot (total 6)", "Buy 5 more lots", "Do nothing"], "answer": 1, "why": ["Workbook: when delta rises to 0.60, the trader needs one more lot (6 total) — this continuous rebalancing is delta hedging.", "Working: New option delta = −0.6 × 500 = −300 → needs +300 → 6 lots. Continuously adjusting like this is delta hedging."], "reasons": ["Selling makes it worse", "New option delta = −0.6 × 500 = −300 → needs +300 → 6 lots.", "5 more over-hedges", "The position would no longer be neutral"], "notes": ["Easy way to remember: Delta changes → rebalance."], "id": 335}, "336": {"ch": 5, "chapter": "Strategies using Equity Futures and Equity Options", "q": "Client 3 holds long futures 300, long call 500 (delta 0.5) and long put 400 (delta −0.5). His notional OI and FutEq OI are:", "options": ["1,200 and 850", "350 and 1,200", "800 and 0", "1,200 and 350"], "answer": 3, "why": ["Workbook FutEq OI table: notional adds all positions (1,200); FutEq multiplies each by delta and nets: 300 + 250 − 200 = 350.", "Working: Notional = 300 + 500 + 400 = 1,200. FutEq = 300 + 250 − 200 = 350 (delta-adjusted, netted)."], "reasons": ["850 ignores the negative put delta", "Swapped", "These belong to Client 4", "Notional = 300 + 500 + 400 = 1,200."], "notes": ["Easy way to remember: FutEq = Σ position × delta."], "id": 336}, "337": {"ch": 5, "chapter": "Strategies using Equity Futures and Equity Options", "q": "Futures price is rising while open interest is falling. This usually indicates:", "options": ["Fresh long build-up", "Short covering", "Fresh short build-up", "Long unwinding"], "answer": 1, "why": ["The workbook's four scenarios: price up + OI up = bullish; price up + OI down = short covering; price down + OI up = bearish short build-up; price down + OI down = long unwinding.", "Key point: Price up + OI down = shorts closing positions. Price up + OI up = bullish long build-up."], "reasons": ["That's price up + OI up", "Price up + OI down = shorts closing positions.", "That's price down + OI up", "That's price down + OI down"], "notes": ["Easy way to remember: Price ↑ OI ↓ = shorts running for cover."], "id": 337}, "338": {"ch": 5, "chapter": "Strategies using Equity Futures and Equity Options", "q": "Put open interest is 8,000 and call open interest is 12,000. PCR and its interpretation per the workbook:", "options": ["1.5, bullish", "0.67, bullish", "1.5, bearish", "0.67, bearish"], "answer": 3, "why": ["The workbook: PCR = put OI ÷ call OI = 0.67. PCR is a contrarian indicator; < 1 means more call selling — sellers don't expect a rise — bearish.", "Working: PCR = 8,000/12,000 = 0.67. As a contrarian indicator, PCR < 1 means more calls are being written — sellers don't expect a rise → bearish."], "reasons": ["PCR is 0.67, not 1.5", "Workbook reads PCR < 1 as bearish", "PCR is 0.67", "Correct as per the workbook. PCR = 8,000/12,000 = 0.67."], "notes": ["Easy way to remember: PCR < 1 bearish; > 1 bullish (workbook view)."], "id": 338}, "339": {"ch": 6, "chapter": "Trading Mechanism", "q": "Indian derivatives exchanges operate as a:", "options": ["Quote-driven open outcry market", "Fully automated screen-based, order-driven market", "Dealer market with designated market makers only", "Pit-based auction market"], "answer": 1, "why": ["The workbook: all Indian derivatives exchanges provide a fully automated screen-based trading platform supporting an order-driven market with complete transparency.", "Key point: All Indian derivatives exchanges provide a fully automated, screen-based, order-driven trading platform."], "reasons": ["Open outcry is the older pit system", "All Indian derivatives exchanges provide a fully automated, screen-based, order-driven trading platform.", "Not a dealer market", "No pits in India"], "notes": ["Easy way to remember: India = screen + order-driven."], "id": 339}, "340": {"ch": 6, "chapter": "Trading Mechanism", "q": "A Professional Clearing Member (PCM) is typically:", "options": ["A trading member who clears only his own trades", "A client of a trading member", "A bank or custodian, not a trading member, that clears trades of trading members and custodial participants", "A sub-broker"], "answer": 2, "why": ["The workbook: a PCM clears trades of associate trading members and institutional clients; it is not a trading member; typically banks or custodians.", "Key point: PCMs are not trading members; banks/custodians usually take this role."], "reasons": ["That describes a self-clearing member", "A participant is a client", "PCMs are not trading members; banks/custodians usually take this role.", "Sub-brokers no longer exist"], "notes": ["Easy way to remember: PCM = bank/custodian that clears but doesn't trade."], "id": 340}, "341": {"ch": 6, "chapter": "Trading Mechanism", "q": "A Self Clearing Member can clear and settle:", "options": ["Trades of any trading member", "Only custodial participants' trades", "Only its own proprietary and its clients' trades", "Only index derivatives"], "answer": 2, "why": ["The workbook: an SCM may clear and settle only its own proprietary trades and its clients' trades, not those of other trading members.", "Key point: An SCM cannot clear trades of other trading members."], "reasons": ["That's a TCM", "That's a PCM function", "An SCM cannot clear trades of other trading members.", "Not limited to index derivatives"], "notes": ["Easy way to remember: Self-clearing = self only."], "id": 341}, "342": {"ch": 6, "chapter": "Trading Mechanism", "q": "A Trading-cum-Clearing Member can clear:", "options": ["Own proprietary trades, clients' trades, and trades of other trading members and custodial participants", "Only proprietary trades", "Only trades of other trading members", "No trades; it only executes"], "answer": 0, "why": ["The workbook: a TCM can clear its own proprietary trades, its clients' trades, other trading members' trades and custodial participants' trades.", "Key point: TCMs clear their own and others' trades."], "reasons": ["TCMs clear their own and others' trades.", "Too narrow", "Too narrow", "A TCM does clear"], "notes": ["Easy way to remember: TCM = trade + clear for all."], "id": 342}, "343": {"ch": 6, "chapter": "Trading Mechanism", "q": "Sub-brokers as an intermediary category ceased to exist with effect from:", "options": ["April 01, 2018", "April 01, 2019", "June 21, 2018", "October 01, 2019"], "answer": 1, "why": ["The workbook: SEBI Board (June 21, 2018) decided sub-brokers would cease to exist with effect from April 01, 2019; they migrated to APs or TMs.", "Key point: SEBI's Board decided on June 21, 2018 that sub-brokers would cease to exist from April 01, 2019; they migrated to Authorised Persons or trading members."], "reasons": ["Wrong year", "SEBI's Board decided on June 21, 2018 that sub-brokers would cease to exist from April 01, 2019; they migrated to Authorised Persons or trading members.", "That's the Board meeting date", "October 2019 is physical settlement"], "notes": ["Easy way to remember: Decided 2018, effective April 2019."], "id": 343}, "344": {"ch": 6, "chapter": "Trading Mechanism", "q": "SEBI permits exchanges to set equity derivatives trading hours within:", "options": ["9:15 AM to 3:30 PM only", "9:00 AM to 11:55 PM, subject to adequate risk management and infrastructure", "10:00 AM to 5:00 PM", "24 hours"], "answer": 1, "why": ["The workbook: exchanges may set trading hours between 9:00 AM and 11:55 PM, provided they and their clearing corporation have commensurate risk management systems and infrastructure.", "Key point: Exchanges may set trading hours between 9:00 AM and 11:55 PM if the exchange and clearing corporation have commensurate risk systems. Normal hours are 9:15–3:30."], "reasons": ["That's the normal market timing", "Exchanges may set trading hours between 9:00 AM and 11:55 PM if the exchange and clearing corporation have commensurate risk systems.", "Not in the workbook", "Not 24 hours"], "notes": ["Easy way to remember: Permitted window 9:00 AM – 11:55 PM."], "id": 344}, "345": {"ch": 6, "chapter": "Trading Mechanism", "q": "In the trading system user hierarchy, which user can define exposure limits for branches?", "options": ["Dealer", "Branch Manager", "Corporate Manager", "Clearing Member"], "answer": 2, "why": ["The workbook: the corporate manager can define exposure limits for branches; \"This facility is available only to the corporate manager.\"", "Key point: Only the Corporate Manager can set branch exposure limits and view all branches and dealers."], "reasons": ["Dealer is the lowest level", "Branch Manager can't set branch limits", "Only the Corporate Manager can set branch exposure limits and view all branches and dealers.", "A clearing member sets TM limits, not branch limits in the TM's system"], "notes": ["Easy way to remember: Corporate Manager = top boss."], "id": 345}, "346": {"ch": 6, "chapter": "Trading Mechanism", "q": "A Dealer in the trading hierarchy can view:", "options": ["All orders of the firm", "Only his own orders and trades", "Orders of his branch", "Orders of other dealers in his branch"], "answer": 1, "why": ["The workbook: the dealer \"can only view his own orders and trades\".", "Key point: The dealer is the lowest level; he sees only his own orders and trades."], "reasons": ["That's the corporate manager", "The dealer is the lowest level; he sees only his own orders and trades.", "That's the branch manager", "Dealers can't see other dealers"], "notes": ["Easy way to remember: Dealer sees only himself."], "id": 346}, "347": {"ch": 6, "chapter": "Trading Mechanism", "q": "An IOC order for 500 contracts finds only 300 matching contracts on entry. What happens?", "options": ["The whole order is cancelled", "300 execute; 200 remain as a day order", "The order waits till end of day", "300 are executed and the unmatched 200 are cancelled immediately"], "answer": 3, "why": ["The workbook: IOC — partial match is possible; the unmatched portion is cancelled immediately.", "Key point: IOC allows partial match; the unmatched portion is cancelled immediately."], "reasons": ["Partial execution is allowed", "IOC doesn't convert to a day order", "IOC never waits", "IOC allows partial match; the unmatched portion is cancelled immediately."], "notes": ["Easy way to remember: IOC = fill what you can now, cancel the rest."], "id": 347}, "348": {"ch": 6, "chapter": "Trading Mechanism", "q": "A limit buy order at Rs 250 can execute at:", "options": ["Only Rs 250", "Rs 250 or lower", "Rs 250 or higher", "Any price"], "answer": 1, "why": ["The workbook: a limit order executes at the limit price or better — lower for a buy, higher for a sell.", "Key point: A limit order executes at the limit price or better — lower for a buy, higher for a sell."], "reasons": ["It can get a better price", "A limit order executes at the limit price or better — lower for a buy, higher for a sell.", "Higher is worse for a buyer", "A limit order caps the price"], "notes": ["Easy way to remember: Limit = your price or better."], "id": 348}, "349": {"ch": 6, "chapter": "Trading Mechanism", "q": "A trader bought ABC at Rs 100 and places a stop-loss sell order with trigger Rs 95 and limit Rs 92. When the price falls to Rs 95:", "options": ["The order is converted to a limit sell order at Rs 92", "The order sells at market immediately at any price", "The order is cancelled", "The order sells only at Rs 95"], "answer": 0, "why": ["Workbook example: once the trigger (95) is breached, the order is converted to a limit sell order at Rs 92.", "Key point: Once the trigger is breached, the stop-loss order enters the market as a limit order at 92 (i.e., sells at 92 or better)."], "reasons": ["Once the trigger is breached, the stop-loss order enters the market as a limit order at 92 (i.e., sells at 92 or better).", "It becomes a limit order, not a market order", "It isn't cancelled", "95 is the trigger, not the execution limit"], "notes": ["Easy way to remember: Trigger activates; limit governs execution."], "id": 349}, "350": {"ch": 6, "chapter": "Trading Mechanism", "q": "For a stop-loss SELL limit order, the trigger price must be:", "options": ["Below the limit price", "Above the last traded price", "Equal to the limit price always", "Between the last traded price and the limit price"], "answer": 3, "why": ["The workbook: \"The trigger price must be between last traded price and limit price while placing the sell limit order.\"", "Key point: For a sell stop-loss, LTP > trigger ≥ limit."], "reasons": ["For a sell stop-loss, trigger is above the limit", "Trigger above LTP would trigger instantly", "They can differ", "For a sell stop-loss, LTP > trigger ≥ limit."], "notes": ["Easy way to remember: LTP > Trigger ≥ Limit."], "id": 350}, "351": {"ch": 6, "chapter": "Trading Mechanism", "q": "A trader bought 100 XYZ shares at Rs 780 and doesn't want to lose more than Rs 1,000. He should place:", "options": ["A limit sell order for 100 shares at Rs 770", "A limit buy order at Rs 790", "A limit buy order at Rs 770", "A stop-loss sell order for 100 shares at Rs 770"], "answer": 3, "why": ["Workbook sample (Chapter 6): Rs 1,000 ÷ 100 shares = Rs 10 → stop-loss sell at 770.", "Working: Rs 1,000 / 100 = Rs 10 → stop-loss sell at 770. A plain limit sell at 770 would execute immediately at the current higher price."], "reasons": ["A plain limit sell at 770 would fill immediately at the higher market price", "Buying adds to the position", "Buying adds to the position", "Rs 1,000 / 100 = Rs 10 → stop-loss sell at 770."], "notes": ["Easy way to remember: Protection for a long = stop-loss sell."], "id": 351}, "352": {"ch": 6, "chapter": "Trading Mechanism", "q": "Orders on Indian F&O platforms are matched on the basis of:", "options": ["Size priority", "Price-time priority", "Pro-rata allocation", "Broker priority"], "answer": 1, "why": ["The workbook: orders match automatically on a price-time priority basis — best price first, then earliest time.", "Key point: Best price first; within the same price, earliest time first."], "reasons": ["Size isn't the priority", "Best price first; within the same price, earliest time first.", "Not pro-rata", "Not broker priority"], "notes": ["Easy way to remember: Price first, then time."], "id": 352}, "353": {"ch": 6, "chapter": "Trading Mechanism", "q": "In the order book, the \"best buy order\" is the one with the:", "options": ["Lowest price", "Highest price", "Largest quantity", "Earliest time irrespective of price"], "answer": 1, "why": ["The workbook: the best buy order is the one with the highest price; the best sell order is the one with the lowest price.", "Key point: Best buy = highest bid; best sell = lowest ask."], "reasons": ["Lowest is best for sell orders", "Best buy = highest bid; best sell = lowest ask.", "Quantity isn't the criterion", "Price comes before time"], "notes": ["Easy way to remember: Best bid = highest; best offer = lowest."], "id": 353}, "354": {"ch": 6, "chapter": "Trading Mechanism", "q": "For index futures and stock futures, the operating range (to prevent erroneous orders) is set at:", "options": ["5% of base price", "20% of base price", "No range", "10% of base price"], "answer": 3, "why": ["The workbook: operating ranges are 10% of base price for index futures and stock futures; options have a delta-based range updated daily.", "Key point: 10% of base price for index and stock futures; options have a delta-based contract-specific range updated daily."], "reasons": ["Not 5%", "Not 20%", "There is a range", "10% of base price for index and stock futures; options have a delta-based contract-specific range updated daily."], "notes": ["Easy way to remember: Futures operating range = 10%."], "id": 354}, "355": {"ch": 6, "chapter": "Trading Mechanism", "q": "Under SEBI's May 24, 2024 dynamic price band framework, flexing of price bands now requires:", "options": ["50 trades, 10 unique traders and 3 brokerage firms on each side", "25 trades by 5 unique traders on each side", "100 trades by 20 traders", "Approval of SEBI for each flex"], "answer": 0, "why": ["The workbook: previously 25 trades with 5 unique traders on both sides; now 50 trades, 10 unique traders and 3 brokerage firms on each side.", "Key point: The older criterion (25 trades, 5 unique traders) was tightened to 50 trades, 10 unique traders and 3 brokers on each side."], "reasons": ["The older criterion (25 trades, 5 unique traders) was tightened to 50 trades, 10 unique traders and 3 brokers on each side.", "That's the old criterion", "Not in the workbook", "SEBI approval isn't needed per flex"], "notes": ["Easy way to remember: 50-10-3."], "id": 355}, "356": {"ch": 6, "chapter": "Trading Mechanism", "q": "Under the dynamic price band framework, the first two flexes are:", "options": ["5% after a 15-minute cooling-off (5 minutes if near market close)", "3% after a 30-minute cooling-off", "2% after 60 minutes", "10% instantly"], "answer": 0, "why": ["The workbook: first two increases — 5% after a 15-minute break (5 minutes near close); next two — 3% after 30 minutes; further — 2% after 60 minutes.", "Key point: First two: 5% after 15 min; next two: 3% after 30 min; thereafter 2% after 60 min."], "reasons": ["First two: 5% after 15 min; next two: 3% after 30 min; thereafter 2% after 60 min.", "That's flexes 3–4", "That's flexes 5+", "No instant 10%"], "notes": ["Easy way to remember: 5% / 15 min → 3% / 30 min → 2% / 60 min."], "id": 356}, "357": {"ch": 6, "chapter": "Trading Mechanism", "q": "A futures contract has a price range of Rs 90–110. Under \"sliding\" price bands, the upper band moves to Rs 115. The new lower band is:", "options": ["Rs 95", "Rs 90", "Rs 85", "Rs 100"], "answer": 0, "why": ["Workbook sliding bands example: if the upper band moves to 115, the lower band also moves up to 95.", "Key point: Bands slide together, so the lower band also moves up by 5 to Rs 95."], "reasons": ["Bands slide together, so the lower band also moves up by 5 to Rs 95.", "The lower band doesn't stay", "It moves up, not down", "It moves by 5 only"], "notes": ["Easy way to remember: Bands slide together."], "id": 357}, "358": {"ch": 6, "chapter": "Trading Mechanism", "q": "While entering orders, \"Pro\" identifies:", "options": ["Professional clearing member orders", "Proprietary orders of the trading member", "Priority orders", "Promoter orders"], "answer": 1, "why": ["The workbook: 'Pro' identifies proprietary orders; 'Cli' identifies client orders (with client account number).", "Key point: Pro = proprietary; Cli = client orders (client account number must be given)."], "reasons": ["Not PCM", "Pro = proprietary; Cli = client orders (client account number must be given).", "Not priority", "Not promoter"], "notes": ["Easy way to remember: Pro = own book; Cli = client."], "id": 358}, "359": {"ch": 6, "chapter": "Trading Mechanism", "q": "Which is NOT an eligibility criterion for a stock to enter the F&O segment?", "options": ["Among top 500 stocks by average daily market cap and traded value (six months)", "Median quarter-sigma order size (MQSOS) not less than Rs 75 lakh", "Market-wide position limit not less than Rs 1,500 crore", "Minimum promoter holding of 51%"], "answer": 3, "why": ["Workbook criteria (six months, rolling): top 500 by average daily M-cap and traded value; MQSOS ≥ Rs 75 lakh; MWPL ≥ Rs 1,500 crore; average daily delivery value ≥ Rs 35 crore.", "Key point: The fourth criterion is average daily delivery value in cash of at least Rs 35 crore. No promoter-holding criterion exists."], "reasons": ["Listed criterion", "Listed criterion", "Listed criterion", "No promoter-holding criterion. The fourth criterion is average daily delivery value in cash of at least Rs 35 crore."], "notes": ["Easy way to remember: 500 – 75 lakh – 1,500 cr – 35 cr."], "id": 359}, "360": {"ch": 6, "chapter": "Trading Mechanism", "q": "A stock must meet the F&O entry criteria continuously for:", "options": ["One month", "Three months", "Six months", "One year"], "answer": 2, "why": ["The workbook: the stock \"shall conform to the following broad eligibility criteria for a continuous period of six months\".", "Key point: The criteria apply for a continuous period of six months (rolling)."], "reasons": ["Too short", "Too short (3 months is the exit trigger)", "The criteria apply for a continuous period of six months (rolling).", "Too long (1 year is the re-inclusion bar)"], "notes": ["Easy way to remember: Entry = 6 months."], "id": 360}, "361": {"ch": 6, "chapter": "Trading Mechanism", "q": "The minimum average daily delivery value in the cash market for a stock to be eligible for derivatives is:", "options": ["Rs 10 crore", "Rs 75 crore", "Rs 500 crore", "Rs 35 crore"], "answer": 3, "why": ["The workbook: average daily delivery value in cash ≥ Rs 35 crore in the previous six months.", "Key point: Average daily delivery value ≥ Rs 35 crore over the previous six months."], "reasons": ["Not 10", "Rs 75 crore is the PSF turnover criterion", "Rs 500 crore is the PSF OI criterion", "Average daily delivery value ≥ Rs 35 crore over the previous six months."], "notes": ["Easy way to remember: Delivery value = 35 crore."], "id": 361}, "362": {"ch": 6, "chapter": "Trading Mechanism", "q": "If an existing F&O stock fails the continued eligibility criteria for three consecutive months:", "options": ["All existing contracts are cancelled immediately", "The stock is delisted from the cash market", "Only options are discontinued", "No fresh month contracts are issued; existing contracts trade till expiry and new strikes may be introduced in them"], "answer": 3, "why": ["The workbook: after three consecutive months of failure, no fresh month contracts; existing contracts trade till expiry and new strikes may be introduced in them.", "Key point: Existing contracts continue to expiry; only fresh month contracts are stopped."], "reasons": ["Existing contracts aren't cancelled", "Cash market listing isn't affected", "Both futures and options are affected", "Existing contracts continue to expiry; only fresh month contracts are stopped."], "notes": ["Easy way to remember: Fail 3 months → no new months."], "id": 362}, "363": {"ch": 6, "chapter": "Trading Mechanism", "q": "A stock excluded from the derivatives segment can be considered for re-inclusion after at least:", "options": ["Three months", "Six months", "Two years", "One year from its last trading day in derivatives"], "answer": 3, "why": ["The workbook: once excluded, it shall not be considered for re-inclusion for one year from its last trading day in derivatives.", "Key point: It is not considered for re-inclusion for one year, and must then meet the criteria for six consecutive months."], "reasons": ["Too short", "6 months applies to index re-inclusion", "Too long", "It is not considered for re-inclusion for one year, and must then meet the criteria for six consecutive months."], "notes": ["Easy way to remember: Stock exit → 1-year cooling off."], "id": 363}, "364": {"ch": 6, "chapter": "Trading Mechanism", "q": "Under the Product Success Framework for single stock derivatives, which criterion is correct?", "options": ["At least 15% of active trading members or 200 members, whichever is lower, must have traded in the stock's derivatives", "Average daily turnover of at least Rs 10 crore", "Average daily OI of Rs 4 crore", "Trading on 50% of days"], "answer": 0, "why": ["Workbook stock PSF: 15% of active TMs or 200 TMs (lower); trading on 75% of days; ADT ≥ Rs 75 crore; average daily notional OI ≥ Rs 500 crore.", "Key point: Stock PSF: 15% or 200 TMs (lower), trading on 75% of days, average daily turnover ≥ Rs 75 crore, average daily notional OI ≥ Rs 500 crore. (Rs 10 crore and Rs 4 crore are for index PSF.)"], "reasons": ["Stock PSF: 15% or 200 TMs (lower), trading on 75% of days, average daily turnover ≥ Rs 75 crore, average daily notional OI ≥ Rs 500 crore.", "Rs 10 crore is the index PSF", "Rs 4 crore is the index PSF", "It's 75% of days"], "notes": ["Easy way to remember: Stock PSF: 15%/200, 75%, 75 cr, 500 cr."], "id": 364}, "365": {"ch": 6, "chapter": "Trading Mechanism", "q": "The stock PSF exit criteria apply only to stocks that have completed at least:", "options": ["1 month since introduction", "3 months since introduction", "6 months since introduction", "12 months since introduction"], "answer": 2, "why": ["The workbook: PSF exit applies only to stocks that have completed at least 6 months from introduction (gestation period).", "Key point: After a six-month gestation period, stocks failing PSF exit in the upcoming review cycle."], "reasons": ["Too short", "Too short", "After a six-month gestation period, stocks failing PSF exit in the upcoming review cycle.", "Too long"], "notes": ["Easy way to remember: 6-month gestation."], "id": 365}, "366": {"ch": 6, "chapter": "Trading Mechanism", "q": "An exchange can introduce derivatives on an index if constituents individually eligible for derivatives make up at least ___ of the index, and no single ineligible stock exceeds ___.", "options": ["50%; 10%", "90%; 2%", "80%; 5%", "75%; 5%"], "answer": 2, "why": ["The workbook: at least 80% of index weight must be individually F&O-eligible stocks; no single ineligible stock may exceed 5%.", "Key point: At least 80% weight must be F&O-eligible stocks; no ineligible stock may exceed 5%."], "reasons": ["Wrong numbers", "Wrong numbers", "At least 80% weight must be F&O-eligible stocks; no ineligible stock may exceed 5%.", "75% is wrong"], "notes": ["Easy way to remember: Index eligibility = 80 / 5."], "id": 366}, "367": {"ch": 6, "chapter": "Trading Mechanism", "q": "Under the index Product Success Framework, the required average daily turnover and average daily open interest are:", "options": ["Rs 75 crore and Rs 500 crore", "Rs 10 crore and Rs 4 crore", "Rs 35 crore and Rs 15 crore", "Rs 1 crore and Rs 1 crore"], "answer": 1, "why": ["Workbook index PSF: 15% of active TMs or 20 TMs (lower); 75% trading days; ADT Rs 10 crore; average daily OI Rs 4 crore. Flagship indices are exempt.", "Key point: Index PSF: 15% of active TMs or 20 TMs (lower), 75% trading days, ADT Rs 10 crore, average daily OI Rs 4 crore. Flagship indices are exempt."], "reasons": ["These are stock PSF numbers", "Index PSF: 15% of active TMs or 20 TMs (lower), 75% trading days, ADT Rs 10 crore, average daily OI Rs 4 crore.", "Not in the workbook", "Not in the workbook"], "notes": ["Easy way to remember: Index PSF: 10 cr turnover, 4 cr OI."], "id": 367}, "368": {"ch": 6, "chapter": "Trading Mechanism", "q": "Which condition is NOT required for a surrogate/pseudo index?", "options": ["Constituents of the smaller index at least 80% of the larger index", "Both indices must be on the same exchange", "At least 50% of the larger index's stocks are in the smaller index", "Correlation of at least 0.90 over the previous 6 months"], "answer": 1, "why": ["Workbook conditions: smaller index has ≥ 80% of the larger index's constituents; ≥ 50% overlap; correlation ≥ 0.90 over 6 months. A surrogate exists in another exchange; one per exchange.", "Key point: A surrogate index exists on another exchange; one surrogate per exchange is permitted."], "reasons": ["Required condition", "Not required — it is on another exchange. A surrogate index exists on another exchange; one surrogate per exchange is permitted.", "Required condition", "Required condition"], "notes": ["Easy way to remember: Surrogate = 80% / 50% / 0.90."], "id": 368}, "369": {"ch": 6, "chapter": "Trading Mechanism", "q": "A 1:2 bonus (1 bonus share for every 2 held). A 900 strike option with lot size 400 will be adjusted to:", "options": ["Strike 450; lot 800", "Strike 1,350; lot 267", "Strike 600; lot 600", "Strike 600; lot 400"], "answer": 2, "why": ["Workbook: bonus ratio A:B → adjustment factor = (A + B)/B. New strike = old ÷ factor; new lot = old × factor.", "Working: Adjustment factor = (A + B)/B = (1 + 2)/2 = 1.5. New strike = 900/1.5 = 600; new lot = 400 × 1.5 = 600. Position value stays the same."], "reasons": ["Uses factor 2 (a 1:1 bonus)", "Multiplies strike instead of dividing", "(1 + 2)/2 = 1.5 → 900/1.5 = 600; 400 × 1.5 = 600", "Lot must change too"], "notes": ["Easy way to remember: Strike ÷ factor, lot × factor."], "id": 369}, "370": {"ch": 6, "chapter": "Trading Mechanism", "q": "A 1:1 bonus. A stock option with strike Rs 1,200 and lot 500 becomes:", "options": ["Strike 1,200; lot 1,000", "Strike 600; lot 500", "Strike 2,400; lot 250", "Strike 600; lot 1,000"], "answer": 3, "why": ["Factor = (1 + 1)/1 = 2.", "Working: Factor = (1 + 1)/1 = 2. Strike 1,200/2 = 600; lot 500 × 2 = 1,000."], "reasons": ["Strike must fall too", "Lot must rise too", "Reversed", "Factor = (1 + 1)/1 = 2."], "notes": ["Easy way to remember: 1:1 bonus = halve strike, double lot."], "id": 370}, "371": {"ch": 6, "chapter": "Trading Mechanism", "q": "A stock split from face value Rs 10 to Rs 2 (ratio A:B = 10:2). A 1,000 strike option with lot 250 becomes:", "options": ["Strike 500; lot 500", "Strike 200; lot 1,250", "Strike 5,000; lot 50", "Strike 200; lot 250"], "answer": 1, "why": ["Workbook: for splits, factor = A/B = 10/2 = 5.", "Working: Factor = A/B = 10/2 = 5. Strike 1,000/5 = 200; lot 250 × 5 = 1,250."], "reasons": ["Uses factor 2", "Factor = A/B = 10/2 = 5.", "Reversed", "Lot must change"], "notes": ["Easy way to remember: Split factor = old FV ÷ new FV."], "id": 371}, "372": {"ch": 6, "chapter": "Trading Mechanism", "q": "Rights issue: 1 right for every 5 held (A = 5, B = 1); last cum price P = Rs 110; issue price S = Rs 80. The adjustment factor is:", "options": ["0.7273", "1.2000", "0.9091", "0.9545"], "answer": 3, "why": ["Workbook formula: benefit per right = P − S; E = (P − S)/(A + B); factor = (P − E)/P.", "Working: Benefit per right = P − S = 30. E = 30/(A + B) = 30/6 = 5. Factor = (P − E)/P = 105/110 = 0.9545."], "reasons": ["Uses S/P", "Factor below 1 for rights", "Wrong E", "(110 − 5)/110 = 0.9545. Benefit per right = P − S = 30."], "notes": ["Easy way to remember: Rights: E = (P − S)/(A + B)."], "id": 372}, "373": {"ch": 6, "chapter": "Trading Mechanism", "q": "Adjustments for corporate actions are carried out:", "options": ["On the ex-date before trading starts", "On the last cum-date after the close of trading hours", "On the record date", "At the next expiry"], "answer": 1, "why": ["The workbook: adjustments are carried out on the last day the security trades on a 'cum' basis, after the close of trading hours.", "Key point: Adjustments happen after market hours on the last day the stock trades cum-benefit."], "reasons": ["Not on the ex-date", "Adjustments happen after market hours on the last day the stock trades cum-benefit.", "Not on record date", "Not deferred to expiry"], "notes": ["Easy way to remember: Last cum-day, after close."], "id": 373}, "374": {"ch": 6, "chapter": "Trading Mechanism", "q": "A stock trades at Rs 500 (previous close before announcement) and declares a dividend of Rs 12. Treatment in F&O:", "options": ["Ordinary dividend; no adjustment", "Contracts cancelled", "Lot size doubled", "Extraordinary (≥ 2%); strike prices reduced by the dividend amount from the ex-date"], "answer": 3, "why": ["The workbook: dividends ≥ 2% of market value are extraordinary; strike prices are reduced by the dividend amount from the ex-dividend date; futures carried at settlement price less dividend.", "Working: 12/500 = 2.4% ≥ 2% → extraordinary. Strikes reduced by the dividend; futures carried at settlement price less dividend."], "reasons": ["2.4% is above 2%", "Contracts aren't cancelled", "Lot size isn't adjusted", "Correct — 12/500 = 2.4%. 12/500 = 2.4% ≥ 2% → extraordinary."], "notes": ["Easy way to remember: Dividend ≥ 2% → cut strikes."], "id": 374}, "375": {"ch": 6, "chapter": "Trading Mechanism", "q": "A stock at Rs 800 declares a dividend of Rs 14. Treatment:", "options": ["Extraordinary; strikes reduced by 14", "Strikes reduced by 2%", "Ordinary; no strike adjustment", "Lot size adjusted"], "answer": 2, "why": ["14/800 = 1.75% < 2% → ordinary dividend; no strike adjustment.", "Working: 14/800 = 1.75% < 2% → ordinary dividend; no adjustment."], "reasons": ["It's below 2%", "Strikes aren't adjusted", "14/800 = 1.75% < 2% → ordinary dividend; no adjustment.", "Lot isn't adjusted"], "notes": ["Easy way to remember: Below 2% → ignore."], "id": 375}, "376": {"ch": 6, "chapter": "Trading Mechanism", "q": "The market price used to test whether a dividend is \"extraordinary\" is:", "options": ["The closing price on the record date", "The 52-week average price", "The closing price on the day before the Board announces the dividend (same day's close if announced after market hours)", "The ex-date opening price"], "answer": 2, "why": ["The workbook: closing price on the day previous to the Board's announcement; if announced after market hours, the same day's close.", "Key point: The previous day's close before announcement is used, or the same day's close if announced after hours."], "reasons": ["Not the record date", "Not a 52-week average", "The previous day's close before announcement is used, or the same day's close if announced after hours.", "Not the ex-date open"], "notes": ["Easy way to remember: Day-before-announcement close."], "id": 376}, "377": {"ch": 6, "chapter": "Trading Mechanism", "q": "On a merger where the underlying will cease to exist, unexpired contracts outstanding on the last cum-date are:", "options": ["Rolled into the acquirer's contracts", "Compulsorily settled at the last available closing price of the underlying on the last cum-date", "Kept open till expiry", "Cancelled without settlement"], "answer": 1, "why": ["The workbook: unexpired contracts are compulsorily settled at the last available closing price in the capital market on the last cum-date.", "Key point: No fresh contracts are introduced after the record date announcement; open contracts are settled at the last cum-date closing price."], "reasons": ["No rollover into acquirer's contracts", "No fresh contracts are introduced after the record date announcement; open contracts are settled at the last cum-date closing price.", "They don't stay open", "They are settled, not cancelled"], "notes": ["Easy way to remember: Company disappears → settle at last cum close."], "id": 377}, "378": {"ch": 6, "chapter": "Trading Mechanism", "q": "As per Union Budget 2026-27 (effective April 1, 2026), STT on sale of futures is:", "options": ["0.02% on price, payable by seller", "0.05% on the traded price, payable by the seller", "0.1% payable by buyer", "0.15% on premium"], "answer": 1, "why": ["Workbook STT table: sale of futures 0.05% on traded price (seller); sale of option 0.15% on premium (seller); exercised option 0.15% on settlement price (purchaser).", "Key point: Futures: 0.05% of traded price, seller. Options sold: 0.15% of premium, seller. Exercised options: 0.15% on settlement price, purchaser."], "reasons": ["Old/incorrect rate", "Futures: 0.05% of traded price, seller.", "Payable by seller, not buyer", "0.15% is for options"], "notes": ["Easy way to remember: Futures 0.05%; options 0.15%."], "id": 378}, "379": {"ch": 6, "chapter": "Trading Mechanism", "q": "A trader sells one lot of options (lot 75) at a premium of Rs 100. The STT payable at the rate applicable from April 1, 2026 is:", "options": ["Rs 3.75", "Rs 11.25", "Rs 37.50", "Rs 112.50"], "answer": 1, "why": ["STT on option sale = 0.15% × premium value.", "Working: Premium value = 100 × 75 = 7,500. STT = 0.15% × 7,500 = 11.25, payable by the seller."], "reasons": ["3.75 uses 0.05%", "7,500 × 0.15% = 11.25. Premium value = 100 × 75 = 7,500.", "37.50 uses 0.5%", "112.50 uses 1.5%"], "notes": ["Easy way to remember: Option STT on premium only."], "id": 379}, "380": {"ch": 6, "chapter": "Trading Mechanism", "q": "For a short futures trade of contract value Rs 8,75,000, STT at the current rate is:", "options": ["Rs 437.50", "Rs 175.00", "Rs 262.50", "Rs 875.00"], "answer": 0, "why": ["Workbook cost example: STT @ 0.05% = 437.50.", "Working: 0.05% × 8,75,000 = 437.50."], "reasons": ["0.05% × 8,75,000 = 437.50.", "Uses 0.02%", "Uses 0.03% (the brokerage rate)", "Uses 0.1%"], "notes": ["Easy way to remember: 8,75,000 × 0.0005."], "id": 380}, "381": {"ch": 6, "chapter": "Trading Mechanism", "q": "Stamp duty is charged on:", "options": ["Sellers of futures at 0.002%", "Buyers only — 0.002% for equity futures and 0.003% for equity options", "Both sides at 0.005%", "Only on exercised options"], "answer": 1, "why": ["The workbook: stamp duty 0.002% (Rs 200/crore) for buyers of equity futures and 0.003% (Rs 300/crore) for buyers of equity options.", "Key point: Stamp duty is buyer-side only: futures 0.002% (Rs 200/crore), options 0.003% (Rs 300/crore)."], "reasons": ["It is on buyers, not sellers", "Stamp duty is buyer-side only: futures 0.002% (Rs 200/crore), options 0.003% (Rs 300/crore).", "Not both sides", "Not only exercised options"], "notes": ["Easy way to remember: Stamp duty = buyer pays."], "id": 381}, "382": {"ch": 6, "chapter": "Trading Mechanism", "q": "NSE IPFT charges on equity options are levied at:", "options": ["Rs 10 per crore of traded value + GST", "0.05% of premium", "Rs 50 per crore of premium value + 18% GST", "Nil"], "answer": 2, "why": ["Workbook table: NSE equity and futures Rs 10/crore of traded value + GST; equity options Rs 50/crore of premium value + 18% GST.", "Key point: NSE equity and futures: Rs 10/crore of traded value + GST; equity options: Rs 50/crore of premium + GST."], "reasons": ["That's for equity and futures", "Not in the workbook", "NSE equity and futures: Rs 10/crore of traded value + GST; equity options: Rs 50/crore of premium + GST.", "IPFT is charged"], "notes": ["Easy way to remember: IPFT options = Rs 50/crore of premium."], "id": 382}, "383": {"ch": 6, "chapter": "Trading Mechanism", "q": "Which of the following is an implicit cost that is not actually paid by market participants?", "options": ["Bid-ask spread and impact cost", "STT", "Brokerage", "Stamp duty"], "answer": 0, "why": ["The workbook: bid-ask spread and impact cost \"are not actually paid by market participants\"; they arise from market imperfections or lack of liquidity.", "Key point: Spread/impact cost arise from market imperfections or illiquidity; they are not charges paid to anyone."], "reasons": ["Spread/impact cost arise from market imperfections or illiquidity; they are not charges paid to anyone.", "STT is explicit", "Brokerage is explicit", "Stamp duty is explicit"], "notes": ["Easy way to remember: Implicit costs hide in the price."], "id": 383}, "384": {"ch": 6, "chapter": "Trading Mechanism", "q": "Best bid for an option is Rs 16.60 and best ask Rs 16.80. An investor buys at market and immediately sells at market. His loss per unit is:", "options": ["Rs 0.10", "Rs 0.20", "Rs 0.40", "Nil"], "answer": 1, "why": ["Workbook example: buying at ask 16.80 and selling at bid 16.60 loses 0.20 — the bid-ask spread.", "Working: Buys at 16.80, sells at 16.60 → loss = bid-ask spread = 0.20 per unit."], "reasons": ["Half the spread", "Buys at 16.80, sells at 16.60 → loss = bid-ask spread = 0.20 per unit.", "Double the spread", "There is a loss"], "notes": ["Easy way to remember: Round trip at market = lose the spread."], "id": 384}, "385": {"ch": 6, "chapter": "Trading Mechanism", "q": "Under SEBI's retail algo framework, registration of an algo with the exchange via the broker is mandatory when orders per second exceed:", "options": ["5", "50", "10", "100"], "answer": 2, "why": ["Workbook table: low-frequency algo ≤ 10 orders per second — registration not required, generic algo ID; > 10 OPS — registration mandatory via broker with unique exchange ID.", "Key point: ≤ 10 OPS: no registration (generic algo ID). > 10 OPS: registration mandatory with a unique exchange ID."], "reasons": ["Not 5", "Not 50", "≤ 10 OPS: no registration (generic algo ID).", "Not 100"], "notes": ["Easy way to remember: Above 10 OPS → register."], "id": 385}, "386": {"ch": 6, "chapter": "Trading Mechanism", "q": "A \"black box\" algo provider must:", "options": ["Register as an Investment Adviser", "Register as a Research Analyst and maintain a research report for each algo", "Disclose logic to users", "Obtain no registration"], "answer": 1, "why": ["Workbook table: black box — logic not disclosed; provider must register as a Research Analyst and maintain a research report for each algo; each logic change is a new algo.", "Key point: Black box logic isn't disclosed to users, so the provider must be an RA and every logic change is a new algo. White box algos need no registration."], "reasons": ["Not IA", "Black box logic isn't disclosed to users, so the provider must be an RA and every logic change is a new algo.", "Black box logic is NOT disclosed", "Registration is required"], "notes": ["Easy way to remember: Black box → RA registration."], "id": 386}, "387": {"ch": 6, "chapter": "Trading Mechanism", "q": "Which is NOT permitted under the retail algo trading framework?", "options": ["Static IP mapped to API key", "OAuth with mandatory 2FA", "Sharing within family (self, spouse, dependent children/parents) with 2FA", "Open APIs"], "answer": 3, "why": ["Workbook table: open APIs not allowed; static IP mapped to API key; OAuth with mandatory 2FA; sharing within family allowed with 2FA.", "Key point: Open APIs are not allowed; access must be via broker-approved static IP with OAuth and 2FA."], "reasons": ["Permitted", "Permitted", "Permitted", "Not permitted. Open APIs are not allowed; access must be via broker-approved static IP with OAuth and 2FA."], "notes": ["Easy way to remember: No open APIs."], "id": 387}, "388": {"ch": 6, "chapter": "Trading Mechanism", "q": "A kill switch in algo trading is:", "options": ["A tool to cancel all client KYC", "A broker's right to refuse algo orders", "A SEBI order to close an exchange", "An emergency last line of defence that halts trading automatically on pre-defined conditions"], "answer": 3, "why": ["Workbook: a kill switch is an emergency function and the last level of defence against algorithm malfunction, halting trading automatically on pre-defined conditions.", "Key point: The kill switch automatically halts trading when an algo malfunctions."], "reasons": ["Not KYC-related", "Not a broker's refusal right", "Not a SEBI order", "The kill switch automatically halts trading when an algo malfunctions."], "notes": ["Easy way to remember: Kill switch = emergency brake."], "id": 388}, "389": {"ch": 6, "chapter": "Trading Mechanism", "q": "Complaints related to algo trading and API monitoring are handled by:", "options": ["SEBI directly", "Stock exchange", "The broker, solely", "The algo provider"], "answer": 2, "why": ["The workbook: brokers are solely responsible for handling investor grievances related to algo trading and monitoring APIs; SEBI and the exchange will not entertain any complaint.", "Key point: Brokers are solely responsible for algo-related investor grievances; SEBI and exchanges won't entertain such complaints."], "reasons": ["SEBI won't entertain these", "The exchange won't entertain these", "Brokers are solely responsible for algo-related investor grievances; SEBI and exchanges won't entertain such complaints.", "The algo provider isn't the complaint handler"], "notes": ["Easy way to remember: Algo complaint → broker."], "id": 389}, "390": {"ch": 6, "chapter": "Trading Mechanism", "q": "The IRRA platform allows investors to:", "options": ["Square off open positions and cancel pending orders when the trading member's services are disrupted", "Open new positions when the broker's system is down", "Transfer accounts to another broker", "Trade algos"], "answer": 0, "why": ["The workbook: IRRA lets investors square off open positions and/or cancel pending orders when the TM's services are disrupted; it does not permit any action that increases risk; not for algo or institutional clients.", "Key point: IRRA is a joint exchange platform for risk-reducing actions only; it is for individual investors, not algo or institutional clients."], "reasons": ["IRRA is a joint exchange platform for risk-reducing actions only; it is for individual investors, not algo or institutional clients.", "New positions are not allowed", "No account transfers", "Not for algos"], "notes": ["Easy way to remember: IRRA = exit door only."], "id": 390}, "391": {"ch": 6, "chapter": "Trading Mechanism", "q": "Under SEBI's technical glitch framework, a stock broker must submit a Root Cause Analysis report to the exchange within:", "options": ["14 days", "1 hour", "T+1 day", "30 days"], "answer": 0, "why": ["The workbook: inform the exchange within 1 hour; preliminary incident report within T+1; RCA report within 14 days.", "Key point: Inform exchange within 1 hour; preliminary incident report within T+1; RCA within 14 days."], "reasons": ["Inform exchange within 1 hour; preliminary incident report within T+1; RCA within 14 days.", "1 hour is the initial intimation", "T+1 is the preliminary report", "Not 30 days"], "notes": ["Easy way to remember: 1 hour → T+1 → 14 days."], "id": 391}, "392": {"ch": 6, "chapter": "Trading Mechanism", "q": "In the business continuity mechanism for interoperable segments, the affected exchange must intimate SEBI and the alternate venue within ___ of impact, and the alternate venue must invoke its plan within ___ of intimation.", "options": ["75 minutes; 15 minutes", "15 minutes; 75 minutes", "1 hour; 1 hour", "30 minutes; 30 minutes"], "answer": 0, "why": ["The workbook: the affected exchange intimates SEBI and the alternate venue within 75 minutes of impact; the alternate venue invokes the SOP within 15 minutes of intimation.", "Key point: 75 minutes to intimate; 15 minutes for the alternate venue (NSE for BSE and vice versa) to invoke its SOP."], "reasons": ["75 minutes to intimate; 15 minutes for the alternate venue (NSE for BSE and vice versa) to invoke its SOP.", "Swapped", "Not in the workbook", "Not in the workbook"], "notes": ["Easy way to remember: 75 then 15."], "id": 392}, "393": {"ch": 6, "chapter": "Trading Mechanism", "q": "In the NSE data feed, \"PE\" under option type stands for:", "options": ["Price-earnings", "Premium Exercised", "Put Expired", "Put European"], "answer": 3, "why": ["The workbook: CE — Call European; PE — Put European; CA — Call American; PA — Put American.", "Key point: CE = Call European, PE = Put European, CA/PA = American call/put."], "reasons": ["Not a valuation ratio here", "Not a workbook term", "Not a workbook term", "CE = Call European, PE = Put European, CA/PA = American call/put."], "notes": ["Easy way to remember: C/P + E/A."], "id": 393}, "394": {"ch": 7, "chapter": "Clearing, Settlement and Risk Management", "q": "The legal principle by which the clearing corporation becomes the central counterparty to all trades is called:", "options": ["Subrogation", "Assignment", "Netting", "Novation"], "answer": 3, "why": ["The workbook: \"According to the legal principle of 'novation', the Clearing Corporation becomes the central counterparty to all trades.\"", "Key point: Under novation, the clearing corporation interposes itself as buyer to every seller and seller to every buyer and guarantees settlement."], "reasons": ["Subrogation is an insurance concept", "Assignment relates to exercised options", "Netting is a calculation step", "Under novation, the clearing corporation interposes itself as buyer to every seller and seller to every buyer and guarantees settlement."], "notes": ["Easy way to remember: Novation = CC steps into the middle."], "id": 394}, "395": {"ch": 7, "chapter": "Clearing, Settlement and Risk Management", "q": "The three main activities of the clearing and settlement process are:", "options": ["Trading, clearing, surveillance", "Margining, delivery, taxation", "KYC, clearing, reporting", "Clearing, settlement, risk management"], "answer": 3, "why": ["The workbook: \"The Clearing and Settlement process comprises of three main activities, viz., Clearing, Settlement and Risk Management.\"", "Key point: Clearing (computing obligations), settlement (actual settlement) and risk management."], "reasons": ["Trading is not part of clearing", "Taxation isn't part", "KYC isn't part", "Clearing (computing obligations), settlement (actual settlement) and risk management."], "notes": ["Easy way to remember: Clear, Settle, Manage risk."], "id": 395}, "396": {"ch": 7, "chapter": "Clearing, Settlement and Risk Management", "q": "Which type of clearing member must bring an additional security deposit for every trading member whose trades it clears?", "options": ["Trading-cum-clearing member and professional clearing member", "Self-clearing member only", "Only custodial participants", "No clearing member"], "answer": 0, "why": ["The workbook: \"Both trading-cum-clearing member and professional clearing member are required to bring in additional security deposits in respect of every trading member whose trades they undertake to clear.\"", "Key point: Both TCMs and PCMs clearing for others bring additional deposits per TM."], "reasons": ["Both TCMs and PCMs clearing for others bring additional deposits per TM.", "SCMs clear only their own trades", "Custodial participants are clients", "Some members must"], "notes": ["Easy way to remember: Clear for others → deposit for each."], "id": 396}, "397": {"ch": 7, "chapter": "Clearing, Settlement and Risk Management", "q": "Clearing member eligibility norms in the workbook include a net worth of at least ___ and a security deposit of ___ with the clearing corporation.", "options": ["Rs 300 lakh; Rs 50 lakh", "Rs 100 lakh; Rs 25 lakh", "Rs 500 lakh; Rs 100 lakh", "Rs 50 lakh; Rs 10 lakh"], "answer": 0, "why": ["The workbook: net worth at least Rs 300 lakh (Rs 100 lakh if clearing only own deals); deposit Rs 50 lakh; additional Rs 10 lakh for each additional TM.", "Key point: Rs 300 lakh net worth (Rs 100 lakh if clearing only own deals); Rs 50 lakh deposit; plus Rs 10 lakh for each additional TM cleared."], "reasons": ["Rs 300 lakh net worth (Rs 100 lakh if clearing only own deals); Rs 50 lakh deposit; plus Rs 10 lakh for each additional TM cleared.", "Rs 100 lakh is for self-only clearing", "Too high", "Too low"], "notes": ["Easy way to remember: 300 lakh net worth, 50 lakh deposit."], "id": 397}, "398": {"ch": 7, "chapter": "Clearing, Settlement and Risk Management", "q": "A clearing member clears for three other trading members in addition to itself. Its deposit with the clearing corporation per the norms is:", "options": ["Rs 50 lakh", "Rs 80 lakh", "Rs 60 lakh", "Rs 1.2 crore"], "answer": 1, "why": ["Deposit = Rs 50 lakh base + Rs 10 lakh per additional TM.", "Key point: Base Rs 50 lakh + Rs 10 lakh × 3 additional TMs = Rs 80 lakh."], "reasons": ["Ignores the additional TMs", "50 + 30 = 80 lakh. Base Rs 50 lakh + Rs 10 lakh × 3 additional TMs = Rs 80 lakh.", "Counts only one TM", "Overstates"], "notes": ["Easy way to remember: 50 + 10 × extra TMs."], "id": 398}, "399": {"ch": 7, "chapter": "Clearing, Settlement and Risk Management", "q": "Funds settlement in the F&O segment takes place through:", "options": ["SEBI's account", "Clearing banks designated by the clearing corporation", "Depositories", "The exchange's own treasury"], "answer": 1, "why": ["The workbook: funds settlement takes place through clearing banks; all CMs open a separate F&O account with a clearing bank designated by the clearing corporation.", "Key point: All CMs open a separate account with a designated clearing bank for F&O settlement."], "reasons": ["SEBI doesn't hold settlement funds", "All CMs open a separate account with a designated clearing bank for F&O settlement.", "Depositories handle securities, not funds", "Not the exchange's treasury"], "notes": ["Easy way to remember: Money via clearing banks; shares via depositories."], "id": 399}, "400": {"ch": 7, "chapter": "Clearing, Settlement and Risk Management", "q": "TM PQR: Proprietary net +2,000; Client 1 net +1,000; Client 2 net +2,000 (Nifty May). TM XYZ: Proprietary −1,000; Client 1 +1,000; Client 2 −1,000. Clearing member A's open position is:", "options": ["Long 5,000; Short 1,000", "Long 4,000; Short 0", "Long 6,000; Short 2,000", "Long 4,000 (net)"], "answer": 2, "why": ["Workbook example: TM open position = proprietary net + client longs + client shorts (clients not netted against each other). CM = sum across TMs.", "Working: PQR: long 5,000. XYZ: long 1,000 (client 1), short 2,000 (prop −1,000 and client 2 −1,000). CM A = long 6,000, short 2,000."], "reasons": ["Ignores part of PQR and XYZ positions", "Understates the long and ignores the short", "PQR: long 5,000.", "Netting long vs short at CM level isn't done"], "notes": ["Easy way to remember: CM position = Σ TM longs; Σ TM shorts."], "id": 400}, "401": {"ch": 7, "chapter": "Clearing, Settlement and Risk Management", "q": "A TM's proprietary trades: buy 400, sell 100. Client X: buy 200, sell 500. Client Y: buy 100. The TM's open position is:", "options": ["Long 700; Short 600", "Net long 100", "Long 400; Short 300", "Long 300; Short 0"], "answer": 2, "why": ["The workbook: proprietary positions are netted per contract; client positions are the sum of net positions of each individual client, and client longs and shorts are kept separate.", "Working: Prop is netted: +300 long. Clients are netted individually and then kept gross: X = −300 (short), Y = +100 (long). TM long = 300 + 100 = 400; short = 300."], "reasons": ["Uses gross trades, not net positions", "Nets clients against each other — not allowed", "Prop is netted: +300 long.", "Ignores client X's short"], "notes": ["Easy way to remember: Prop nets; clients stay gross."], "id": 401}, "402": {"ch": 7, "chapter": "Clearing, Settlement and Risk Management", "q": "A member has two clients: C1 bought 800 and C2 sold 900 contracts in the same futures series. The member's open position toward the clearing corporation is:", "options": ["1,700", "100", "800", "900"], "answer": 0, "why": ["Workbook sample: client positions are not netted, so open position = 800 long + 900 short = 1,700.", "Working: Client positions are not netted against each other: long 800 + short 900 = 1,700 contracts."], "reasons": ["Client positions are not netted against each other: long 800 + short 900 = 1,700 contracts.", "Netting is wrong", "Ignores C2", "Ignores C1"], "notes": ["Easy way to remember: Client positions add up, never cancel."], "id": 402}, "403": {"ch": 7, "chapter": "Clearing, Settlement and Risk Management", "q": "\"Clients' positions cannot be netted off against each other while calculating initial margin on the derivatives segment.\"", "options": ["True", "False"], "answer": 0, "why": ["Workbook sample (True): margins are paid upfront on a gross basis at individual client level; net basis only for proprietary positions.", "Key point: Margins are collected on a gross basis at individual client level; only proprietary positions are netted."], "reasons": ["Correct — True. Margins are collected on a gross basis at individual client level; only proprietary positions are netted.", "False would allow netting across clients"], "notes": ["Easy way to remember: Gross for clients, net for prop."], "id": 403}, "404": {"ch": 7, "chapter": "Clearing, Settlement and Risk Management", "q": "Interoperability of clearing corporations was proposed in 2018 and implemented in 2019. A client is long 10 lots of SBI May futures on NSE and short 6 lots on BSE. His net position for margining is:", "options": ["Long 16", "Long 10 and short 6 separately", "Long 4", "Short 4"], "answer": 2, "why": ["Workbook example: long 10 SBI futures on NSE, short 6 on BSE → net long 4 contracts; margin computed accordingly.", "Working: With interoperability, positions across exchanges net at the chosen clearing corporation: 10 − 6 = long 4."], "reasons": ["Adding them is wrong", "Interoperability allows netting", "With interoperability, positions across exchanges net at the chosen clearing corporation: 10 − 6 = long 4.", "Sign wrong"], "notes": ["Easy way to remember: Interoperability nets across exchanges."], "id": 404}, "405": {"ch": 7, "chapter": "Clearing, Settlement and Risk Management", "q": "Which is NOT a benefit of clearing corporation interoperability?", "options": ["Collateral maintained with a single clearing corporation", "Elimination of all margins", "Better capital utilisation", "Continuity if one exchange's clearing link is disrupted"], "answer": 1, "why": ["Workbook benefits: single CC for collateral, better capital use, continuity during disruption, simpler compliance, competition among CCs. Margins still apply.", "Key point: Margins remain; they are simply computed on consolidated positions at one CC."], "reasons": ["Listed benefit", "Margins are not eliminated. Margins remain; they are simply computed on consolidated positions at one CC.", "Listed benefit", "Listed benefit"], "notes": ["Easy way to remember: Interoperability = efficiency, not zero margin."], "id": 405}, "406": {"ch": 7, "chapter": "Clearing, Settlement and Risk Management", "q": "Since October 2019, open positions in stock futures and stock options on expiry are settled by:", "options": ["Cash", "Choice of the client", "Rollover to next month", "Physical delivery"], "answer": 3, "why": ["The workbook: since October 2019, open positions in stock F&O on expiry are settled by physical delivery; index F&O remain cash-settled.", "Key point: Stock F&O is physically settled; index F&O remains cash settled."], "reasons": ["Index F&O are cash settled", "Not the client's choice", "No automatic rollover", "Stock F&O is physically settled; index F&O remains cash settled."], "notes": ["Easy way to remember: Stocks deliver; indices pay cash."], "id": 406}, "407": {"ch": 7, "chapter": "Clearing, Settlement and Risk Management", "q": "For a futures contract executed today and not squared off, the day's MTM is the difference between:", "options": ["Previous day's settlement price and today's settlement price", "Trade price and today's settlement price", "Buy price and sell price", "Trade price and final settlement price"], "answer": 1, "why": ["The workbook: MTM is the difference between (i) trade price and day's settlement for new positions; (ii) previous and current settlement for brought-forward; (iii) buy and sell price for intraday squared-off.", "Key point: New open positions: trade price vs day's settlement. Brought-forward: previous vs current settlement. Squared-off intraday: buy vs sell price."], "reasons": ["That's for brought-forward positions", "New open positions: trade price vs day's settlement.", "That's for squared-off intraday trades", "Final settlement applies at expiry"], "notes": ["Easy way to remember: New position → trade price vs today's settlement."], "id": 407}, "408": {"ch": 7, "chapter": "Clearing, Settlement and Risk Management", "q": "The daily settlement price for futures, per Chapter 7, is based on:", "options": ["The closing price of the underlying", "The theoretical price F = S·e^(rt) always", "The last 30 minutes' volume-weighted average price of the contract across exchanges", "The day's high-low average"], "answer": 2, "why": ["The workbook (Chapter 7): daily settlement price is based on the last 30 minutes' volume-weighted average price of the contract across exchanges.", "Working: Last half-hour VWAP across exchanges; if not traded in the last half hour, a theoretical price F = S·e^(rt) is used."], "reasons": ["The underlying close is for final settlement", "Theoretical price is only if not traded in the last half hour", "Last half-hour VWAP across exchanges; if not traded in the last half hour, a theoretical price F = S·e^(rt) is used.", "Not the high-low average"], "notes": ["Easy way to remember: Daily = last 30-min VWAP."], "id": 408}, "409": {"ch": 7, "chapter": "Clearing, Settlement and Risk Management", "q": "If a futures contract does not trade in the last half-hour, the daily settlement price is:", "options": ["The previous day's settlement price", "A theoretical price computed as F = S × e^(rt)", "The spot closing price", "Zero"], "answer": 1, "why": ["The workbook: a theoretical daily settlement price F = S × e^(rt) is computed (r = MIBOR or specified rate, t = time to expiry).", "Key point: r may be MIBOR or another specified rate; t is time to expiry."], "reasons": ["Not the previous settlement", "r may be MIBOR or another specified rate; t is time to expiry.", "Not the spot close", "Not zero"], "notes": ["Easy way to remember: Not traded → theoretical F = S·e^(rt)."], "id": 409}, "410": {"ch": 7, "chapter": "Clearing, Settlement and Risk Management", "q": "Daily MTM pay-in/pay-out for futures is effected:", "options": ["On T+2", "Before the start of market hours on the next day", "Weekly", "At expiry only"], "answer": 1, "why": ["The workbook: daily MTM is cash-settled; pay-in and pay-out happen before the start of market hours on the next day.", "Key point: Daily MTM is cash-settled before market opens the next day, via clearing bank debits/credits."], "reasons": ["Not T+2", "Daily MTM is cash-settled before market opens the next day, via clearing bank debits/credits.", "Not weekly", "Not only at expiry"], "notes": ["Easy way to remember: MTM settles before next day's open."], "id": 410}, "411": {"ch": 7, "chapter": "Clearing, Settlement and Risk Management", "q": "Mr P holds 1 lot long of a stock future on expiry. Lot 1,500; final settlement price Rs 475; previous day's settlement Rs 482. His obligations are:", "options": ["Receive Rs 10,500 MTM", "Pay Rs 7,23,000 only", "Deliver 1,500 shares", "Take delivery of 1,500 shares paying Rs 7,12,500, and pay MTM loss of Rs 10,500"], "answer": 3, "why": ["Workbook Example 1: long futures on expiry → take delivery at FSP (1,500 × 475 = 7,12,500) and pay final MTM (475 − 482) × 1,500 = −10,500.", "Working: Physical settlement at FSP: 1,500 × 475 = 7,12,500. Plus final MTM (475 − 482) × 1,500 = −10,500."], "reasons": ["Direction wrong: the price fell, so the long pays", "7,23,000 uses 482 — wrong", "A long receives shares, doesn't deliver", "Physical settlement at FSP: 1,500 × 475 = 7,12,500."], "notes": ["Easy way to remember: Long futures at expiry = buy the shares at FSP."], "id": 411}, "412": {"ch": 7, "chapter": "Clearing, Settlement and Risk Management", "q": "Mr Q holds 1 lot short in the same stock future (lot 1,500; FSP 475; previous settlement 482). His obligations:", "options": ["Deliver 1,500 shares at Rs 475 and receive MTM credit of Rs 10,500", "Pay MTM Rs 10,500 and receive shares", "Deliver shares and pay Rs 10,500", "Nothing — shorts are cash settled"], "answer": 0, "why": ["Workbook Example 2: short → deliver 1,500 shares at FSP; the fall from 482 to 475 is credited as MTM (+10,500).", "Key point: Short → delivers shares on T+1, receiving 7,12,500; the fall from 482 to 475 is a gain of 10,500 to the short."], "reasons": ["Short → delivers shares on T+1, receiving 7,12,500; the fall from 482 to 475 is a gain of 10,500 to the short.", "That's the long's position", "The short gains, not pays", "Stock futures are physically settled"], "notes": ["Easy way to remember: Short futures at expiry = deliver shares."], "id": 412}, "413": {"ch": 7, "chapter": "Clearing, Settlement and Risk Management", "q": "A client holds an index call with strike 17,500; index closes at 17,800 on expiry; lot 50. Final settlement:", "options": ["Delivery of index stocks worth Rs 8,90,000", "Cash credit of Rs 15,000 on T+1", "Cash credit of Rs 8,75,000", "Nothing, as options expire"], "answer": 1, "why": ["Workbook Example 3: index options are cash settled: (17,800 − 17,500) × 50 = 15,000 on T+1.", "Working: Index options are cash settled: (17,800 − 17,500) × 50 = 15,000 on T+1."], "reasons": ["No delivery for index options", "Index options are cash settled: (17,800 − 17,500) × 50 = 15,000 on T+1.", "That's strike × lot", "ITM options pay out"], "notes": ["Easy way to remember: Index option = cash intrinsic value."], "id": 413}, "414": {"ch": 7, "chapter": "Clearing, Settlement and Risk Management", "q": "Mr P is long 1 lot of a stock call, strike Rs 475, lot 1,500; stock closes at Rs 510 on expiry. The exercise settlement value and his obligation are:", "options": ["Pay Rs 7,12,500 (strike × lot) and take delivery of 1,500 shares", "Rs 52,500 received in cash", "Pay Rs 7,65,000 and take delivery", "Deliver 1,500 shares"], "answer": 0, "why": ["Workbook Example 4: ITM stock options are physically settled; exercise settlement value = strike × lot = 475 × 1,500.", "Working: ITM stock options are physically settled at the STRIKE price: 475 × 1,500 = 7,12,500."], "reasons": ["ITM stock options are physically settled at the STRIKE price: 475 × 1,500 = 7,12,500.", "Stock options aren't cash settled", "Uses the closing price instead of strike", "A long call receives shares"], "notes": ["Easy way to remember: Stock option delivery happens at the STRIKE."], "id": 414}, "415": {"ch": 7, "chapter": "Clearing, Settlement and Risk Management", "q": "A client who is assigned a SHORT ITM stock call must have:", "options": ["Funds equal to strike × lot", "Shares equal to the lot size to deliver", "Nothing — it's cash settled", "A long put position"], "answer": 1, "why": ["The workbook: short ITM call = sell obligation; treated like long ITM put — the client must hold shares equal to the lot size.", "Key point: Short ITM call assignment = sell obligation → must deliver shares (treated like a long ITM put)."], "reasons": ["That's for short ITM puts / long ITM calls", "Short ITM call assignment = sell obligation → must deliver shares (treated like a long ITM put).", "Stock options are physically settled", "Unrelated"], "notes": ["Easy way to remember: Short call assigned → deliver shares."], "id": 415}, "416": {"ch": 7, "chapter": "Clearing, Settlement and Risk Management", "q": "The daily premium settlement for options is credited/debited on:", "options": ["T+0", "T+2", "At expiry", "T+1"], "answer": 3, "why": ["The workbook: premium payable/receivable is credited/debited to the clearing member's clearing bank account on T+1.", "Key point: Net premium payable/receivable is settled on T+1 through clearing bank accounts."], "reasons": ["Not T+0", "Not T+2", "Not at expiry", "Net premium payable/receivable is settled on T+1 through clearing bank accounts."], "notes": ["Easy way to remember: Premium settles T+1."], "id": 416}, "417": {"ch": 7, "chapter": "Clearing, Settlement and Risk Management", "q": "Under the net settlement mechanism, Mr A holds a long ITM put (strike 110) and buys the same stock at Rs 101 in the cash market on expiry day. What happens?", "options": ["He must pay Rs 101 on T+1 and later deliver shares separately", "The put is cancelled", "He pays Rs 110", "The obligations are netted: no funds pay-in of Rs 101 or share delivery; he receives the net difference"], "answer": 3, "why": ["Workbook example: cash buy obligation and put delivery obligation are settled on a net basis; available only through the same TM-CM combination and not to institutional investors.", "Key point: Cash buy and put exercise delivery offset; only net funds move. Available only if trading and clearing through the same TM-CM; not for institutional investors."], "reasons": ["That was the earlier rule", "The put isn't cancelled", "He receives, not pays, the strike", "Cash buy and put exercise delivery offset; only net funds move."], "notes": ["Easy way to remember: Net settlement = offset cash and F&O deliveries."], "id": 417}, "418": {"ch": 7, "chapter": "Clearing, Settlement and Risk Management", "q": "SPAN, used for margining in India, was developed by:", "options": ["NSE Clearing", "Chicago Mercantile Exchange", "SEBI", "CBOE"], "answer": 1, "why": ["The workbook: SPAN (Standard Portfolio Analysis of Risk) was designed by the Chicago Mercantile Exchange.", "Key point: Standard Portfolio Analysis of Risk was designed by CME, Chicago."], "reasons": ["NSE Clearing uses it but didn't design it", "Standard Portfolio Analysis of Risk was designed by CME, Chicago.", "SEBI didn't design it", "CBOE didn't design it"], "notes": ["Easy way to remember: SPAN = CME product."], "id": 418}, "419": {"ch": 7, "chapter": "Clearing, Settlement and Risk Management", "q": "SPAN's basic objective is to determine:", "options": ["The average daily profit of a portfolio", "The largest loss a portfolio might reasonably suffer from one day to the next", "The tax liability of a client", "The fair value of options"], "answer": 1, "why": ["The workbook: SPAN determines \"the largest possible loss that a portfolio might reasonably be expected to suffer from one day to the next\".", "Key point: SPAN sets initial margin to cover the one-day worst reasonable loss, using risk arrays."], "reasons": ["Not average profit", "SPAN sets initial margin to cover the one-day worst reasonable loss, using risk arrays.", "Not tax", "Not fair value"], "notes": ["Easy way to remember: SPAN = worst reasonable one-day loss."], "id": 419}, "420": {"ch": 7, "chapter": "Clearing, Settlement and Risk Management", "q": "Initial margin in equity derivatives is based on:", "options": ["95% VaR over one day for all products", "99% VaR over 10 days", "99% VaR over a one-day horizon; for futures, computed over a two-day horizon", "Fixed 10% of contract value"], "answer": 2, "why": ["The workbook: initial margin is based on 99% VaR over a one-day horizon; for futures, over a two-day horizon since MTM may not be collected before next day's trading.", "Key point: 99% one-day VaR; futures use two days since MTM may not be collected before the next day's trading begins."], "reasons": ["95% is wrong", "10 days is wrong", "99% one-day VaR; futures use two days since MTM may not be collected before the next day's trading begins.", "Not a fixed %"], "notes": ["Easy way to remember: 99% VaR, 1 day (futures 2 days)."], "id": 420}, "421": {"ch": 7, "chapter": "Clearing, Settlement and Risk Management", "q": "Value-at-risk measures:", "options": ["Value of proprietary portfolio", "Net worth of an investor", "Risk level of a financial portfolio", "Credit rating of an investor"], "answer": 2, "why": ["Workbook sample: VaR measures the risk level of a financial portfolio.", "Key point: VaR estimates the potential loss of a portfolio at a confidence level over a horizon."], "reasons": ["Not the portfolio value", "Not net worth", "VaR estimates the potential loss of a portfolio at a confidence level over a horizon.", "Not credit rating"], "notes": ["Easy way to remember: VaR = how much can I lose."], "id": 421}, "422": {"ch": 7, "chapter": "Clearing, Settlement and Risk Management", "q": "Mark-to-market margins are collected:", "options": ["Weekly", "Daily", "Every 2 days", "Every 3 days"], "answer": 1, "why": ["Workbook sample: MTM margins are collected on a daily basis.", "Key point: MTM profits/losses on futures are settled daily."], "reasons": ["Not weekly", "MTM profits/losses on futures are settled daily.", "Not 2 days", "Not 3 days"], "notes": ["Easy way to remember: MTM = daily."], "id": 422}, "423": {"ch": 7, "chapter": "Clearing, Settlement and Risk Management", "q": "Intraday Crystallised MTM losses (ICMTM) are computed:", "options": ["For both futures and options", "Only for options", "Only for futures contracts, on trades that close out open positions", "Only at end of day"], "answer": 2, "why": ["The workbook: ICMTM is computed only for futures, on trades that close out open positions, based on weighted average prices; it is part of initial margin.", "Key point: ICMTM applies only to futures, is part of initial margin, and is adjusted against liquid assets in real time."], "reasons": ["Not options", "Not options", "ICMTM applies only to futures, is part of initial margin, and is adjusted against liquid assets in real time.", "It's computed intraday"], "notes": ["Easy way to remember: ICMTM = futures only."], "id": 423}, "424": {"ch": 7, "chapter": "Clearing, Settlement and Risk Management", "q": "Delivery margins on physically settled derivatives are levied progressively. The percentage applied at Expiry − 2 EOD is:", "options": ["20%", "40%", "80%", "60%"], "answer": 3, "why": ["The workbook: 20% at E−4 EOD, 40% at E−3, 60% at E−2, 80% at E−1.", "Key point: E−4: 20%, E−3: 40%, E−2: 60%, E−1: 80%."], "reasons": ["E−4", "E−3", "E−1", "Correct — E−2. E−4: 20%, E−3: 40%, E−2: 60%, E−1: 80%."], "notes": ["Easy way to remember: 20-40-60-80 as expiry nears."], "id": 424}, "425": {"ch": 7, "chapter": "Clearing, Settlement and Risk Management", "q": "If early pay-in of securities or funds is made for a position to be settled by delivery:", "options": ["The delivery margin doubles", "The position is cancelled", "MTM is waived", "The position is exempt from delivery margins"], "answer": 3, "why": ["The workbook: positions for which early pay-in of securities or funds is made are exempt from delivery margins.", "Key point: Early pay-in removes settlement risk, so delivery margins are not charged."], "reasons": ["Margins don't double", "Positions aren't cancelled", "MTM isn't waived", "Early pay-in removes settlement risk, so delivery margins are not charged."], "notes": ["Easy way to remember: Pay early → no delivery margin."], "id": 425}, "426": {"ch": 7, "chapter": "Clearing, Settlement and Risk Management", "q": "Short Option Minimum Charge (SOMC) was:", "options": ["Increased in 2024", "Done away with by SEBI vide circular dated February 24, 2020", "Applied only to index options", "Replaced by premium margin"], "answer": 1, "why": ["The workbook: SEBI did away with SOMC vide circular dated February 24, 2020.", "Key point: SEBI discontinued SOMC in February 2020."], "reasons": ["Not increased", "SEBI discontinued SOMC in February 2020.", "It is abolished", "Not replaced by premium margin"], "notes": ["Easy way to remember: SOMC — gone since 2020."], "id": 426}, "427": {"ch": 7, "chapter": "Clearing, Settlement and Risk Management", "q": "Net Option Value is:", "options": ["Deducted from the member's liquid net worth", "Added to the clearing member's liquid net worth", "Settled in cash daily", "Ignored for margining"], "answer": 1, "why": ["The workbook: NOV (long option value − short option value at market) is added to the clearing member's liquid net worth; option MTM is not settled in cash.", "Key point: NOV (long option value − short option value at market) is added to liquid net worth; option MTM is not cash settled daily."], "reasons": ["Not deducted", "NOV (long option value − short option value at market) is added to liquid net worth; option MTM is not cash settled daily.", "Not settled daily in cash", "It is used"], "notes": ["Easy way to remember: NOV adds to liquid net worth."], "id": 427}, "428": {"ch": 7, "chapter": "Clearing, Settlement and Risk Management", "q": "Client securities given as margin must now be provided through:", "options": ["A \"margin pledge\" in the depository system, to the broker's Client Securities Margin Pledge Account", "A power of attorney to the broker", "Physical share certificates", "Transfer of title to the broker's own demat account"], "answer": 0, "why": ["The workbook: collateral can be given only via a 'margin pledge' in the depository system to the TM/CM's Client Securities Margin Pledge Account; title stays with the client.", "Key point: Title stays with the client; the TM can re-pledge to CM and CC only from that account, leaving a full trail."], "reasons": ["Title stays with the client; the TM can re-pledge to CM and CC only from that account, leaving a full trail.", "POA misuse is why the rule changed", "Physical certificates aren't used", "No transfer of title"], "notes": ["Easy way to remember: Pledge, don't transfer."], "id": 428}, "429": {"ch": 7, "chapter": "Clearing, Settlement and Risk Management", "q": "Under the peak margin framework (July 20, 2020 circular), clearing corporations send at least ___ intraday snapshots of client margin requirements.", "options": ["2", "6", "10", "4"], "answer": 3, "why": ["The workbook: clearing corporations send a minimum of 4 snapshots of client-wise margin requirements to TMs/CMs.", "Key point: A minimum of 4 snapshots are sent; the penalty is on the higher of EOD shortfall and peak shortfall."], "reasons": ["Not 2", "Not 6", "Not 10", "A minimum of 4 snapshots are sent; the penalty is on the higher of EOD shortfall and peak shortfall."], "notes": ["Easy way to remember: Four snapshots a day."], "id": 429}, "430": {"ch": 7, "chapter": "Clearing, Settlement and Risk Management", "q": "From August 1, 2022, intraday snapshot margin requirements in derivatives are computed using:", "options": ["Real-time margin parameters", "Previous week's parameters", "End-of-day parameters", "Fixed Beginning-of-Day (BOD) margin parameters"], "answer": 3, "why": ["The workbook: snapshot margins are calculated on fixed Beginning of Day (BOD) margin parameters (SPAN + ELM); the short-margin penalty due to intraday volatility no longer applies.", "Key point: Snapshot margins use fixed BOD parameters (SPAN + ELM), so intraday volatility doesn't trigger short-margin penalties."], "reasons": ["Not real-time parameters", "Not previous week's", "Not EOD", "Snapshot margins use fixed BOD parameters (SPAN + ELM), so intraday volatility doesn't trigger short-margin penalties."], "notes": ["Easy way to remember: BOD margin holds all day."], "id": 430}, "431": {"ch": 7, "chapter": "Clearing, Settlement and Risk Management", "q": "Cross margining is available:", "options": ["Only to institutional investors", "Only across two exchanges", "Only for options", "Across cash and derivatives segments to all categories of participants, for offsetting positions"], "answer": 3, "why": ["The workbook: cross margining is available across cash and derivatives segments to all categories of participants, for positions that offset each other.", "Key point: Offsetting positions in cash and derivatives receive cross margin benefit for all participants."], "reasons": ["All participants, not only institutions", "It's across segments", "Not only options", "Offsetting positions in cash and derivatives receive cross margin benefit for all participants."], "notes": ["Easy way to remember: Offsetting cash + derivatives = cross margin."], "id": 431}, "432": {"ch": 7, "chapter": "Clearing, Settlement and Risk Management", "q": "Client-level position limit for stock derivatives is the higher of:", "options": ["5% of free float or 1% of OI", "20% of MWPL or Rs 500 crore", "1% of free float market cap (in shares) or 5% of OI in all derivatives on that stock", "15% of OI or Rs 7,500 crore"], "answer": 2, "why": ["The workbook: gross open position across all derivatives on a stock ≤ higher of 1% of free float market cap (in shares) or 5% of open interest (in shares).", "Key point: Gross open position across all derivatives on a stock ≤ higher of 1% of free float (shares) or 5% of OI (shares)."], "reasons": ["Numbers reversed", "20% of MWPL is the TM limit", "Gross open position across all derivatives on a stock ≤ higher of 1% of free float (shares) or 5% of OI (shares).", "These are index TM limits"], "notes": ["Easy way to remember: Client: 1% free float or 5% OI."], "id": 432}, "433": {"ch": 7, "chapter": "Clearing, Settlement and Risk Management", "q": "A stock has a free float of 40 crore shares and total derivatives OI of 6 crore shares. The client-level position limit is:", "options": ["30 lakh shares", "6 crore shares", "2 crore shares", "40 lakh shares"], "answer": 3, "why": ["Client limit = higher of 1% × free float and 5% × OI.", "Working: 1% of 40 crore = 40 lakh; 5% of 6 crore = 30 lakh. Higher = 40 lakh shares."], "reasons": ["30 lakh is the lower value", "6 crore is total OI", "2 crore is not relevant", "40 lakh is higher. 1% of 40 crore = 40 lakh; 5% of 6 crore = 30 lakh."], "notes": ["Easy way to remember: Compute both, take the higher."], "id": 433}, "434": {"ch": 7, "chapter": "Clearing, Settlement and Risk Management", "q": "A stock has 50 crore non-promoter shares. Its MWPL, and the aggregate OI level at which fresh positions are banned, are:", "options": ["10 crore; 9.5 crore", "10 crore; 8 crore", "5 crore; 4.75 crore", "20 crore; 19 crore"], "answer": 0, "why": ["The workbook: MWPL = 20% of non-promoter shares; no fresh positions once aggregate OI exceeds 95% of MWPL; normal trading resumes at 80% or below.", "Working: MWPL = 20% × 50 crore = 10 crore shares. Ban when OI exceeds 95% = 9.5 crore; trading resumes when it falls to 80% (8 crore) or below."], "reasons": ["MWPL = 20% × 50 crore = 10 crore shares.", "8 crore is the resumption level", "Uses 10%", "Uses 40%"], "notes": ["Easy way to remember: MWPL 20%; ban at 95%; resume at 80%."], "id": 434}, "435": {"ch": 7, "chapter": "Clearing, Settlement and Risk Management", "q": "Using the same stock (MWPL 10 crore shares), the trading-member-wise combined F&O position limit is:", "options": ["1 crore shares", "5 crore shares", "9.5 crore shares", "2 crore shares"], "answer": 3, "why": ["The workbook: combined F&O position limit per TM for individual securities = 20% of MWPL.", "Working: TM limit for individual securities = 20% of MWPL = 2 crore shares."], "reasons": ["Uses 10%", "Uses 50%", "That's the ban trigger", "TM limit for individual securities = 20% of MWPL = 2 crore shares."], "notes": ["Easy way to remember: TM stock limit = 20% of MWPL."], "id": 435}, "436": {"ch": 7, "chapter": "Clearing, Settlement and Risk Management", "q": "Trading systems display an alert when a stock's aggregate OI exceeds what percentage of MWPL?", "options": ["50%", "80%", "60%", "95%"], "answer": 2, "why": ["The workbook: an alert is displayed once OI exceeds 60% of MWPL.", "Key point: Alert at 60%; ban above 95%; normal trading resumes at or below 80%."], "reasons": ["Not 50%", "80% is the resumption level", "Alert at 60%; ban above 95%; normal trading resumes at or below 80%.", "95% is the ban level"], "notes": ["Easy way to remember: 60 alert → 95 ban → 80 resume."], "id": 436}, "437": {"ch": 7, "chapter": "Clearing, Settlement and Risk Management", "q": "The trading-member position limit in equity index futures is the higher of:", "options": ["Rs 7,500 crore or 15% of total OI in index futures", "Rs 500 crore or 15% of OI", "Rs 1,500 crore or 10% of OI", "Rs 10,000 crore or 20% of OI"], "answer": 0, "why": ["The workbook: TM limits for index futures (and separately for index options) = higher of Rs 7,500 crore or 15% of total OI.", "Key point: TM limits for index futures (and separately index options) = higher of Rs 7,500 crore or 15% of market OI."], "reasons": ["TM limits for index futures (and separately index options) = higher of Rs 7,500 crore or 15% of market OI.", "Rs 500 crore is the client/FPI index futures floor", "Not in the workbook", "Not in the workbook"], "notes": ["Easy way to remember: TM index = 7,500 cr or 15%."], "id": 437}, "438": {"ch": 7, "chapter": "Clearing, Settlement and Risk Management", "q": "Any person(s) acting in concert holding ___ or more of OI in an index must report it to the exchange/clearing corporation.", "options": ["5%", "15%", "10%", "20%"], "answer": 1, "why": ["The workbook: persons acting in concert who together own 15% or more of OI in a particular index must report it to the exchange/CC; failure is a violation.", "Key point: 15% or more of OI on a particular underlying index must be reported; failure is a violation."], "reasons": ["Not 5%", "15% or more of OI on a particular underlying index must be reported; failure is a violation.", "Not 10%", "Not 20%"], "notes": ["Easy way to remember: 15% of index OI → report."], "id": 438}, "439": {"ch": 7, "chapter": "Clearing, Settlement and Risk Management", "q": "PAN-level position limits for index options (FutEq basis) at end of day are:", "options": ["Net Rs 5,000 crore; Gross Rs 10,000 crore", "Net Rs 1,500 crore; Gross Rs 10,000 crore", "Net Rs 500 crore; Gross Rs 1,500 crore", "Net Rs 10,000 crore; Gross Rs 1,500 crore"], "answer": 1, "why": ["Workbook tables: EOD net FutEq OI Rs 1,500 crore, gross Rs 10,000 crore; intraday net Rs 5,000 crore, gross Rs 10,000 crore.", "Key point: EOD: net Rs 1,500 crore, gross Rs 10,000 crore. Intraday: net Rs 5,000 crore, gross Rs 10,000 crore."], "reasons": ["These are intraday limits", "EOD: net Rs 1,500 crore, gross Rs 10,000 crore.", "Not in the workbook", "Reversed"], "notes": ["Easy way to remember: EOD net 1,500; intraday net 5,000; gross 10,000."], "id": 439}, "440": {"ch": 7, "chapter": "Clearing, Settlement and Risk Management", "q": "Intraday position limits for index derivatives are monitored through at least four random snapshots, including one taken:", "options": ["Between 9:15 and 9:30", "Between 12:00 and 13:00", "Between 14:45 and 15:30", "After market close"], "answer": 2, "why": ["The workbook: monitoring through at least four random snapshots, including one between 14:45 and 15:30.", "Key point: One snapshot must fall in the heightened-activity closing window 14:45–15:30."], "reasons": ["Not the opening", "Not midday", "One snapshot must fall in the heightened-activity closing window 14:45–15:30.", "Not after close"], "notes": ["Easy way to remember: One snapshot near the close."], "id": 440}, "441": {"ch": 7, "chapter": "Clearing, Settlement and Risk Management", "q": "Index futures position limit for FPI Category I, Mutual Funds and Clients is:", "options": ["Higher of 15% of index futures OI or Rs 500 crore", "Higher of 5% of OI or Rs 500 crore", "Higher of 10% of OI or Rs 500 crore", "Rs 7,500 crore flat"], "answer": 0, "why": ["Workbook table: FPI Cat I/MFs/TM-prop/clients — higher of 15% of index futures OI or Rs 500 crore; FPI Cat II (non-individual etc.) 10%; Cat II individuals/family offices/corporates 5%.", "Key point: Cat I FPIs/MFs/TM-prop/clients: 15% or Rs 500 crore. Cat II (other than individuals, family offices, corporates): 10%. Cat II individuals/family offices/corporates: 5%."], "reasons": ["Cat I FPIs/MFs/TM-prop/clients: 15% or Rs 500 crore.", "That's FPI Cat II individuals", "That's FPI Cat II others", "That's the TM limit amount"], "notes": ["Easy way to remember: Cat I 15%, Cat II 10%, Cat II individuals 5%."], "id": 441}, "442": {"ch": 7, "chapter": "Clearing, Settlement and Risk Management", "q": "A client with a credit balance has not traded for 30 calendar days. The TM must:", "options": ["Return the entire credit balance on the next monthly running account settlement date, regardless of the client's chosen cycle", "Keep the funds till the client asks", "Transfer it to the IPF", "Adjust it against brokerage"], "answer": 0, "why": ["The workbook: for inactive clients (30 calendar days), the entire credit balance is returned on the upcoming monthly running account settlement date, regardless of the client's chosen cycle.", "Key point: Inactive for 30 days → full credit balance returned on the upcoming monthly settlement date."], "reasons": ["Inactive for 30 days → full credit balance returned on the upcoming monthly settlement date.", "Must be returned", "Not transferred to IPF", "Not adjusted against brokerage"], "notes": ["Easy way to remember: 30 days idle → money back."], "id": 442}, "443": {"ch": 7, "chapter": "Clearing, Settlement and Risk Management", "q": "The primary objective of the Core Settlement Guarantee Fund is to:", "options": ["Compensate investors for broker fraud", "Fund investor education only", "Guarantee settlement of trades in each segment if a clearing member fails", "Pay STT on behalf of members"], "answer": 2, "why": ["The workbook: Core SGF exists in each segment to guarantee settlement if a CM fails; the Investor Protection Fund compensates investors when defaulter assets fall short.", "Key point: Core SGF funds a defaulting CM's obligations so settlement completes normally. The Investor Protection Fund compensates investors when a defaulting member's assets fall short."], "reasons": ["That's the IPF", "IPF also promotes education", "Core SGF funds a defaulting CM's obligations so settlement completes normally.", "Not STT"], "notes": ["Easy way to remember: SGF guarantees settlement; IPF protects investors."], "id": 443}, "444": {"ch": 7, "chapter": "Clearing, Settlement and Risk Management", "q": "Which SEBI measure became effective on February 1, 2025?", "options": ["Upfront collection of option premium from buyers and removal of calendar spread benefit on expiry day", "Weekly expiries limited to one benchmark index", "Increase in contract size to Rs 15 lakh", "Intraday position limit monitoring"], "answer": 0, "why": ["The workbook: upfront collection of option premium and removal of calendar spread benefits on expiry day — effective Feb 1, 2025.", "Key point: Feb 1, 2025: upfront premium and no calendar spread benefit on expiry day. Nov 20, 2024: contract size, weekly rationalisation, 2% ELM. Apr 1, 2025: intraday monitoring."], "reasons": ["Feb 1, 2025: upfront premium and no calendar spread benefit on expiry day.", "Nov 20, 2024", "Nov 20, 2024", "April 1, 2025"], "notes": ["Easy way to remember: Feb 2025 = upfront premium + no expiry-day spread benefit."], "id": 444}, "445": {"ch": 7, "chapter": "Clearing, Settlement and Risk Management", "q": "An additional Extreme Loss Margin of ___ applies to short options on expiry day (from Nov 20, 2024).", "options": ["1%", "2%", "3%", "5%"], "answer": 1, "why": ["The workbook: from Nov 20, 2024, an additional 2% ELM applies to short options on expiry days.", "Key point: An additional 2% ELM on short options expiring that day covers tail risk from expiry-day speculation."], "reasons": ["Not 1%", "An additional 2% ELM on short options expiring that day covers tail risk from expiry-day speculation.", "Not 3%", "Not 5%"], "notes": ["Easy way to remember: Expiry-day tail risk → +2% ELM."], "id": 445}, "446": {"ch": 7, "chapter": "Clearing, Settlement and Risk Management", "q": "Monthly stock derivative expiries fall on the 29th (current), 30th (next) and 31st (far). On the 29th, which calendar spread still gets margin benefit (circular effective May 05, 2026)?", "options": ["30th vs 31st", "29th vs 30th", "29th vs 31st", "None"], "answer": 0, "why": ["Workbook illustration: on the 29th (current expiry), spreads involving the 29th contract lose the benefit; the 30th–31st spread continues to get it.", "Key point: Spreads involving the contract expiring that day lose the benefit; the 30th–31st spread keeps it."], "reasons": ["Spreads involving the contract expiring that day lose the benefit; the 30th–31st spread keeps it.", "Involves the expiring contract", "Involves the expiring contract", "One spread still qualifies"], "notes": ["Easy way to remember: Only the expiring leg loses the spread benefit."], "id": 446}, "447": {"ch": 7, "chapter": "Clearing, Settlement and Risk Management", "q": "Which is NOT one of the five cyber resiliency goals under SEBI's CSCRF?", "options": ["Anticipate", "Retaliate", "Withstand", "Contain"], "answer": 1, "why": ["The workbook: CSCRF goals — Anticipate, Withstand, Contain, Recover, Evolve.", "Key point: The five goals are Anticipate, Withstand, Contain, Recover and Evolve."], "reasons": ["Listed", "Not listed. The five goals are Anticipate, Withstand, Contain, Recover and Evolve.", "Listed", "Listed"], "notes": ["Easy way to remember: A-W-C-R-E."], "id": 447}, "448": {"ch": 7, "chapter": "Clearing, Settlement and Risk Management", "q": "Under CSCRF, which of the following is NOT listed as a Market Infrastructure Institution?", "options": ["Stock exchanges", "Mutual funds", "Depositories", "KYC Registration Agencies"], "answer": 1, "why": ["The workbook: MIIs under CSCRF are stock exchanges, depositories, clearing corporations, KRAs and QRTAs.", "Key point: MIIs under CSCRF: stock exchanges, depositories, clearing corporations, KRAs and QRTAs."], "reasons": ["Listed", "Mutual funds are not listed as MIIs. MIIs under CSCRF: stock exchanges, depositories, clearing corporations, KRAs and QRTAs.", "Listed", "Listed"], "notes": ["Easy way to remember: MIIs = infrastructure, not fund houses."], "id": 448}, "449": {"ch": 7, "chapter": "Clearing, Settlement and Risk Management", "q": "In the event of a clearing member's violation, the clearing corporation may:", "options": ["Only issue a warning", "Transfer the member's proprietary profits to clients", "Advise withdrawal of membership rights, close out outstanding positions, impose penalties — without notice", "Suspend SEBI registration directly"], "answer": 2, "why": ["The workbook: the CC may advise exchanges to withdraw membership rights, withdraw trading/clearing facilities, close out positions and impose penalties, without notice; such action is final and binding.", "Key point: The CC can advise the exchange to withdraw trading/clearing facilities and close out positions; such action is final and binding."], "reasons": ["Stronger actions are possible", "Not a workbook measure", "The CC can advise the exchange to withdraw trading/clearing facilities and close out positions; such action is final and binding.", "SEBI registration is SEBI's domain"], "notes": ["Easy way to remember: CC can pull the plug without notice."], "id": 449}, "450": {"ch": 8, "chapter": "Legal and Regulatory Environment", "q": "The term \"securities\" is defined in which section of the Securities Contracts (Regulation) Act, 1956?", "options": ["Section 2(a)", "Section 18A", "Section 4", "Section 2(h)"], "answer": 3, "why": ["The workbook: \"The term 'securities' has been defined in the Section 2(h) of SCRA.\"", "Key point: Section 2(h) defines securities. Section 18A validates derivative contracts; Section 4 deals with recognition of exchanges."], "reasons": ["Not 2(a)", "18A validates derivative contracts", "Section 4 is about recognition of exchanges", "Section 2(h) defines securities."], "notes": ["Easy way to remember: 2(h) = securities; 18A = derivatives valid; 4 = recognition."], "id": 450}, "451": {"ch": 8, "chapter": "Legal and Regulatory Environment", "q": "Under SCRA, which of the following is NOT a \"security\"?", "options": ["Units of a mutual fund scheme", "A unit linked insurance policy (ULIP) issued by an insurer", "Government securities", "Security receipts under the SARFAESI Act"], "answer": 1, "why": ["The workbook: securities include MF units, government securities and security receipts, but \"do not include any unit linked insurance policy\" providing combined life-risk and investment benefit.", "Key point: The definition expressly excludes ULIPs that combine life risk cover with investment."], "reasons": ["Included", "Excluded — ULIPs. The definition expressly excludes ULIPs that combine life risk cover with investment.", "Included", "Included"], "notes": ["Easy way to remember: ULIP = insurance, not security."], "id": 451}, "452": {"ch": 8, "chapter": "Legal and Regulatory Environment", "q": "Under Section 18A of SCRA, derivative contracts are legal and valid if they are:", "options": ["Traded on a recognised stock exchange and settled on its clearing house as per its rules and bye-laws", "Registered with RBI", "Approved by the Central Government individually", "Entered into by institutional investors only"], "answer": 0, "why": ["The workbook: Section 18A — derivative contracts are legal and valid if traded on a recognised stock exchange and settled on its clearing house as per its rules and bye-laws.", "Key point: Section 18A requires trading on a recognised exchange and settlement through its clearing house."], "reasons": ["Section 18A requires trading on a recognised exchange and settlement through its clearing house.", "RBI registration isn't the condition", "No individual government approval", "Not limited to institutions"], "notes": ["Easy way to remember: Recognised exchange + its clearing house = legal."], "id": 452}, "453": {"ch": 8, "chapter": "Legal and Regulatory Environment", "q": "Which is NOT a stated purpose of SEBI under the SEBI Act, 1992?", "options": ["Protecting investors' interests", "Setting the repo rate", "Promoting development of the securities market", "Regulating the securities market"], "answer": 1, "why": ["The SEBI Act, 1992 provides for SEBI to protect investors, promote development and regulate the securities market.", "Key point: The repo rate is set by RBI. SEBI's three purposes are protection, development and regulation."], "reasons": ["Listed purpose", "The repo rate is RBI's function. The repo rate is set by RBI.", "Listed purpose", "Listed purpose"], "notes": ["Easy way to remember: SEBI: Protect, Develop, Regulate."], "id": 453}, "454": {"ch": 8, "chapter": "Legal and Regulatory Environment", "q": "As per L.C. Gupta Committee norms, representation of trading/clearing members on the derivatives exchange's governing council is limited to:", "options": ["20%", "40%", "33%", "51%"], "answer": 1, "why": ["The workbook: the derivatives exchange must have a separate governing council, with trading/clearing members limited to a maximum of 40%.", "Key point: Members may form at most 40% of the governing council; the exchange must also have at least 50 members."], "reasons": ["Not 20%", "Members may form at most 40% of the governing council; the exchange must also have at least 50 members.", "Not 33%", "Not 51%"], "notes": ["Easy way to remember: Members ≤ 40% of the council."], "id": 454}, "455": {"ch": 8, "chapter": "Legal and Regulatory Environment", "q": "\"On the Governing Council of the Clearing Corporation of the derivatives segment, broker-members are allowed.\" This statement is:", "options": ["True", "False"], "answer": 1, "why": ["Workbook sample: the statement is False — broker-members are not allowed on the governing council of the clearing corporation.", "Key point: The workbook's sample answer is False — broker-members are not allowed on the clearing corporation's governing council."], "reasons": ["Not true", "Correct — False. The workbook's sample answer is False — broker-members are not allowed on the clearing corporation's governing council."], "notes": ["⚠️ Important: Don't confuse with the exchange's governing council, where members are allowed up to 40%.", "Easy way to remember: Exchange council: members ≤ 40%; CC council: no brokers."], "id": 455}, "456": {"ch": 8, "chapter": "Legal and Regulatory Environment", "q": "A derivatives exchange must have a minimum of how many members?", "options": ["50", "25", "100", "500"], "answer": 0, "why": ["The workbook: \"The Exchange should have a minimum of 50 members.\"", "Key point: The L.C. Gupta framework requires at least 50 members."], "reasons": ["The L.C.", "Not 25", "Not 100", "Not 500"], "notes": ["Easy way to remember: 50 members."], "id": 456}, "457": {"ch": 8, "chapter": "Legal and Regulatory Environment", "q": "While computing a clearing member's net worth, which item is deducted?", "options": ["30% of marketable securities", "Paid-up capital", "Free reserves", "Cash in bank"], "answer": 0, "why": ["The workbook: net worth = capital + free reserves − non-allowable assets, including fixed assets, pledged securities, member's card, unlisted securities, bad deliveries, doubtful debts, prepaid expenses, intangibles, and 30% of marketable securities.", "Key point: Net worth = capital + free reserves − non-allowable assets (fixed assets, pledged securities, member card, unlisted securities, bad deliveries, doubtful debts, prepaid expenses, intangibles, and 30% of marketable securities)."], "reasons": ["Correct — deducted. Net worth = capital + free reserves − non-allowable assets (fixed assets, pledged securities, member card, unlisted securities, bad deliveries, doubtful debts, prepaid expenses, intangibles, and 30% of marketable securities).", "Capital is added", "Reserves are added", "Cash is not deducted"], "notes": ["Easy way to remember: Deduct what can't quickly pay debts."], "id": 457}, "458": {"ch": 8, "chapter": "Legal and Regulatory Environment", "q": "A member's capital is Rs 250 lakh and free reserves Rs 150 lakh. Non-allowable assets: fixed assets Rs 40 lakh, prepaid expenses Rs 10 lakh, and marketable securities of Rs 100 lakh (30% haircut). Net worth for CM eligibility is:", "options": ["Rs 400 lakh", "Rs 320 lakh", "Rs 350 lakh", "Rs 250 lakh"], "answer": 1, "why": ["Apply the workbook formula: capital + free reserves − non-allowable assets (30% haircut on marketable securities).", "Working: 250 + 150 − 40 − 10 − (30% × 100 = 30) = 320 lakh. This meets the Rs 300 lakh requirement."], "reasons": ["Ignores deductions", "400 − 40 − 10 − 30 = 320. 250 + 150 − 40 − 10 − (30% × 100 = 30) = 320 lakh.", "Deducts fixed assets and prepaid expenses but misses the 30% securities haircut", "Deducts too much"], "notes": ["Easy way to remember: Securities haircut = 30%."], "id": 458}, "459": {"ch": 8, "chapter": "Legal and Regulatory Environment", "q": "Trading members must maintain trade confirmation slips and exercise notices for:", "options": ["5 years", "1 year", "3 years", "8 years"], "answer": 0, "why": ["The workbook: TMs maintain trade confirmation slips and exercise notices for 5 years; inspection at least once a year.", "Key point: Records are kept for 5 years; members are inspected by the exchange at least once a year."], "reasons": ["Records are kept for 5 years; members are inspected by the exchange at least once a year.", "Not 1 year", "Not 3 years", "8 years is loss carry-forward"], "notes": ["Easy way to remember: Records 5 years; inspection yearly."], "id": 459}, "460": {"ch": 8, "chapter": "Legal and Regulatory Environment", "q": "A default by a member in the derivatives segment is treated as:", "options": ["A default in that segment only", "A civil dispute only", "A default only if SEBI declares it", "A default in all segments of that exchange and on all exchanges where he is a member"], "answer": 3, "why": ["The workbook: \"A default by a member in the derivatives segment is treated as default in all segments of that exchange and as default on all exchanges where he is a member.\"", "Key point: Default in derivatives is treated as default across all segments and exchanges of that member."], "reasons": ["Not segment-only", "Not merely civil", "No SEBI declaration needed", "Default in derivatives is treated as default across all segments and exchanges of that member."], "notes": ["Easy way to remember: Default anywhere = default everywhere."], "id": 460}, "461": {"ch": 8, "chapter": "Legal and Regulatory Environment", "q": "SEBI-prescribed net worth for a clearing member and a self-clearing member respectively are:", "options": ["Rs 1 crore; Rs 3 crore", "Rs 5 crore; Rs 2 crore", "Rs 3 crore; Rs 1 crore", "Rs 3 crore; no requirement"], "answer": 2, "why": ["The workbook: SEBI net worth Rs 3 crore for clearing members; Rs 1 crore for self-clearing members; none for trading members.", "Key point: CM Rs 3 crore; SCM Rs 1 crore (auditor's certificate every 6 months). SEBI specifies none for trading members."], "reasons": ["Reversed", "Too high", "CM Rs 3 crore; SCM Rs 1 crore (auditor's certificate every 6 months).", "SCMs do have a requirement"], "notes": ["Easy way to remember: CM 3 cr; SCM 1 cr; TM — exchange decides."], "id": 461}, "462": {"ch": 8, "chapter": "Legal and Regulatory Environment", "q": "Every clearing member must maintain a liquid net worth with the exchange/clearing corporation of at least:", "options": ["Rs 10 lakh", "Rs 25 lakh", "Rs 100 lakh", "Rs 50 lakh"], "answer": 3, "why": ["The workbook: every clearing member (both CMs and SCMs) must maintain at least Rs 50 lakh as liquid net worth.", "Key point: Liquid net worth of at least Rs 50 lakh."], "reasons": ["Not 10 lakh", "Not 25 lakh", "Not 100 lakh", "Liquid net worth of at least Rs 50 lakh."], "notes": ["Easy way to remember: Liquid net worth = 50 lakh."], "id": 462}, "463": {"ch": 8, "chapter": "Legal and Regulatory Environment", "q": "A clearing member's total liquid assets must comprise at least ___ cash component.", "options": ["25%", "75%", "50%", "100%"], "answer": 2, "why": ["The workbook: total liquid assets comprise at least 50% cash component; the rest non-cash.", "Key point: At least 50% must be cash component (cash, bank guarantee, FDRs, T-bills, dated G-secs); the rest can be non-cash (approved demat securities)."], "reasons": ["Not 25%", "Not 75%", "At least 50% must be cash component (cash, bank guarantee, FDRs, T-bills, dated G-secs); the rest can be non-cash (approved demat securities).", "Not 100%"], "notes": ["Easy way to remember: At least half in cash."], "id": 463}, "464": {"ch": 8, "chapter": "Legal and Regulatory Environment", "q": "Every trading member must appoint at least ___ approved users who have passed a SEBI-approved certification.", "options": ["One", "Three", "Two", "Five"], "answer": 2, "why": ["The workbook: every trading member must appoint at least two approved users who have passed the certification programme; only approved users operate the terminal.", "Key point: At least two certified approved users; only approved users may operate the derivatives terminal."], "reasons": ["Not one", "Not three", "At least two certified approved users; only approved users may operate the derivatives terminal.", "Not five"], "notes": ["Easy way to remember: Two certified users."], "id": 464}, "465": {"ch": 8, "chapter": "Legal and Regulatory Environment", "q": "A defaulting member's clients' positions could be transferred by the clearing corporation to:", "options": ["Another solvent member", "The exchange", "A suspense account", "An error account"], "answer": 0, "why": ["Workbook sample: the CC can transfer client positions to another solvent member in the event of default.", "Key point: The CC can transfer client positions from a defaulting broker to another member."], "reasons": ["The CC can transfer client positions from a defaulting broker to another member.", "The exchange doesn't hold positions", "Not a suspense account", "Not an error account"], "notes": ["Easy way to remember: Default → move clients to a healthy broker."], "id": 465}, "466": {"ch": 8, "chapter": "Legal and Regulatory Environment", "q": "An exchange outage is not resolved within 1 hour before scheduled market close. SEBI's SOP requires:", "options": ["No change in trading hours", "Trading to close immediately", "All stock exchanges to extend trading hours by one and a half hours that day", "Extension by 30 minutes on the affected exchange only"], "answer": 2, "why": ["Workbook SOP table: if trading doesn't resume at least 1 hour before scheduled close, all exchanges extend trading hours by one and a half hours that day.", "Key point: If normal trading doesn't resume at least 1 hour before close (or outage occurs in the last hour up to 15 minutes before close), all exchanges extend by 1.5 hours."], "reasons": ["That's when normalcy resumes 1+ hour before close", "Trading isn't just closed", "If normal trading doesn't resume at least 1 hour before close (or outage occurs in the last hour up to 15 minutes before close), all exchanges extend by 1.5 hours.", "All exchanges, 1.5 hours"], "notes": ["Easy way to remember: Outage near close → +1.5 hours."], "id": 466}, "467": {"ch": 8, "chapter": "Legal and Regulatory Environment", "q": "During a stock exchange outage, market participants must be informed:", "options": ["Immediately or at least within 15 minutes", "Within 1 hour", "At end of day", "Only after SEBI approval"], "answer": 0, "why": ["The workbook: participants and other MIIs must be informed immediately or at least within 15 minutes; also at least 15 minutes' notice before resumption.", "Key point: Within 15 minutes via broadcast and website; also at least 15 minutes' notice before trading resumes."], "reasons": ["Within 15 minutes via broadcast and website; also at least 15 minutes' notice before trading resumes.", "Too late", "Too late", "No SEBI approval needed to inform"], "notes": ["Easy way to remember: 15 minutes to tell, 15 minutes before restart."], "id": 467}, "468": {"ch": 9, "chapter": "Accounting and Taxation", "q": "Under AS-11, when a forward contract is taken for HEDGING, the premium or discount (difference between spot-rate value and forward-rate value) is:", "options": ["Ignored", "Recognised fully on the contract date", "Amortised over the life of the contract", "Taken to reserves"], "answer": 2, "why": ["The workbook: for hedging forwards, the premium/discount is amortised over the life of the contract; exchange differences go to P&L.", "Key point: For hedging forwards, premium/discount is amortised; for trading/speculative forwards, no premium/discount is recognised — gain/loss is recognised based on year-end forward rates."], "reasons": ["It is not ignored", "Not recognised at once", "For hedging forwards, premium/discount is amortised; for trading/speculative forwards, no premium/discount is recognised — gain/loss is recognised based on year-end forward rates.", "Not taken to reserves"], "notes": ["⚠️ Important: For trading forwards, NO premium/discount is recognised; gains/losses use year-end forward rates.", "Easy way to remember: Hedge → amortise."], "id": 468}, "469": {"ch": 9, "chapter": "Accounting and Taxation", "q": "Mr X buys a futures contract. SPAN margin: Day 1 Rs 50,000; Day 2 Rs 55,000; Day 3 Rs 45,000; Day 4 Rs 47,000. The Day 3 entry is:", "options": ["Initial Margin a/c Dr Rs 45,000; To Bank", "Initial Margin a/c Dr Rs 10,000; To Bank", "Bank a/c Dr Rs 10,000; To Initial Margin a/c", "No entry"], "answer": 2, "why": ["Workbook example: when margin falls from 55,000 to 45,000, Rs 10,000 is refunded — Bank Dr, Initial Margin Cr.", "Key point: Margin falls from 55,000 to 45,000, so Rs 10,000 is refunded: Bank Dr, Initial Margin Cr."], "reasons": ["Records the full balance, not the change", "Reversed entry", "Margin falls from 55,000 to 45,000, so Rs 10,000 is refunded: Bank Dr, Initial Margin Cr.", "An entry is needed"], "notes": ["Easy way to remember: Margin down → refund entry."], "id": 469}, "470": {"ch": 9, "chapter": "Accounting and Taxation", "q": "At the time of entering into an equity index futures contract, in the client's books:", "options": ["No entry for the contract itself; only the initial margin paid is recorded", "The full contract value is recorded as a liability", "The contract is recorded at fair value as an asset", "A provision is created"], "answer": 0, "why": ["The workbook: no entry is passed for recording the contract itself; only initial margin paid is debited to Initial Margin a/c.", "Key point: No payment other than margin occurs at inception, so only Initial Margin a/c is debited."], "reasons": ["No payment other than margin occurs at inception, so only Initial Margin a/c is debited.", "No liability recorded", "Not recorded at fair value", "No provision at inception"], "notes": ["Easy way to remember: Record only what you pay — the margin."], "id": 470}, "471": {"ch": 9, "chapter": "Accounting and Taxation", "q": "The balance in \"Initial Margin – Equity Index Futures Account\" at the balance sheet date is shown under:", "options": ["Current Liabilities", "Fixed Assets", "Reserves", "Current Assets"], "answer": 3, "why": ["The workbook: at the balance sheet date, the Initial Margin account balance is shown separately under Current Assets.", "Key point: It is shown separately under Current Assets; any excess deposit is shown as a deposit under Current Assets."], "reasons": ["Not a liability", "Not fixed assets", "Not reserves", "It is shown separately under Current Assets; any excess deposit is shown as a deposit under Current Assets."], "notes": ["Easy way to remember: Margin is money parked → current asset."], "id": 471}, "472": {"ch": 9, "chapter": "Accounting and Taxation", "q": "If initial margin is provided by bank guarantee instead of cash:", "options": ["No accounting entry, but disclose in notes to accounts", "Debit Initial Margin a/c", "Credit Bank a/c", "Record as contingent asset"], "answer": 0, "why": ["The workbook: where the client provides bank guarantees or lodges securities instead of cash, disclose in notes; no accounting entry.", "Key point: A disclosure in the notes is needed; no accounting entry."], "reasons": ["A disclosure in the notes is needed; no accounting entry.", "No debit", "No credit", "Not a contingent asset"], "notes": ["Easy way to remember: BG → disclose, don't book."], "id": 472}, "473": {"ch": 9, "chapter": "Accounting and Taxation", "q": "At year-end, the Mark-to-Market Margin account on open futures shows a debit (net paid) of Rs 5,000. Following prudence, the client should:", "options": ["Ignore it", "Debit P&L and credit Provision for loss by Rs 5,000", "Credit P&L by Rs 5,000", "Transfer it to reserves"], "answer": 1, "why": ["The workbook: following prudence, create a provision for anticipated loss equal to the debit balance — P&L Dr, Provision Cr.", "Key point: Anticipated losses are provided for. A credit balance (anticipated profit) would be ignored and shown as a current liability."], "reasons": ["Losses aren't ignored", "Anticipated losses are provided for.", "That would book a gain", "Not reserves"], "notes": ["Easy way to remember: Provide for losses."], "id": 473}, "474": {"ch": 9, "chapter": "Accounting and Taxation", "q": "At year-end, the Mark-to-Market Margin account shows a CREDIT balance of Rs 8,000 (net received). Treatment:", "options": ["Recognise Rs 8,000 as income", "Create a provision", "Ignore the anticipated profit; show the credit balance as a current liability", "Adjust against initial margin"], "answer": 2, "why": ["The workbook: anticipated profit is ignored; the credit balance is shown as a current liability.", "Key point: Prudence: anticipated profits are not recognised; the credit balance goes under Current Liabilities and Provisions."], "reasons": ["Not recognised as income", "No provision for gains", "Prudence: anticipated profits are not recognised; the credit balance goes under Current Liabilities and Provisions.", "Not adjusted against margin"], "notes": ["Easy way to remember: Ignore anticipated gains."], "id": 474}, "475": {"ch": 9, "chapter": "Accounting and Taxation", "q": "When one of several outstanding contracts of the same futures series is squared up, the contract price used to compute profit/loss is based on:", "options": ["FIFO", "Weighted average method", "LIFO", "Highest price"], "answer": 1, "why": ["The workbook: if more than one contract is outstanding, the contract price of the squared-up contract is determined using the weighted average method.", "Key point: The weighted average method is prescribed for squared-up futures and for options with the same strike and expiry."], "reasons": ["Not FIFO", "The weighted average method is prescribed for squared-up futures and for options with the same strike and expiry.", "Not LIFO", "Not highest price"], "notes": ["Easy way to remember: Squared up → weighted average."], "id": 475}, "476": {"ch": 9, "chapter": "Accounting and Taxation", "q": "A buyer paid option premium of Rs 40 per unit on 100 units. On the balance sheet date, the prevailing premium is Rs 25. The provision required in the buyer's books is:", "options": ["Rs 2,500", "Rs 4,000", "Nil", "Rs 1,500"], "answer": 3, "why": ["The workbook: in the buyer's books, provide for the amount by which premium paid exceeds the premium prevailing on the balance sheet date.", "Working: Provision = (premium paid − current premium) × units = (40 − 25) × 100 = 1,500. If current premium were higher, the gain would be ignored."], "reasons": ["2,500 is the current premium value", "4,000 is premium paid", "A provision is needed", "(40 − 25) × 100 = 1,500. Provision = (premium paid − current premium) × units = (40 − 25) × 100 = 1,500."], "notes": ["Easy way to remember: Buyer provides for premium drop."], "id": 476}, "477": {"ch": 9, "chapter": "Accounting and Taxation", "q": "A writer received premium of Rs 30 per unit on 50 units. On the balance sheet date, the prevailing premium is Rs 42. Provision in the writer's books:", "options": ["Rs 1,500", "Rs 2,100", "Rs 600", "Nil"], "answer": 2, "why": ["The workbook: in the writer's books, provide for the amount by which the prevailing premium exceeds the premium received.", "Working: Writer provides for (current premium − premium received) × units = (42 − 30) × 50 = 600."], "reasons": ["1,500 is premium received", "2,100 is current premium value", "(42 − 30) × 50 = 600. Writer provides for (current premium − premium received) × units = (42 − 30) × 50 = 600.", "A provision is needed"], "notes": ["Easy way to remember: Writer provides for premium rise."], "id": 477}, "478": {"ch": 9, "chapter": "Accounting and Taxation", "q": "Gains from exchange-traded derivatives for resident Indian traders are taxed as:", "options": ["Speculative income under business income", "Non-speculative business income under \"Profits and Gains of Business or Profession\"", "Short-term capital gains", "Income from other sources"], "answer": 1, "why": ["The workbook: Finance Act 2005 amended Section 43(5), so derivatives on a recognised exchange are not speculative; gains are non-speculative business income.", "Key point: Finance Act 2005 amended Section 43(5) to exclude derivatives on a recognised exchange from \"speculative transactions\"."], "reasons": ["Not speculative since FY 2005-06", "Finance Act 2005 amended Section 43(5) to exclude derivatives on a recognised exchange from \"speculative transactions\".", "That's for FPIs", "Not other sources"], "notes": ["Easy way to remember: Recognised exchange F&O = non-speculative business."], "id": 478}, "479": {"ch": 9, "chapter": "Accounting and Taxation", "q": "A non-speculative F&O business loss that cannot be set off in the same year can be:", "options": ["Set off against salary income", "Carried forward for 8 assessment years against non-speculative business income only", "Carried forward indefinitely", "Not carried forward at all"], "answer": 1, "why": ["The workbook: set off against any other income except salary in the same year; unabsorbed loss carried forward for 8 assessment years against non-speculative business income only.", "Key point: Same-year set-off against any income except salary; carry forward for 8 AYs against non-speculative business income."], "reasons": ["Not against salary", "Same-year set-off against any income except salary; carry forward for 8 AYs against non-speculative business income.", "Not indefinitely", "It can be carried forward"], "notes": ["Easy way to remember: Loss: no salary set-off; 8-year carry forward."], "id": 479}, "480": {"ch": 9, "chapter": "Accounting and Taxation", "q": "For FPIs, gains from derivatives on recognised exchanges are generally taxed as:", "options": ["Business income", "Long-term capital gains", "Speculative gains", "Short-term capital gains"], "answer": 3, "why": ["The workbook: for FPIs, gains/losses are taxable under 'Capital Gains'; since most contracts are up to 3 months, they are generally short-term.", "Key point: FPIs are taxed under Capital Gains; since most contracts mature within 3 months, gains are short-term."], "reasons": ["Not business income for FPIs", "Not long-term", "Not speculative", "FPIs are taxed under Capital Gains; since most contracts mature within 3 months, gains are short-term."], "notes": ["Easy way to remember: FPI F&O = STCG."], "id": 480}, "481": {"ch": 9, "chapter": "Accounting and Taxation", "q": "An individual's F&O turnover is Rs 1.5 crore and he opts for presumptive taxation under Section 44AD. His deemed income is:", "options": ["Rs 9 lakh", "Rs 6 lakh", "Rs 12 lakh", "Rs 15 lakh"], "answer": 0, "why": ["The workbook: under Section 44AD (turnover ≤ Rs 2 crore), gains are assessed at 6% of turnover without deductions.", "Working: 6% of turnover = 6% × 1.5 crore = Rs 9 lakh (allowed when turnover ≤ Rs 2 crore; no expense deductions)."], "reasons": ["6% × 1.5 crore = 9 lakh. 6% of turnover = 6% × 1.5 crore = Rs 9 lakh (allowed when turnover ≤ Rs 2 crore; no expense deductions).", "4% of turnover", "8% of turnover", "10% of turnover"], "notes": ["Easy way to remember: Presumptive = 6% of turnover."], "id": 481}, "482": {"ch": 9, "chapter": "Accounting and Taxation", "q": "Tax audit under Section 44AB(a) is mandatory, regardless of profit or loss, when F&O turnover exceeds:", "options": ["Rs 1 crore", "Rs 10 crore", "Rs 2 crore", "Rs 5 crore"], "answer": 1, "why": ["Workbook table: audit mandatory if turnover exceeds Rs 10 crore; between Rs 2–10 crore with >95% digital transactions, not required.", "Key point: Above Rs 10 crore, audit is mandatory. Between Rs 2–10 crore with >95% digital transactions, it is not required."], "reasons": ["Not 1 crore", "Above Rs 10 crore, audit is mandatory.", "2 crore is the 44AD limit", "Not 5 crore"], "notes": ["Easy way to remember: Above 10 crore → audit."], "id": 482}, "483": {"ch": 9, "chapter": "Accounting and Taxation", "q": "For STT purposes, each futures trade is valued at ___ and each option trade at ___.", "options": ["Contract value; strike price", "Settlement price; intrinsic value", "Spot price; notional value", "Actual traded price; premium"], "answer": 3, "why": ["The workbook: each futures trade is valued at actual traded price and option trade at premium; on exercise, STT is on settlement price.", "Key point: Futures at traded price; options at premium. For exercised ITM options, STT applies on settlement price."], "reasons": ["Not contract value/strike", "Not settlement/IV", "Not spot/notional", "Futures at traded price; options at premium."], "notes": ["Easy way to remember: Futures → price; options → premium."], "id": 483}, "484": {"ch": 10, "chapter": "Sales Practices and Investor Protection Services", "q": "A broker's sales agent may call a prospective client, unless requested otherwise by the customer, only between:", "options": ["8 am and 10 pm", "10 am and 6 pm", "Any time", "9 am and 8 pm"], "answer": 3, "why": ["The workbook: \"Sales Agents will in any event only call between 9 am and 8 pm, unless it is at the customer's request.\"", "Key point: Calls only between 9 am and 8 pm unless at the customer's request."], "reasons": ["Too wide", "Too narrow", "Not any time", "Calls only between 9 am and 8 pm unless at the customer's request."], "notes": ["Easy way to remember: 9 to 8."], "id": 484}, "485": {"ch": 10, "chapter": "Sales Practices and Investor Protection Services", "q": "A broker makes excessive trades in a client's account mainly to earn commission. This is called:", "options": ["Churning", "Front running", "Circular trading", "Spoofing"], "answer": 0, "why": ["The workbook: churning is excessive, unnecessary trades in customer accounts for the sole purpose of generating commissions.", "Key point: Churning = unnecessary, excessive trades to generate commissions. Clients should review monthly statements for abnormal activity."], "reasons": ["Churning = unnecessary, excessive trades to generate commissions.", "Not front running", "Not circular trading", "Not spoofing"], "notes": ["Easy way to remember: Churning = commission farming."], "id": 485}, "486": {"ch": 10, "chapter": "Sales Practices and Investor Protection Services", "q": "A broker advises a low-risk senior citizen to trade options and penny stocks. This is an example of:", "options": ["Churning", "Unsuitable investment recommendation", "Insider trading", "Market manipulation"], "answer": 1, "why": ["The workbook's example of an unsuitable recommendation: a broker advising a senior citizen with low risk tolerance to deal in futures, options or penny stocks.", "Key point: The product doesn't match the client's objectives and risk profile."], "reasons": ["Not churning", "The product doesn't match the client's objectives and risk profile.", "Not insider trading", "Not manipulation"], "notes": ["Easy way to remember: Product must fit the person."], "id": 486}, "487": {"ch": 10, "chapter": "Sales Practices and Investor Protection Services", "q": "As per the SEBI study displayed in risk disclosures, how many individual F&O traders incurred net losses?", "options": ["5 out of 10", "7 out of 10", "99 out of 100", "9 out of 10"], "answer": 3, "why": ["Workbook risk disclosure facts: 9 out of 10 individual F&O traders incurred net losses; average loss ~Rs 50,000; loss makers spent an extra 28% of losses on transaction costs.", "Key point: 9 of 10 lost; average loss ~Rs 50,000; loss makers spent an additional 28% of losses on transaction costs; profit makers spent 15–50% of profits on costs."], "reasons": ["Not 5", "Not 7", "Not 99", "9 of 10 lost; average loss ~Rs 50,000; loss makers spent an additional 28% of losses on transaction costs; profit makers spent 15–50% of profits on costs."], "notes": ["Easy way to remember: 9 of 10 lose."], "id": 487}, "488": {"ch": 10, "chapter": "Sales Practices and Investor Protection Services", "q": "Brokers must maintain P&L data of individual F&O clients (including HUFs and NRIs) and retain it for at least:", "options": ["1 year", "3 years", "8 years", "5 years"], "answer": 3, "why": ["The workbook: brokers must maintain P&L data of individual clients (including HUFs and NRIs) and retain it for at least five years.", "Key point: At least five years, in a prescribed format."], "reasons": ["Not 1", "Not 3", "Not 8", "At least five years, in a prescribed format."], "notes": ["Easy way to remember: P&L data = 5 years."], "id": 488}, "489": {"ch": 10, "chapter": "Sales Practices and Investor Protection Services", "q": "Which is NOT one of the three specific parameters of the Client Due Diligence process under AML procedures?", "options": ["Policy for acceptance of clients", "Procedure for identifying clients", "Transaction monitoring and suspicious transaction reporting", "Guaranteeing minimum returns to clients"], "answer": 3, "why": ["The workbook: written AML procedures must include client acceptance policy, client identification procedure, and transaction monitoring/STR.", "Key point: The three parameters are client acceptance policy, client identification procedure and transaction monitoring/STR."], "reasons": ["Listed", "Listed", "Listed", "Returns can never be guaranteed. The three parameters are client acceptance policy, client identification procedure and transaction monitoring/STR."], "notes": ["Easy way to remember: Accept, Identify, Monitor."], "id": 489}, "490": {"ch": 10, "chapter": "Sales Practices and Investor Protection Services", "q": "In the KYC process, Politically Exposed Persons (PEPs) of foreign origin are classified as:", "options": ["High Net-worth Clients", "Institutional Clients", "Clients of Special Category (CSC)", "Retail Clients"], "answer": 2, "why": ["Workbook sample: PEPs are Clients of Special Category.", "Key point: CSC includes non-residents, HNIs, trusts/NGOs, PEPs, non-face-to-face clients, clients in high-risk countries etc."], "reasons": ["HNI is a separate CSC item", "Not institutional", "CSC includes non-residents, HNIs, trusts/NGOs, PEPs, non-face-to-face clients, clients in high-risk countries etc.", "Not retail"], "notes": ["Easy way to remember: PEP = CSC."], "id": 490}, "491": {"ch": 10, "chapter": "Sales Practices and Investor Protection Services", "q": "Which document is MANDATORY for identity proof of an individual under KYC?", "options": ["Passport", "Aadhaar", "PAN card", "Voter ID"], "answer": 2, "why": ["The workbook: PAN card is mandatory; passport, voter ID, driving licence, Aadhaar etc. are other acceptable documents.", "Key point: PAN is mandatory; the others are among acceptable supporting documents."], "reasons": ["Optional", "Optional", "PAN is mandatory; the others are among acceptable supporting documents.", "Optional"], "notes": ["Easy way to remember: No PAN, no account."], "id": 491}, "492": {"ch": 10, "chapter": "Sales Practices and Investor Protection Services", "q": "In-person verification (IPV) is NOT required when:", "options": ["The client is a senior citizen", "The client provides a telephone bill", "The broker is a discount broker", "KYC is completed through Aadhaar authentication of UIDAI, or online with documents via DigiLocker/verifiable sources"], "answer": 3, "why": ["The workbook: IPV isn't required when KYC is completed through Aadhaar authentication of UIDAI, or when KYC is submitted online with documents via DigiLocker/other verifiable source.", "Key point: These two cases exempt IPV. Video IPV is available for individuals doing e-KYC."], "reasons": ["Age isn't an exemption", "A telephone bill isn't an exemption", "Broker type isn't an exemption", "These two cases exempt IPV."], "notes": ["Easy way to remember: Aadhaar or DigiLocker → no IPV."], "id": 492}, "493": {"ch": 10, "chapter": "Sales Practices and Investor Protection Services", "q": "The Unique Client Code (UCC) is:", "options": ["The client's demat account number", "The ISIN of the security", "An exclusive client identifier allotted on onboarding, linked to PAN, and mapped to demat accounts", "The broker's SEBI registration number"], "answer": 2, "why": ["The workbook: UCC is allotted on onboarding, linked to PAN, serves as exclusive client identification, and is mapped to demat accounts.", "Key point: UCC is linked to PAN and mapped to demat accounts to detect diversion of client securities."], "reasons": ["Not the demat number", "Not ISIN", "UCC is linked to PAN and mapped to demat accounts to detect diversion of client securities.", "Not the broker's number"], "notes": ["Easy way to remember: UCC = client's exchange ID."], "id": 493}, "494": {"ch": 10, "chapter": "Sales Practices and Investor Protection Services", "q": "Suspicious transactions under AML/CFT regulations must be reported to:", "options": ["Financial Intelligence Unit – India (FIU-IND)", "SEBI", "Reserve Bank of India", "Central Vigilance Commission"], "answer": 0, "why": ["Workbook sample: suspicious transactions are reported to the Financial Intelligence Unit – India (FIU-IND).", "Key point: STRs go to FIU-IND."], "reasons": ["STRs go to FIU-IND.", "Not SEBI", "Not RBI", "Not CVC"], "notes": ["Easy way to remember: STR → FIU-IND."], "id": 494}, "495": {"ch": 10, "chapter": "Sales Practices and Investor Protection Services", "q": "After an employee flags a client's transaction as suspicious, the intermediary should:", "options": ["Inform the client immediately", "Close the account at once in all cases", "Report internally to the Money Laundering Control Officer and continue dealing as normal without tipping off the client", "Reverse the transaction"], "answer": 2, "why": ["The workbook: notify the Money Laundering Control Officer immediately; continue dealing normally; the client must not be told; suspension only in exceptional circumstances.", "Key point: The client must not be told; accounts are suspended only in exceptional circumstances."], "reasons": ["Tipping off is prohibited", "Not in all cases", "The client must not be told; accounts are suspended only in exceptional circumstances.", "No reversal"], "notes": ["Easy way to remember: Report quietly, act normally."], "id": 495}, "496": {"ch": 10, "chapter": "Sales Practices and Investor Protection Services", "q": "A blind investor cannot blink for the e-KYC \"proof of liveliness\" test. The intermediary should:", "options": ["Use alternative parameters such as facial expressions, head nods or showing an OTP on video", "Reject the application", "Insist on physical KYC only", "Allow trading without KYC"], "answer": 0, "why": ["The workbook: after the Supreme Court judgment (April 30, 2025), intermediaries may use alternate parameters like facial expressions, nodding, showing OTP on screen, real-time video etc.", "Key point: After the Supreme Court judgment of April 30, 2025, digital KYC must be accessible to persons with disabilities."], "reasons": ["After the Supreme Court judgment of April 30, 2025, digital KYC must be accessible to persons with disabilities.", "Rejection isn't allowed", "Digital KYC must stay available", "KYC is still needed"], "notes": ["Easy way to remember: Accessible KYC — adapt the test."], "id": 496}, "497": {"ch": 10, "chapter": "Sales Practices and Investor Protection Services", "q": "Under SCORES, the entity concerned must resolve a complaint within:", "options": ["21 days", "7 days", "15 days", "30 days"], "answer": 0, "why": ["The workbook: the entity must resolve the complaint within 21 days after receiving intimation from SEBI under SCORES.", "Key point: The entity must resolve within 21 days of receiving intimation from SEBI via SCORES and upload an Action Taken Report."], "reasons": ["The entity must resolve within 21 days of receiving intimation from SEBI via SCORES and upload an Action Taken Report.", "Not 7", "Not 15", "Not 30"], "notes": ["Easy way to remember: SCORES = 21 days."], "id": 497}, "498": {"ch": 10, "chapter": "Sales Practices and Investor Protection Services", "q": "Under the SMART ODR process, if conciliation fails within ___ calendar days, the investor may pursue online arbitration; the market participant must pay under the arbitral award within ___ days.", "options": ["21; 15", "15; 21", "30; 30", "7; 3"], "answer": 0, "why": ["The workbook: MII review within 21 days; conciliation within 21 calendar days; then online arbitration; payment within 15 calendar days of the award.", "Key point: MII review ≤ 21 days, conciliation ≤ 21 days, then arbitration; payment within 15 calendar days of the award."], "reasons": ["MII review ≤ 21 days, conciliation ≤ 21 days, then arbitration; payment within 15 calendar days of the award.", "Reversed", "Not 30/30", "Not 7/3"], "notes": ["Easy way to remember: 21 review, 21 conciliation, 15 to pay."], "id": 498}, "499": {"ch": 10, "chapter": "Sales Practices and Investor Protection Services", "q": "A party wishing to challenge an ODR arbitral award under Section 34 must submit its intention within:", "options": ["3 days", "7 calendar days", "15 days", "3 months"], "answer": 1, "why": ["The workbook: submit intention to challenge under Section 34 within 7 calendar days; if no stay within 3 months, comply fully.", "Key point: Intention to challenge within 7 calendar days; if no stay is granted within 3 months, the award must be complied with fully."], "reasons": ["Not 3 days", "Intention to challenge within 7 calendar days; if no stay is granted within 3 months, the award must be complied with fully.", "Not 15 days", "3 months is the stay window"], "notes": ["Easy way to remember: 7 days to signal a challenge."], "id": 499}, "500": {"ch": 10, "chapter": "Sales Practices and Investor Protection Services", "q": "SEBI-regulated entities and their agents on social media must disclose their registered name and registration number:", "options": ["On the home page of their social media handles and at the beginning of each securities-market video/content", "Only in their annual report", "Only on request", "Only to SEBI"], "answer": 0, "why": ["The workbook: REs and agents must prominently disclose their registered name and registration number on their social media home page and at the beginning of each securities market video/content.", "Key point: This helps investors distinguish registered entities' content from unregistered persons."], "reasons": ["This helps investors distinguish registered entities' content from unregistered persons.", "Not only annual report", "Not only on request", "Not only to SEBI"], "notes": ["Easy way to remember: Show your registration on every post.", "Quick Answer Key"], "id": 500}};
